/**
 * What every primitive of audio/ui shares and the kernel does not do: parts
 * named in kebab case, a value reported as `onValueChange` and
 * `onValueCommitted`, one pointer gesture at a time, and a native input
 * hidden from sight. The primitives import it from `../primitive`.
 */
import {
  bindDrag,
  type ChangeSource,
  createChange,
  definePrimitive as definePrimitiveOf,
  dispatch,
  type PointerSample,
  type PrimitiveContext,
} from "@ui-sdk/core";

/** A boolean as a data attribute: present and empty, or absent. */
export const flag = (on: boolean) => (on ? "" : undefined);

/** What a change reports to `onValueChange`, beside the value. */
export interface ChangeDetails {
  cancel: () => void;
  event?: Event;
  /** The point or segment that moved, for a control that has several. */
  index?: number;
  reason: string;
  source?: string;
}

/** What a commit reports to `onValueCommitted`, beside the value. */
export interface CommitDetails {
  event?: Event;
  index?: number;
  reason: string;
}

/** How a native input is hidden while it keeps the focus, the keys and the name. */
export const VISUALLY_HIDDEN = {
  border: "0",
  "clip-path": "inset(50%)",
  height: "1px",
  margin: "-1px",
  overflow: "hidden",
  padding: "0",
  position: "absolute",
  "white-space": "nowrap",
  width: "1px",
};

/**
 * How a change came about, when its event says. The kernel reads it from
 * input it tracks, so the first interaction would report "programmatic"
 * without this. With no event, the kernel decides, and an agent's change
 * stays the agent's.
 */
export function sourceOf(event?: Event): ChangeSource | undefined {
  if (typeof PointerEvent !== "undefined" && event instanceof PointerEvent) {
    return event.pointerType === "touch" || event.pointerType === "pen"
      ? event.pointerType
      : "mouse";
  }
  if (event instanceof MouseEvent) {
    return "mouse";
  }
  if (event instanceof KeyboardEvent) {
    return "keyboard";
  }
}

/** A change or a commit's details: the reason, the event, and who caused it when the event says. */
function detailsOf(reason: string, event?: Event, extra?: object) {
  const source = sourceOf(event);
  return { event, reason, ...(source ? { source } : {}), ...extra };
}

/**
 * How a primitive whose state holds a `value` reports it: `report` fires
 * `onValueChange` and keeps the value unless an app refused it, `commit`
 * fires `onValueCommitted`, and `setAtOnce` does both, for a change that is
 * over as soon as it is made (a key, a typed value, the wheel, a reset). It
 * skips a value `same` finds equal to the one `displayed` shows; with no
 * `same`, every value is reported, even an unchanged one. `extra` goes into
 * the details, such as the `index` of the point that moved.
 */
export function createReporter<State extends { value: Value }, Value>(
  context: PrimitiveContext<any, State, any>,
  displayed: (state: State) => Value,
  same?: (a: Value, b: Value) => boolean
) {
  const change = createChange(context);
  const state = () => context.store.get() as State;
  const commit = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    dispatch(
      context,
      "onValueCommitted",
      value,
      detailsOf(reason, event, extra)
    );
  };
  const report = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) =>
    change("value", value as never, detailsOf(reason, event, extra) as never);
  const setAtOnce = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    if (same?.(value, displayed(state()))) {
      return;
    }
    if (report(value, reason, event, extra)) {
      commit(value, reason, event, extra);
    }
  };
  return { commit, report, setAtOnce, state };
}

/** Two numbers as one text: a comma between them, or a semicolon where the comma is the decimal mark. */
export function formatPair(formatter: Intl.NumberFormat, a: number, b: number) {
  const decimalComma = formatter
    .formatToParts(1.5)
    .some((part) => part.type === "decimal" && part.value === ",");
  return `${formatter.format(a)}${decimalComma ? "; " : ", "}${formatter.format(b)}`;
}

/** Where in an interval a curve is checked against its chord, how many times an interval may be halved, and a ceiling on the vertices of one curve. */
const PROBES = [0.25, 0.5, 0.75];
const MAX_DEPTH = 8;
const MAX_SAMPLES = 4096;

/**
 * The vertices of a polyline that draws `f(t)` for `t` from 0 to 1 without
 * straying more than `tolerance` from it: it starts from `grid` and halves
 * every interval whose curve leaves its chord. `width` is how wide `t` from 0
 * to 1 spans in the box the curve is drawn in.
 */
export function adaptiveSamples(
  f: (t: number) => number,
  grid: readonly number[],
  tolerance: number,
  width = 1
) {
  const samples: [number, number][] = [];
  let budget = MAX_SAMPLES - grid.length;
  const refine = (
    from: number,
    start: number,
    to: number,
    end: number,
    depth: number
  ) => {
    if (depth >= MAX_DEPTH || budget <= 0) {
      return;
    }
    let stray = 0;
    let middle = Number.NaN;
    for (const probe of PROBES) {
      const value = f(from + (to - from) * probe);
      stray = Math.max(
        stray,
        Math.abs(value - (start + (end - start) * probe))
      );
      if (probe === 0.5) {
        middle = value;
      }
    }
    const slope = (end - start) / ((to - from) * width);
    if (stray / Math.sqrt(1 + slope * slope) <= tolerance) {
      return;
    }
    const half = (from + to) / 2;
    budget -= 1;
    refine(from, start, half, middle, depth + 1);
    samples.push([half, middle]);
    refine(half, middle, to, end, depth + 1);
  };
  const values = grid.map(f);
  grid.forEach((t, index) => {
    const value = values[index] ?? 0;
    samples.push([t, value]);
    const next = grid[index + 1];
    if (next !== undefined) {
      refine(t, value, next, values[index + 1] ?? 0, 0);
    }
  });
  return samples;
}

/**
 * What a change reports: why it happened (`reason`), the event behind it,
 * and `cancel()` to refuse the change.
 */
export interface ChangeEventDetails<Reason extends string, E extends Event> {
  cancel: () => void;
  event: E;
  readonly isCanceled: boolean;
  reason: Reason;
}

/** What a commit reports once a gesture ends: why it happened and the event behind it. */
export interface CommitEventDetails<Reason extends string, E extends Event> {
  event: E;
  reason: Reason;
}

/** The details of a change for `reason` and `event`, with `cancel()` to refuse it. */
export function createChangeEventDetails<
  Reason extends string,
  E extends Event,
>(reason: Reason, event: E): ChangeEventDetails<Reason, E> {
  let canceled = false;
  return {
    cancel: () => {
      canceled = true;
    },
    event,
    get isCanceled() {
      return canceled;
    },
    reason,
  };
}

/**
 * One pointer at a time on a control: while one drags, a press from another is
 * ignored, and the same pointer pressing again means its release was missed,
 * so the drag it left ends there. Moves arrive at most once per frame, each
 * with where the pointer was at the last one.
 */
export function createPointerLock() {
  type Held = {
    end: (event: PointerEvent) => void;
    pointerId: number;
    stop: () => void;
  };
  let held: Held | null = null;
  return {
    claim: (event: PointerEvent) => {
      if (!held) {
        return true;
      }
      if (held.pointerId !== event.pointerId) {
        return false;
      }
      const stale = held;
      held = null;
      stale.stop();
      stale.end(event);
      return true;
    },
    follow: (
      target: Element,
      down: PointerEvent,
      move: (event: PointerEvent, from: { x: number; y: number }) => void,
      end: (event: PointerEvent) => void
    ) => {
      let last = { x: down.clientX, y: down.clientY };
      const entry: Held = {
        end,
        pointerId: down.pointerId,
        stop: () => undefined,
      };
      held = entry;
      entry.stop = bindDrag(target as HTMLElement, down, {
        onEnd: (event) => {
          if (held === entry) {
            held = null;
          }
          end(event);
        },
        onMove: ({ event }) => {
          const from = last;
          last = { x: event.clientX, y: event.clientY };
          move(event, from);
        },
      });
    },
  };
}

/**
 * A value that changes outside the framework, in the shape of an external
 * store: `subscribe` registers a listener called on each change, and
 * `getSnapshot` returns the current value. What a primitive's `source` reads
 * from, so that following a signal costs no render.
 */
export interface Source<Value> {
  getSnapshot: () => Value;
  subscribe: (listener: () => void) => () => void;
}

/** A source that also takes values: what `createSource` returns. */
export interface WritableSource<Value> extends Source<Value> {
  /** Publishes a value. Subscribers are told every time, so the same array, updated in place, can be published again. */
  set: (value: Value) => void;
}

/**
 * A source you push to yourself, from an audio callback, a WebSocket, a worker
 * or a test: call `set` with each new reading, and whatever reads the source
 * follows.
 */
export function createSource<Value>(initial: Value): WritableSource<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    getSnapshot: () => value,
    set: (next) => {
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

/** A value the primitive holds and its parts read outside any render. */
export interface Store<Value> {
  get: () => Value;
  set: (next: Value) => void;
  subscribe: (listener: () => void) => () => void;
}

/** A store holding `initial`: `set` tells every listener, unless the value is the same one. */
export function createStore<Value>(initial: Value): Store<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next) => {
      if (Object.is(next, value)) {
        return;
      }
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/** What a gesture hears, from the press that started it to its release. */
export interface GestureHandlers<Data> {
  /** The pointer lifted, or the browser took it over (`canceled`). */
  onEnd: (event: PointerEvent, data: Data, canceled: boolean) => void;
  /** At most once per frame, with the latest pointer event. */
  onMove: (event: PointerEvent, data: Data, sample: PointerSample) => void;
}

/**
 * A primitive's pointer gestures, one at a time. Call `accepts` first, before
 * the primitive's own guards: another pointer pressing while a gesture runs
 * is refused, so a second finger does not take the gesture over, and the
 * same pointer pressing again means its release was missed, so its gesture
 * ends there, through `onStale`. A gesture carries `data` of its own, read
 * back by `active`, and stops when the primitive is destroyed.
 */
export function createGestures<Data>(context: {
  onDestroy: (cleanup: () => void) => void;
}) {
  type Running = { data: Data; pointerId: number; stop: () => void };
  let running: Running | null = null;
  context.onDestroy(() => running?.stop());
  return {
    /** Whether `event` may start a gesture, ending a stale one of the same pointer first. */
    accepts(event: PointerEvent, onStale?: (data: Data) => void) {
      const stale = running;
      if (!stale) {
        return true;
      }
      if (stale.pointerId !== event.pointerId) {
        return false;
      }
      running = null;
      stale.stop();
      onStale?.(stale.data);
      return true;
    },
    /** The data of the gesture that runs, if any. */
    active: () => running?.data ?? null,
    /** Follows the press on `el` until it lifts. */
    start(
      el: HTMLElement,
      event: PointerEvent,
      data: Data,
      handlers: GestureHandlers<Data>
    ) {
      running?.stop();
      const entry: Running = {
        data,
        pointerId: event.pointerId,
        stop: () => undefined,
      };
      running = entry;
      entry.stop = bindDrag(el, event, {
        onEnd: (end, canceled) => {
          if (running === entry) {
            running = null;
          }
          handlers.onEnd(end, data, canceled);
        },
        onMove: (sample) => handlers.onMove(sample.event, data, sample),
      });
    },
  };
}

const KEBAB = /([a-z0-9])([A-Z])/g;
const kebab = (name: string) => name.replace(KEBAB, "$1-$2").toLowerCase();

/**
 * The part a primitive draws names itself in `data-slot`, in kebab case
 * (`xypad-input-x`, `piano-roll-note`), the names the styles and the docs
 * select: the kernel writes the slot's key as it is (`xypad-inputX`). A
 * component that gives its own name to a part (`timeline-time-selection`)
 * keeps it.
 */
function nameSlots(name: string, slots: Record<string, any>) {
  const prefix = kebab(name);
  for (const [key, definition] of Object.entries(slots)) {
    const fallback = key === "root" ? prefix : `${prefix}-${kebab(key)}`;
    const { attrs } = definition;
    definition.attrs = (state: unknown, context: { props?: object }) => ({
      ...attrs?.(state, context),
      "data-slot":
        (context.props as Record<string, string> | undefined)?.["data-slot"] ??
        fallback,
    });
    definition.props = { ...definition.props, "data-slot": "string" };
  }
  return slots;
}

/** `definePrimitive` of the kernel, with the parts named in kebab case and a `data-slot` that can be given. */
export const definePrimitive = ((options: any) =>
  definePrimitiveOf({
    ...options,
    slots: (slot: unknown) => nameSlots(options.name, options.slots(slot)),
  })) as typeof definePrimitiveOf;

import {
  createChange,
  css,
  dispatch,
  type PrimitiveInstance,
  type PropSpec,
  type SlotDefinition,
} from "@ui-sdk/core";
import { clampFinite, type Grid } from "../grid";
import {
  type ChangeDetails,
  type CommitDetails,
  createStore,
  definePrimitive,
  flag,
  type Source,
  type Store,
  sourceOf,
  VISUALLY_HIDDEN,
} from "../primitive";
import type { ClipValue } from "./clip";
import {
  type ClipApi,
  type ClipChangeDetails,
  type ClipCommitDetails,
  type ClipSlots,
  clipSlots,
  createClipApi,
} from "./clips";
import {
  LENGTH_PROPERTY,
  laneOf,
  OFFSET_PROPERTY,
  paintScale,
  placedAt,
  UNIT_PROPERTY,
  unitLength,
} from "./layout";
import {
  createNavigatorApi,
  type NavigatorApi,
  type NavigatorSlots,
  navigatorSlots,
} from "./navigator";
import {
  createTimelineController,
  type TimelineController,
  type TimelineSelectionHandlers,
  type TimelineSnapshot,
} from "./position";
import {
  createRangeController,
  type RangeController,
} from "./range-controller";
import {
  createRangeApi,
  type RangeApi,
  type RangeChangeDetails,
  type RangeCommitDetails,
  type RangeSlots,
  rangeSlots,
} from "./ranges";
import { anchoredScroll, valueAtOffset, type ZoomAnchor } from "./scale";
import {
  createTrackController,
  type TrackController,
} from "./track-controller";
import { createWheelZoom } from "./wheel-zoom";

/**
 * The timeline, over its controllers, beside it (`position.ts`,
 * `track-controller.ts`, `range-controller.ts`, `clip-controller.ts` and
 * `navigator-controller.ts`): the position and the zoom, a track's height, a
 * mark's drag. The primitive routes the elements' events to them and reports
 * what they change through the kernel.
 *
 * Everything that moves every frame reaches the DOM outside any render: the
 * playhead follows the position through a CSS variable, a lane is sized by its
 * unit, and the viewport measures and scrolls itself.
 *
 * Parts that hold a controller of their own (a track, a mark) are named by a
 * prop and report through the Root, with their name in the details.
 */

export type { Grid } from "../grid";
export type { ClipValue, FadeShape } from "./clip";
export { fadeGain } from "./clip";
export type {
  ClipApi,
  ClipChangeDetails,
  ClipCommitDetails,
  ClipEdgeState,
  ClipFadeState,
  ClipProps,
  ClipPublicState,
  ClipRef,
  ClipSlots,
} from "./clips";
export type {
  NavigatorApi,
  NavigatorEdgeState,
  NavigatorProps,
  NavigatorSlots,
} from "./navigator";
export type {
  RangeApi,
  RangeChangeDetails,
  RangeCommitDetails,
  RangeEdgeState,
  RangeProps,
  RangePublicState,
  RangeRef,
  RangeSlots,
  RangeValue,
} from "./ranges";

const noop = () => undefined;

const describeAsNumber = (value: number) =>
  String(Math.round(value * 100) / 100);

export type DescribePosition = (value: number, duration: number) => string;

/** A live position, in the timeline's units. */
export type PositionSource = Source<number>;

/** How the viewport is scrolled and zoomed, as last laid out. */
export interface ViewportMetrics {
  /** Where value 0 sits in the scrolled content, in px. */
  origin: number;
  scrollStart: number;
  /** Visible width, in px. */
  width: number;
  /** px per unit as drawn: the zoom, or what fitting the width gives. */
  zoom: number;
}

export interface TimelinePrimitiveOptions {
  defaultPosition?: number;
  defaultZoom?: number | null;
  disabled?: boolean;
  /** Length of the timeline, in your units. @default 1 */
  duration?: number;
  largeStep?: number;
  /** @default Infinity */
  maxZoom?: number;
  /** @default 0 */
  minZoom?: number;
  onClipChange?: (value: ClipValue, details: ClipChangeDetails) => void;
  onClipCommitted?: (value: ClipValue, details: ClipCommitDetails) => void;
  onClipDragOffsetChange?: (offset: number, details: { clip: string }) => void;
  /** Delete or Backspace on a clip: removing it is up to you. */
  onClipRemove?: (clip: string, details: { clip: string }) => void;
  onClipSelectedChange?: (
    selected: boolean,
    details: { clip: string; event: PointerEvent; reason: string }
  ) => void;
  onMarkChange?: (value: number, details: MarkChangeDetails) => void;
  onMarkCommitted?: (value: number, details: MarkCommitDetails) => void;
  onPositionChange?: (value: number, details: ChangeDetails) => void;
  onPositionCommitted?: (value: number, details: CommitDetails) => void;
  onRangeChange?: (
    value: readonly [number, number],
    details: RangeChangeDetails
  ) => void;
  onRangeCommitted?: (
    value: readonly [number, number],
    details: RangeCommitDetails
  ) => void;
  /** A Shift drag on the ruler, or on a seekable lane, selected a stretch. */
  onSelectionChange?: (
    range: readonly [number, number],
    details: ChangeDetails & { event: PointerEvent }
  ) => void;
  onSelectionCommitted?: (
    range: readonly [number, number],
    details: CommitDetails & { event: PointerEvent }
  ) => void;
  onTrackHeightChange?: (
    height: number | undefined,
    details: TrackChangeDetails
  ) => void;
  onTrackHeightCommitted?: (
    height: number | undefined,
    details: TrackCommitDetails
  ) => void;
  onZoomChange?: (zoom: number, details: ChangeDetails) => void;
  position?: number;
  snapOffset?: number;
  snapPoints?: readonly number[];
  snapStep?: number;
  source?: PositionSource;
  step?: number;
  zoom?: number | null;
}

export interface MarkChangeDetails extends ChangeDetails {
  mark: string;
}
export interface MarkCommitDetails extends CommitDetails {
  mark: string;
}
export interface TrackChangeDetails extends ChangeDetails {
  track: string;
}
export interface TrackCommitDetails extends CommitDetails {
  track: string;
}

export interface TimelineState {
  duration: number;
  /** The latest snapshot on every step. Live: a zoom writes the lanes' scale straight to them, and no part renders for it. */
  frame: TimelineSnapshot;
  /** Counts the changes a track's or mark's controller made, so the parts read them again. */
  parts: number;
  position: number;
  /** The live position the timeline follows, when it has one. */
  source: PositionSource | undefined;
  view: TimelineSnapshot;
  zoom: number | null;
}

/** What a part reads of the timeline. */
export interface TimelinePublicState {
  disabled: boolean;
  /** Whether no zoom is set, so the timeline fits the width it is given. */
  fitted: boolean;
  /** Whether a pointer is moving the position. */
  scrubbing: boolean;
}

/** The props every part takes. */
interface PartProps {
  id?: string;
}

/** The props of a track's parts. */
export interface TrackProps extends PartProps {
  height?: number;
  largeStep?: number;
  maxHeight?: number;
  minHeight?: number;
  selected?: boolean;
  step?: number;
  /** The name of the track: what keys it and what its changes report. */
  track: string;
}

export interface TrackPublicState extends TimelinePublicState {
  resizing: boolean;
  selected: boolean;
}

/** The props of the parts that belong to a track, beside the track itself. */
export interface TrackRef extends PartProps {
  /** The name of the track it belongs to. */
  track: string;
}

/** The props of a mark. */
export interface MarkProps extends PartProps {
  /** The name of the mark: what keys it and what its changes report. */
  mark: string;
  /** Whether a drag, or the arrows, move it. @default false */
  movable?: boolean;
  step?: number;
  value: number;
}

export interface MarkPublicState extends TimelinePublicState {
  dragging: boolean;
}

/** What a timeline's `api` gives an adapter. */
export interface TimelineApi extends ClipApi, NavigatorApi, RangeApi {
  /** Where the next zoom should hold still; the viewport applies it once laid out. */
  anchor: { current: ZoomAnchor | null };
  controller: TimelineController;
  internal: { keyOf: (value: unknown) => string };
  /** The lanes mounted: the first in the document is where value 0 is measured from. */
  lanes: Set<HTMLElement>;
  /** The latest snapshot, read when it is needed: a render's `state` keeps live keys as they were. */
  latest: () => TimelineSnapshot;
  markFor: (state: TimelineState, props: MarkProps) => RangeController;
  /** Where each mark's press began, so a press that stays one still clicks. */
  markPress: Map<string, { moved: boolean; x: number }>;
  /** The position, observable outside any render. */
  position: Store<number>;
  /** Scrolls the viewport to `left` px and reports where it landed. */
  scrollerTo: { current: ((left: number) => void) | null };
  /** What a selection reports to the app, for a gesture that makes one. */
  selecting: () => TimelineSelectionHandlers;
  trackFor: (
    props: TrackProps,
    /** Whether `props` are the track part's own, which hold what the track is given. */
    owner?: boolean
  ) => TrackController;
  /** What each track was given by its own part. */
  trackProps: Map<string, TrackProps>;
  /** The element of a part, by its name, once it binds. */
  tracks: Map<string, HTMLElement>;
  viewport: Store<ViewportMetrics>;
  viewportEl: { current: HTMLElement | null };
  /** px per unit, or null while fitted: read when needed, or followed. */
  zoom: { get: () => number | null; subscribe: (l: () => void) => () => void };
  zoomTo: (
    next: number,
    details: Parameters<TimelineController["zoomTo"]>[1],
    anchor?: ZoomAnchor
  ) => boolean;
}

type Slot<Props, Public = TimelinePublicState> = SlotDefinition<
  TimelineState,
  TimelineApi,
  Props,
  Public
>;

/** The timeline's slots, by name, with the props and the public state of each. */
export type TimelineSlots = ClipSlots &
  NavigatorSlots &
  RangeSlots & {
    lane: Slot<PartProps & { seekable?: boolean; selects?: boolean }>;
    mark: Slot<MarkProps, MarkPublicState>;
    playhead: Slot<PartProps>;
    root: Slot<PartProps>;
    ruler: Slot<PartProps>;
    rulerInput: Slot<
      PartProps & { getAriaValueText?: DescribePosition },
      object
    >;
    track: Slot<TrackProps, TrackPublicState>;
    trackHeader: Slot<PartProps, TrackPublicState>;
    trackResizeHandle: Slot<TrackRef, TrackPublicState>;
    trackResizeInput: Slot<TrackRef, object>;
    viewport: Slot<PartProps>;
  };

/** The type of `timeline`, written out so a declaration can print it. */
export interface TimelinePrimitive {
  options: Record<string, PropSpec> | undefined;
  slots: TimelineSlots;
  (
    initialOptions: TimelinePrimitiveOptions & { id: string }
  ): Omit<PrimitiveInstance, "api" | "get" | "types"> & {
    api: TimelineApi;
    get: () => TimelineState;
    types: {
      api: TimelineApi;
      options: TimelinePrimitiveOptions;
      slots: TimelineSlots;
      state: TimelineState;
    };
  };
}

/** The options the controller needs, with the defaults the React timeline gave. */
function adjustOptions(options: TimelinePrimitiveOptions) {
  const duration = options.duration ?? 1;
  const snapStep = options.snapStep ?? 0;
  const step = options.step ?? (snapStep > 0 ? snapStep : duration / 100);
  const grid: Grid = {
    offset: options.snapOffset ?? 0,
    points: options.snapPoints,
    step: snapStep,
  };
  return {
    defaultPosition: options.defaultPosition ?? 0,
    defaultZoom: options.defaultZoom ?? null,
    disabled: options.disabled ?? false,
    duration,
    grid,
    largeStep: options.largeStep ?? step * 10,
    maxZoom: options.maxZoom ?? Number.POSITIVE_INFINITY,
    minZoom: options.minZoom ?? 0,
    source: options.source,
    step,
  };
}

function viewOf(options: TimelinePrimitiveOptions): TimelineSnapshot {
  return createTimelineController({
    ...adjustOptions(options),
    position: options.position,
    zoom: options.zoom,
  }).getSnapshot();
}

const publicState = (state: TimelineState): TimelinePublicState => ({
  disabled: state.view.disabled,
  fitted: state.view.fitted,
  scrubbing: state.view.scrubbing,
});

const stateAttrs = (state: TimelineState) => ({
  "data-disabled": flag(state.view.disabled),
  "data-fitted": flag(state.view.fitted),
  "data-scrubbing": flag(state.view.scrubbing),
});

/**
 * How much the transforms of the element's ancestors scale it, such as a
 * dialog that zooms in: what `getBoundingClientRect` gives is divided by it to
 * get back to layout px, which `scrollLeft` and `clientWidth` are in.
 */
function layoutScale(element: HTMLElement) {
  const drawn = element.getBoundingClientRect().width;
  const laid = element.offsetWidth;
  return drawn > 0 && laid > 0 ? drawn / laid : 1;
}

const PRESS_SLOP_PX = 3;

const inField = (target: EventTarget | null) =>
  target instanceof HTMLInputElement ||
  target instanceof HTMLTextAreaElement ||
  (target instanceof HTMLElement && target.isContentEditable);

export { LENGTH_PROPERTY, OFFSET_PROPERTY, UNIT_PROPERTY };

export const timeline: TimelinePrimitive = definePrimitive({
  agent: { actions: ["setPosition"] },
  live: ["frame"],
  api: (context) => {
    const options = () => context.options() as TimelinePrimitiveOptions;
    const controller: TimelineController = createTimelineController({
      ...adjustOptions(options()),
      position: options().position,
      zoom: options().zoom,
    });
    const change = createChange(context);

    // The parts render from the snapshot: it is set only when it differs, so a zoom that several things report is one change to them.
    const publish = () => {
      const next = controller.getSnapshot();
      const held = context.store.get().view;
      const drawn =
        next.disabled !== held.disabled ||
        next.duration !== held.duration ||
        next.fitted !== held.fitted ||
        next.position !== held.position ||
        next.scrubbing !== held.scrubbing;
      context.store.set(drawn ? { frame: next, view: next } : { frame: next });
    };

    // The controller always works controlled: the kernel holds the position and the zoom.
    const configure = () => {
      const wanted = options();
      const held = context.store.get();
      controller.setOptions({
        ...adjustOptions(wanted),
        onPositionChange: (value, details) => {
          const source = sourceOf(details.event);
          if (
            !change("position", value, {
              event: details.event,
              reason: details.reason,
              ...(source ? { source } : {}),
            } as never)
          ) {
            details.cancel();
          }
        },
        onPositionCommitted: (value, details) => {
          dispatch(context, "onPositionCommitted", value, {
            event: details.event,
            reason: details.reason,
          });
        },
        onZoomChange: (zoom, details) => {
          const source = sourceOf(details.event);
          if (
            !change("zoom", zoom, {
              event: details.event,
              reason: details.reason,
              ...(source ? { source } : {}),
            } as never)
          ) {
            details.cancel();
          }
        },
        position: held.position,
        zoom: held.zoom,
      });
      publish();
    };
    configure();
    context.onOptions(configure);
    // A zoom that was given and is not any more goes back to where the timeline began: to the fit, or its default.
    let zoomGiven = options().zoom !== undefined;
    context.onOptions(() => {
      const given = options().zoom !== undefined;
      if (zoomGiven && !given) {
        context.store.set({ zoom: options().defaultZoom ?? null } as never);
      }
      zoomGiven = given;
    });
    let lastPosition = context.store.get().position;
    let lastZoom = context.store.get().zoom;
    context.onDestroy(
      context.store.subscribe(() => {
        const { position, zoom } = context.store.get();
        if (position !== lastPosition || zoom !== lastZoom) {
          lastPosition = position;
          lastZoom = zoom;
          configure();
        }
      })
    );
    context.onDestroy(controller.subscribe(publish));

    // A selection is made only when the app listens for it.
    const selecting = (): TimelineSelectionHandlers => {
      const wanted = options();
      return {
        onSelectionChange: wanted.onSelectionChange
          ? (range, details) => {
              if (
                dispatch(context, "onSelectionChange", range, {
                  event: details.event,
                  reason: details.reason,
                })
              ) {
                details.cancel();
              }
            }
          : undefined,
        onSelectionCommitted: wanted.onSelectionCommitted
          ? (range, details) => {
              dispatch(context, "onSelectionCommitted", range, {
                event: details.event,
                reason: details.reason,
              });
            }
          : undefined,
      };
    };
    // A Shift drag selects.
    const listen = () => controller.setSelection(selecting());
    listen();
    context.onOptions(listen);

    const zoomListeners = new Set<() => void>();
    let toldZoom = lastZoom;
    context.onDestroy(
      context.store.subscribe(() => {
        const { zoom } = context.store.get().view;
        if (zoom === toldZoom) {
          return;
        }
        toldZoom = zoom;
        for (const listener of [...zoomListeners]) {
          listener();
        }
      })
    );

    const anchor: { current: ZoomAnchor | null } = { current: null };
    const tracks = new Map<string, HTMLElement>();
    const trackControllers = new Map<string, TrackController>();
    const trackProps = new Map<string, TrackProps>();
    const markControllers = new Map<string, RangeController>();
    const markPress = new Map<string, { moved: boolean; x: number }>();
    const bump = () =>
      context.store.set({ parts: context.store.get().parts + 1 } as never);

    const result = {
      ...createClipApi(context, () => adjustOptions(options()), bump),
      ...createRangeApi(context, () => adjustOptions(options()), bump),
      ...createNavigatorApi(
        () => result,
        () => adjustOptions(options()).maxZoom
      ),
      anchor,
      controller,
      selecting,
      internal: { keyOf: (value: unknown) => String(value) },
      lanes: new Set<HTMLElement>(),
      latest: () => context.store.get().frame,
      markFor: (state: TimelineState, props: MarkProps) => {
        const name = String(props.mark);
        const settings = adjustOptions(options());
        const rangeOptions = {
          disabled: state.view.disabled,
          duration: settings.duration,
          grid: settings.grid,
          largeStep: settings.largeStep,
          minLength: 0,
          movable: true,
          onValueChange: (
            range: readonly [number, number],
            details: {
              cancel: () => void;
              event: Event;
              reason: string;
            }
          ) => {
            const pointer = details.event as PointerEvent;
            const held = markPress.get(name) ?? { moved: false, x: 0 };
            if (details.reason === "drag" && !held.moved) {
              if (Math.abs(pointer.clientX - held.x) < PRESS_SLOP_PX) {
                details.cancel();
                return;
              }
              held.moved = true;
            }
            const source = sourceOf(details.event);
            if (
              dispatch(context, "onMarkChange", range[0], {
                event: details.event,
                mark: name,
                reason: details.reason,
                ...(source ? { source } : {}),
              })
            ) {
              details.cancel();
            }
          },
          onValueCommitted: (
            range: readonly [number, number],
            details: { event: Event; reason: string }
          ) => {
            dispatch(context, "onMarkCommitted", range[0], {
              event: details.event,
              mark: name,
              reason: details.reason,
            });
          },
          step: props.step ?? settings.step,
          value: [props.value, props.value] as [number, number],
          get zoom() {
            return context.store.get().frame.zoom;
          },
        };
        let mark = markControllers.get(name);
        if (mark) {
          mark.setOptions(rangeOptions as never);
        } else {
          mark = createRangeController(rangeOptions as never);
          mark.subscribe(bump);
          markControllers.set(name, mark);
        }
        return mark;
      },
      markPress,
      position: createStore(
        clampFinite(
          controller.getSnapshot().position,
          0,
          context.store.get().duration
        )
      ),
      scrollerTo: { current: null as ((left: number) => void) | null },
      trackFor: (props: TrackProps, owner = false) => {
        const name = String(props.track);
        const trackOptions = {
          height: props.height,
          largeStep: props.largeStep ?? 32,
          max: props.maxHeight ?? 480,
          measure: () => tracks.get(name)?.getBoundingClientRect().height ?? 0,
          min: props.minHeight ?? 32,
          onHeightChange: (
            height: number | undefined,
            details: { cancel: () => void; event?: Event; reason: string }
          ) => {
            const source = sourceOf(details.event);
            if (
              dispatch(context, "onTrackHeightChange", height, {
                event: details.event,
                reason: details.reason,
                track: name,
                ...(source ? { source } : {}),
              })
            ) {
              details.cancel();
            }
          },
          onHeightCommitted: (
            height: number | undefined,
            details: { event?: Event; reason: string }
          ) => {
            dispatch(context, "onTrackHeightCommitted", height, {
              event: details.event,
              reason: details.reason,
              track: name,
            });
          },
          step: props.step ?? 8,
        };
        if (owner) {
          trackProps.set(name, props);
        }
        let track = trackControllers.get(name);
        if (track) {
          if (owner) {
            track.setOptions(trackOptions as never);
          }
        } else {
          track = createTrackController(trackOptions as never);
          track.subscribe(bump);
          trackControllers.set(name, track);
        }
        return track;
      },
      trackProps,
      tracks,
      viewport: createStore<ViewportMetrics>({
        origin: 0,
        scrollStart: 0,
        width: 0,
        zoom: 0,
      }),
      viewportEl: { current: null as HTMLElement | null },
      zoom: {
        get: () => context.store.get().frame.zoom,
        subscribe: (listener: () => void) => {
          zoomListeners.add(listener);
          return () => {
            zoomListeners.delete(listener);
          };
        },
      },
      zoomTo: (
        next: number,
        details: Parameters<TimelineController["zoomTo"]>[1],
        at?: ZoomAnchor
      ) => {
        if (!controller.zoomTo(next, details)) {
          return false;
        }
        anchor.current = at ?? null;
        return true;
      },
    } as unknown as TimelineApi;
    return result;
  },
  controlled: ["position", "zoom"],
  name: "timeline",
  options: {
    defaultPosition: "number",
    defaultZoom: "value",
    disabled: "boolean",
    duration: "number",
    largeStep: "number",
    maxZoom: "number",
    minZoom: "number",
    onClipChange: "callback",
    onClipCommitted: "callback",
    onClipDragOffsetChange: "callback",
    onClipRemove: "callback",
    onClipSelectedChange: "callback",
    onMarkChange: "callback",
    onRangeChange: "callback",
    onRangeCommitted: "callback",
    onMarkCommitted: "callback",
    onPositionChange: "callback",
    onPositionCommitted: "callback",
    onSelectionChange: "callback",
    onSelectionCommitted: "callback",
    onTrackHeightChange: "callback",
    onTrackHeightCommitted: "callback",
    onZoomChange: "callback",
    position: "number",
    snapOffset: "number",
    snapPoints: "value",
    snapStep: "number",
    source: "value",
    step: "number",
    zoom: "value",
  },
  slots: (slot) => {
    const trackView = (api: TimelineApi, props: object) =>
      api.trackFor(props as TrackProps).getSnapshot();

    return {
      ...clipSlots(slot),
      ...navigatorSlots(slot),
      ...rangeSlots(slot),
      lane: slot<
        { seekable?: boolean; selects?: boolean },
        TimelinePublicState
      >({
        attrs: (state: TimelineState, { api }) => ({
          ...stateAttrs(state),
          "data-timeline-lane": "",
          style: css({
            [UNIT_PROPERTY]: unitLength(api.latest().zoom, state.duration),
            // What changes inside a lane is laid out and styled without the rest of the page.
            contain: "layout style",
            "overflow-x": "clip",
            position: "relative",
            ...(api.latest().zoom === null
              ? {}
              : {
                  "min-width": `${state.duration * (api.latest().zoom ?? 0)}px`,
                }),
          }),
        }),
        bind: (el, part) => {
          part.api.lanes.add(el);
          // The scale is written here on each step, so a zoom renders nothing.
          const paint = () => {
            const { duration, frame } = part.store.get();
            paintScale(el, frame.zoom, duration);
          };
          const off = part.store.subscribe(paint);
          return () => {
            off();
            part.api.lanes.delete(el);
          };
        },
        on: {
          pointerdown: (event, { api, el, props, store }) => {
            if (
              !(el && props.seekable) ||
              store.get().view.disabled ||
              event.button !== 0 ||
              event.target !== el
            ) {
              return;
            }
            api.controller.pressSeek(
              event,
              el,
              el,
              props.selects ? api.selecting() : undefined
            );
          },
        },
        // An id of its own for each lane: parts that share their props share one element.
        props: { id: "id", seekable: "boolean", selects: "boolean" },
        state: (state: TimelineState) => publicState(state),
      }),
      mark: slot<MarkProps, MarkPublicState>({
        attrs: (state: TimelineState, { api, props }) => {
          const moving = props.movable
            ? api.markFor(state, props).getSnapshot()
            : undefined;
          return {
            ...stateAttrs(state),
            "data-dragging": flag(Boolean(moving?.dragging)),
            style: css(placedAt(moving ? moving.value[0] : props.value)),
          };
        },
        // A press that became a drag keeps its click from reaching what is under it.
        bind: (el, part) => {
          const swallow = (event: Event) => {
            const held = part.api.markPress.get(String(part.props.mark));
            if (held?.moved) {
              held.moved = false;
              event.preventDefault();
              event.stopPropagation();
            }
          };
          el.addEventListener("click", swallow, true);
          return () => el.removeEventListener("click", swallow, true);
        },
        on: {
          keydown: (event, { api, props, store }) => {
            if (
              !props.movable ||
              (event.key !== "ArrowLeft" && event.key !== "ArrowRight") ||
              event.altKey ||
              event.ctrlKey ||
              event.metaKey ||
              inField(event.target)
            ) {
              return;
            }
            if (api.markFor(store.get(), props).keyDown(event)) {
              event.preventDefault();
              event.stopPropagation();
            }
          },
          pointerdown: (event, { api, el, props, store }) => {
            if (!props.movable || event.button !== 0 || inField(event.target)) {
              return;
            }
            // The press stops here, so the lane underneath doesn't take it.
            event.stopPropagation();
            api.markPress.set(String(props.mark), {
              moved: false,
              x: event.clientX,
            });
            api
              .markFor(store.get(), props)
              .press(
                "both",
                event,
                event.target as Element,
                laneOf(el ?? null)
              );
          },
        },
        props: {
          mark: "key",
          movable: "boolean",
          step: "number",
          value: "number",
        },
        state: (state: TimelineState, { api, props }) => ({
          ...publicState(state),
          dragging: props.movable
            ? api.markFor(state, props).getSnapshot().dragging
            : false,
        }),
      }),
      // A marker at the playback position, following it straight in the DOM.
      playhead: slot<object, TimelinePublicState>({
        attrs: (state: TimelineState, { api }) => ({
          ...stateAttrs(state),
          "aria-hidden": "true",
          style: css(placedAt(api.position.get())),
        }),
        bind: (el, part) => {
          const follow = () =>
            el.style.setProperty(
              OFFSET_PROPERTY,
              String(part.api.position.get())
            );
          follow();
          const offPosition = part.api.position.subscribe(follow);
          const offStore = part.store.subscribe(follow);
          return () => {
            offPosition();
            offStore();
          };
        },
        // An id of its own for each: parts that share their props share one element.
        props: { id: "id" },
        state: (state: TimelineState) => publicState(state),
      }),
      root: slot<object, TimelinePublicState>({
        attrs: (state: TimelineState) => stateAttrs(state),
        // The position reaches the DOM outside any render: a live source paints every frame.
        bind: (_el, part) => {
          const { controller, position } = part.api;
          const paint = () =>
            position.set(
              clampFinite(
                controller.getSnapshot().position,
                0,
                part.store.get().duration
              )
            );
          let followed: PositionSource | undefined;
          let unfollow: () => void = noop;
          const watch = () => {
            const live = (
              part.store.get() as TimelineState & {
                source?: PositionSource;
              }
            ).source;
            if (live !== followed) {
              unfollow();
              followed = live;
              unfollow = live ? live.subscribe(paint) : () => undefined;
            }
            paint();
          };
          watch();
          const offController = controller.subscribe(paint);
          const offStore = part.store.subscribe(watch);
          return () => {
            offController();
            offStore();
            unfollow();
          };
        },
        state: (state: TimelineState) => publicState(state),
      }),
      // The lane that moves the position: a press jumps to the pointer and a drag scrubs.
      ruler: slot<object, TimelinePublicState>({
        attrs: (state: TimelineState, { api }) => ({
          ...stateAttrs(state),
          "data-timeline-lane": "",
          style: css({
            [UNIT_PROPERTY]: unitLength(api.latest().zoom, state.duration),
            contain: "layout style",
            "overflow-x": "clip",
            position: "relative",
            "touch-action": "none",
            ...(api.latest().zoom === null
              ? {}
              : {
                  "min-width": `${state.duration * (api.latest().zoom ?? 0)}px`,
                }),
          }),
        }),
        bind: (el, part) => {
          part.api.lanes.add(el);
          // The scale is written here on each step, so a zoom renders nothing.
          const paint = () => {
            const { duration, frame } = part.store.get();
            paintScale(el, frame.zoom, duration);
          };
          const off = part.store.subscribe(paint);
          return () => {
            off();
            part.api.lanes.delete(el);
          };
        },
        on: {
          pointerdown: (event, { api, el, store }) => {
            if (!el || store.get().view.disabled || event.button !== 0) {
              return;
            }
            event.preventDefault();
            el.querySelector<HTMLInputElement>('input[type="range"]')?.focus({
              preventScroll: true,
            });
            api.controller.pressRuler(event, el, el);
          },
        },
        state: (state: TimelineState) => publicState(state),
      }),
      rulerInput: slot<{ getAriaValueText?: DescribePosition }>({
        attrs: (state: TimelineState, { api, props }) => ({
          "aria-valuetext": (props.getAriaValueText ?? describeAsNumber)(
            api.position.get(),
            state.duration
          ),
          disabled: flag(state.view.disabled),
          max: String(state.duration),
          min: "0",
          step: "any",
          style: css(VISUALLY_HIDDEN),
          type: "range",
          value: String(api.position.get()),
        }),
        // The input follows the position outside any render, like the playhead.
        bind: (el, part) => {
          const input = el as HTMLInputElement;
          const follow = () => {
            const value = part.api.position.get();
            const text = (part.props.getAriaValueText ?? describeAsNumber)(
              value,
              part.store.get().duration
            );
            if (input.getAttribute("aria-valuetext") !== text) {
              input.setAttribute("aria-valuetext", text);
            }
            input.value = String(value);
          };
          follow();
          return part.api.position.subscribe(follow);
        },
        on: {
          change: (event, { api, el }) =>
            api.controller.typeAt(
              Number((el as HTMLInputElement).value),
              event
            ),
          keydown: (event, { api }) => {
            if (api.controller.keyDown(event)) {
              event.preventDefault();
            }
          },
        },
        props: { getAriaValueText: "value" },
      }),
      // One track of the arrangement: a row holding a header beside a lane.
      track: slot<TrackProps, TrackPublicState>({
        attrs: (state: TimelineState, { api, props }) => ({
          ...stateAttrs(state),
          "data-resizing": flag(
            api.trackFor(props, true).getSnapshot().resizing
          ),
          "data-selected": flag(Boolean(props.selected)),
          "data-track-name": String(props.track),
          style: css({
            display: "flex",
            "min-width": "100%",
            ...(props.height === undefined
              ? {}
              : { height: `${props.height}px` }),
          }),
        }),
        bind: (el, part) => {
          const name = String(part.props.track);
          part.api.tracks.set(name, el);
          return () => part.api.tracks.delete(name);
        },
        props: {
          height: "number",
          largeStep: "number",
          maxHeight: "number",
          minHeight: "number",
          selected: "boolean",
          step: "number",
          track: "key",
        },
        state: (state: TimelineState, { api, props }) => ({
          ...publicState(state),
          resizing: trackView(api, props).resizing,
          selected: Boolean(props.selected),
        }),
      }),
      // The strip beside a track's lane that names it: it stays at the left edge while the lane scrolls.
      trackHeader: slot<object, TrackPublicState>({
        attrs: (state: TimelineState) => ({
          ...stateAttrs(state),
          style: css({
            "flex-shrink": "0",
            left: "0",
            position: "sticky",
            "z-index": "var(--timeline-track-header-z, 20)",
          }),
        }),
        state: (state: TimelineState) => ({
          ...publicState(state),
          resizing: false,
          selected: false,
        }),
      }),
      trackResizeHandle: slot<TrackRef, TrackPublicState>({
        attrs: (state: TimelineState, { api, props }) => ({
          ...stateAttrs(state),
          "data-resizing": flag(trackView(api, props).resizing),
          style: css({ "touch-action": "none" }),
        }),
        on: {
          dblclick: (event, { api, props }) => api.trackFor(props).reset(event),
          pointerdown: (event, { api, el, props }) => {
            // The track's own press (to pick it) is not this one.
            event.stopPropagation();
            if (!el || event.button !== 0) {
              return;
            }
            el.querySelector<HTMLInputElement>('input[type="range"]')?.focus({
              preventScroll: true,
            });
            api.trackFor(props).press(event, el);
          },
        },
        props: { track: "key" },
        state: (state: TimelineState, { api, props }) => ({
          ...publicState(state),
          resizing: trackView(api, props).resizing,
          selected: false,
        }),
      }),
      trackResizeInput: slot<TrackRef>({
        attrs: (_state: TimelineState, { api, props }) => {
          const given = api.trackProps.get(String(props.track));
          return {
            "aria-orientation": "vertical",
            max: String(given?.maxHeight ?? 480),
            min: String(given?.minHeight ?? 32),
            step: "any",
            style: css(VISUALLY_HIDDEN),
            type: "range",
            value: String(given?.height ?? given?.minHeight ?? 32),
          };
        },
        on: {
          change: (event, { api, el, props }) =>
            api
              .trackFor(props)
              .typeAt(Number((el as HTMLInputElement).value), event),
          keydown: (event, { api, props }) => {
            if (api.trackFor(props).keyDown(event)) {
              event.preventDefault();
            }
          },
        },
        props: { track: "key" },
      }),
      // The scrolling window onto the timeline: Cmd/Ctrl + wheel zooms around the pointer.
      viewport: slot<object, TimelinePublicState>({
        attrs: (state: TimelineState) => ({
          ...stateAttrs(state),
          "data-timeline-viewport": "",
          style: css({ "overflow-x": "auto" }),
        }),
        bind: (el, part) => {
          const { api, store } = part;
          api.viewportEl.current = el;
          let previous: { scrollStart: number; zoom: number } | null = null;

          const measureOrigin = () => {
            const lane = el.querySelector<HTMLElement>("[data-timeline-lane]");
            if (!lane) {
              return 0;
            }
            return (
              (lane.getBoundingClientRect().left -
                el.getBoundingClientRect().left) /
                layoutScale(el) +
              el.scrollLeft
            );
          };
          // Where the lanes start does not move with the zoom: it is measured once, and again when the viewport is resized, so a zoom reads no layout.
          let knownOrigin: number | null = null;
          const origin = () => {
            knownOrigin ??= measureOrigin();
            return knownOrigin;
          };
          const drawnZoom = () => {
            const { duration, frame } = store.get();
            if (frame.zoom !== null) {
              return frame.zoom;
            }
            const width =
              (el
                .querySelector<HTMLElement>("[data-timeline-lane]")
                ?.getBoundingClientRect().width ?? 0) / layoutScale(el);
            return width / Math.max(duration, Number.MIN_VALUE);
          };
          const wheelOptions = () => ({
            disabled: store.get().view.disabled,
            drawnZoom,
            duration: store.get().duration,
            origin,
            zoomTo: api.zoomTo,
          });
          const wheelZoom = createWheelZoom(wheelOptions());

          const report = () => {
            const next = {
              origin: origin(),
              scrollStart: el.scrollLeft,
              width: el.clientWidth,
              zoom: drawnZoom(),
            };
            const current = api.viewport.get();
            if (
              current.origin !== next.origin ||
              current.scrollStart !== next.scrollStart ||
              current.width !== next.width ||
              current.zoom !== next.zoom
            ) {
              api.viewport.set(next);
            }
          };
          api.scrollerTo.current = (left: number) => {
            el.scrollLeft = left;
            if (previous) {
              previous.scrollStart = el.scrollLeft;
            }
            report();
          };
          report();

          // A resize is reported on the next frame, so the lanes are not styled inside the layout pass that measured them.
          let frame = 0;
          const observer =
            typeof ResizeObserver === "undefined"
              ? null
              : new ResizeObserver(() => {
                  knownOrigin = null;
                  cancelAnimationFrame(frame);
                  frame = requestAnimationFrame(report);
                });
          observer?.observe(el);

          // The one place that reacts to the zoom changing, once the lanes are laid out again.
          let applying = false;
          const settle = () => {
            const current = drawnZoom();
            if (previous && previous.zoom > 0 && previous.zoom !== current) {
              const middle = api.viewport.get().width / 2;
              const at = api.anchor.current ?? {
                offset: middle,
                value: valueAtOffset(
                  middle,
                  previous.scrollStart,
                  previous.zoom,
                  origin()
                ),
              };
              api.anchor.current = null;
              el.scrollLeft = anchoredScroll(at, current, origin());
            }
            previous = { scrollStart: el.scrollLeft, zoom: current };
            report();
          };
          settle();
          let lastZoom = store.get().frame.zoom;
          const offStore = store.subscribe(() => {
            wheelZoom.setOptions(wheelOptions());
            const { zoom } = store.get().frame;
            if (zoom !== lastZoom) {
              lastZoom = zoom;
              // Before the next frame, so a scroll the app puts there in its own frame has the last word, and once for the steps of one task.
              if (!applying) {
                applying = true;
                queueMicrotask(() => {
                  applying = false;
                  settle();
                });
              }
            }
          });

          // Attached natively: a passive listener could not stop the page from scrolling while it zooms.
          const handleWheel = (event: WheelEvent) => {
            wheelZoom.wheel(event, el);
          };
          el.addEventListener("wheel", handleWheel, { passive: false });
          const handleScroll = () => {
            if (previous) {
              previous.scrollStart = el.scrollLeft;
            }
            report();
          };
          el.addEventListener("scroll", handleScroll);
          return () => {
            offStore();
            cancelAnimationFrame(frame);
            observer?.disconnect();
            el.removeEventListener("wheel", handleWheel);
            el.removeEventListener("scroll", handleScroll);
            wheelZoom.dispose();
            api.viewportEl.current = null;
            api.scrollerTo.current = null;
          };
        },
        state: (state: TimelineState) => publicState(state),
      }),
    };
  },
  state: (options: TimelinePrimitiveOptions): TimelineState => {
    const view = viewOf(options);
    return {
      duration: options.duration ?? 1,
      frame: view,
      parts: 0,
      position: view.position,
      source: options.source,
      view,
      zoom: view.zoom,
    } as TimelineState;
  },
  sync: (options: TimelinePrimitiveOptions) => ({
    duration: options.duration ?? 1,
    ...(options.position === undefined ? {} : { position: options.position }),
    source: options.source,
    ...(options.zoom === undefined ? {} : { zoom: options.zoom }),
  }),
});

/**
 * Painting outside any render: a task that runs on animation frames only
 * while it has something to animate, and a watch on whether an element is in
 * view. Shared by the waveform and the timeline.
 */

/** The longest step the clock takes, so a task that slept or sat in a hidden tab never jumps ahead. */
const MAX_STEP_MS = 100;

/** What `createFrameTask` returns: wake it when something moves, flush it to step at once, stop it for good. */
export interface FrameTask {
  /** Run a step now, without waiting for the pending frame. */
  flush: () => void;
  /** Stop for good: a stopped task ignores `wake` and `flush`. */
  stop: () => void;
  /** Run a step on the next animation frame, unless one is already pending. */
  wake: () => void;
}

/**
 * Runs `step` on animation frames for as long as it returns true, and sleeps
 * otherwise: a painter with nothing left to animate costs no frames until it
 * is woken. `step` receives the time since the previous step, in milliseconds:
 * zero on the first step after a sleep, and never more than 100.
 */
export function createFrameTask(
  step: (elapsedMs: number) => boolean
): FrameTask {
  let frame = 0;
  let lastMs: number | null = null;
  let stopped = false;

  const wake = () => {
    if (!stopped && frame === 0) {
      frame = requestAnimationFrame(run);
    }
  };

  function run(nowMs: number) {
    frame = 0;
    const elapsed =
      lastMs === null ? 0 : Math.min(Math.max(0, nowMs - lastMs), MAX_STEP_MS);
    lastMs = nowMs;
    if (step(elapsed)) {
      wake();
    } else {
      lastMs = null;
    }
  }

  return {
    flush: () => {
      if (stopped) {
        return;
      }
      cancelAnimationFrame(frame);
      run(performance.now());
    },
    stop: () => {
      stopped = true;
      cancelAnimationFrame(frame);
      frame = 0;
    },
    wake,
  };
}

/**
 * Calls `onChange` when `element` enters or leaves the viewport, so a painter
 * can skip frames nobody sees. Returns a function that stops observing.
 */
export function observeVisibility(
  element: Element,
  onChange: (visible: boolean) => void
): () => void {
  if (typeof IntersectionObserver === "undefined") {
    return () => undefined;
  }
  const observer = new IntersectionObserver((entries) => {
    const entry = entries.at(-1);
    if (entry) {
      onChange(entry.isIntersecting);
    }
  });
  observer.observe(element);
  return () => observer.disconnect();
}

/**
 * The grid the timeline and the piano roll snap to, and the ranges they move:
 * shared by both, beside `primitive.ts`.
 */

import { clamp } from "@ui-sdk/core/number";

/** `value` within `min` and `max`, or `min` when it is not a number. */
export const clampFinite = (value: number, min: number, max: number) =>
  Number.isFinite(value) ? clamp(value, min, max) : min;

/** A stretch of a timeline, `[start, end]` in its units. */
export type RangeValue = readonly [start: number, end: number];

/** What a change moves: one edge, or the whole range with `both`. */
export type RangeEdge = "both" | "end" | "start";

/** What a range is kept within: the timeline's length and the shortest it may be. */
export interface RangeLimits {
  duration: number;
  /** The shortest a range may be resized to. */
  minLength: number;
}

/** Orders a range's edges and keeps them on the timeline. */
export function normalizeRange(
  value: RangeValue,
  duration: number
): RangeValue {
  const first = clampFinite(value[0], 0, duration);
  const second = clampFinite(value[1], 0, duration);
  return first <= second ? [first, second] : [second, first];
}

/**
 * Moves one edge of `origin` by `delta`, or the whole range, without leaving
 * the timeline. An edge stops `minLength` short of the other one; a range
 * moved as a whole keeps its length.
 */
export function moveRange(
  origin: RangeValue,
  edge: RangeEdge,
  delta: number,
  limits: RangeLimits
): RangeValue {
  const [start, end] = origin;
  const { duration, minLength } = limits;
  if (edge === "both") {
    const length = end - start;
    const next = clamp(start + delta, 0, Math.max(0, duration - length));
    return [next, next + length];
  }
  if (edge === "start") {
    return [clamp(start + delta, 0, Math.max(0, end - minLength)), end];
  }
  return [
    start,
    clamp(end + delta, Math.min(duration, start + minLength), duration),
  ];
}

/**
 * Grid lines `step` apart, starting from `offset`. A `step` of 0 or less is no
 * grid. `points` are places that pull harder than the lines, such as the
 * edges of other clips and the locators: within `radius` of one, a dragged
 * thing lands on it. The radius is set per gesture from how many units a few
 * pixels are.
 */
export interface Grid {
  offset: number;
  points?: readonly number[];
  radius?: number;
  step: number;
}

/** How far from a snap point, in px, a dragged thing is pulled onto it. */
export const SNAP_RADIUS_PX = 8;

/** The grid with its points pulling from `radius` units away, so a gesture can set it from its own zoom. */
export function withSnapRadius(grid: Grid, radius: number): Grid {
  return grid.points?.length ? { ...grid, radius } : grid;
}

/** The point of `grid` nearest `value` within its radius, or null when none is that close. */
export function nearestSnapPoint(value: number, grid: Grid): number | null {
  const radius = grid.radius ?? 0;
  let found: number | null = null;
  for (const point of grid.points ?? []) {
    const distance = Math.abs(point - value);
    if (
      distance <= radius &&
      (found === null || distance < Math.abs(found - value))
    ) {
      found = point;
    }
  }
  return found;
}

/** Whether a gesture asks to ignore the grid: Cmd on a Mac, Ctrl elsewhere. */
export function bypassesGrid(event: {
  ctrlKey?: boolean;
  metaKey?: boolean;
}): boolean {
  return Boolean(event.metaKey || event.ctrlKey);
}

/** The snap point within reach of `value`, or else the grid line nearest it. */
export function snapToGrid(value: number, grid: Grid): number {
  const point = nearestSnapPoint(value, grid);
  if (point !== null) {
    return point;
  }
  if (!(grid.step > 0)) {
    return value;
  }
  return (
    Math.round((value - grid.offset) / grid.step) * grid.step + grid.offset
  );
}

/**
 * Where something dragged from `origin` should land, given where the pointer
 * would put it. A snap point within reach wins. Otherwise two answers are
 * reasonable, and the one nearer the pointer wins: on a grid line, or moved
 * by a whole number of steps from where it was. Without the second, anything that starts between two lines jumps onto
 * one the moment it is touched, and can never move by exactly one step.
 */
export function snapMove(target: number, origin: number, grid: Grid): number {
  const point = nearestSnapPoint(target, grid);
  if (point !== null) {
    return point;
  }
  if (!(grid.step > 0)) {
    return target;
  }
  const onLine = snapToGrid(target, grid);
  const bySteps =
    origin + Math.round((target - origin) / grid.step) * grid.step;
  return Math.abs(onLine - target) <= Math.abs(bySteps - target)
    ? onLine
    : bySteps;
}

/**
 * Where a span `length` long, dragged from `origin`, should start when the
 * pointer would start it at `target`: either of its edges lands on a snap
 * point within reach (the nearer one wins), or else its start snaps the way
 * anything dragged does.
 */
export function snapSpanMove(
  target: number,
  origin: number,
  length: number,
  grid: Grid
): number {
  const startPoint = nearestSnapPoint(target, grid);
  const endPoint = nearestSnapPoint(target + length, grid);
  if (startPoint !== null || endPoint !== null) {
    if (endPoint === null) {
      return startPoint ?? target;
    }
    if (
      startPoint === null ||
      Math.abs(endPoint - (target + length)) < Math.abs(startPoint - target)
    ) {
      return endPoint - length;
    }
    return startPoint;
  }
  return snapMove(target, origin, { ...grid, points: undefined });
}

/** The grid without the given points, so something dragged is not pulled onto its own edges. */
export function withoutSnapPoints(grid: Grid, own: readonly number[]): Grid {
  return grid.points?.length
    ? { ...grid, points: grid.points.filter((point) => !own.includes(point)) }
    : grid;
}

/**
 * Where one edge of a range dragged from `origin`, or the whole range with
 * `"both"`, should land when the pointer has moved it by `delta`: the
 * dragged edge snaps the way anything dragged does, and the range keeps
 * within the timeline and its minimum length.
 */
export function snapRangeMove(
  origin: RangeValue,
  edge: RangeEdge,
  delta: number,
  limits: RangeLimits,
  grid: Grid
): RangeValue {
  if (edge === "both") {
    const length = origin[1] - origin[0];
    return moveRange(
      origin,
      edge,
      snapSpanMove(origin[0] + delta, origin[0], length, grid) - origin[0],
      limits
    );
  }
  const from = edge === "end" ? origin[1] : origin[0];
  return moveRange(
    origin,
    edge,
    snapMove(from + delta, from, grid) - from,
    limits
  );
}

import { createEdgeScroll, screenScale, scrollParent } from "./edge-scroll";
import {
  type ChangeEventDetails,
  type CommitEventDetails,
  createChangeEventDetails,
  createPointerLock,
} from "../primitive";
import {
  type ClipLimits,
  type ClipValue,
  clipEnd,
  type FadeShape,
  moveClip,
  nextFadeShape,
  setClipFadeIn,
  setClipFadeOut,
  setClipFadeShape,
  trimClipEnd,
  trimClipStart,
} from "./clip";
import {
  bypassesGrid,
  type Grid,
  SNAP_RADIUS_PX,
  snapMove,
  snapSpanMove,
  withoutSnapPoints,
  withSnapRadius,
} from "../grid";

/** What a change to the clip moves. */
export type ClipTarget =
  | "fade-in"
  | "fade-out"
  | "move"
  | "trim-end"
  | "trim-start";

type WithTarget<Details> = Details & {
  /** Whether Alt was held when the drag began: the clip is meant to be copied to where it lands. */
  copy?: boolean;
  /** For a move: how far the clip moved from where it was when the drag began, in the timeline's units. */
  delta?: number;
  /** The lane under the pointer while the clip is dragged, or null when it is over none. */
  lane?: Element | null;
  /** What moved. */
  target: ClipTarget;
};

/** What `onValueChange` receives with each change to a clip: what moved (`target`), for a move how far and over which lane, whether Alt asks for a copy, the reason (`"drag"`, `"keyboard"`, `"input-change"` or `"double-click"`), the event, and `cancel()` to refuse the change. */
export type ClipChangeEventDetails = WithTarget<
  | ChangeEventDetails<"drag", PointerEvent>
  | ChangeEventDetails<"keyboard", KeyboardEvent>
  | ChangeEventDetails<"input-change", Event>
  | ChangeEventDetails<"double-click", MouseEvent>
>;
/** What `onValueCommitted` receives once a gesture on a clip ends: what moved, the reason and the event behind it. */
export type ClipCommitEventDetails = WithTarget<
  | CommitEventDetails<"drag", PointerEvent>
  | CommitEventDetails<"keyboard", KeyboardEvent>
  | CommitEventDetails<"input-change", Event>
  | CommitEventDetails<"double-click", MouseEvent>
>;

/** How far an edge is searched, in the timeline's units: far enough to reach any limit. */
const FAR = 1e12;

/** The options of `createClipController`: the clip and its selection, each held or controlled, the timeline's length, grid, steps and zoom, the shortest length, the source's length, and the callbacks. */
export interface ClipOptions {
  /** Whether additive selection reports every press, as one with Shift, Cmd or Ctrl does. */
  additive?: boolean;
  defaultSelected?: boolean;
  /** Uncontrolled starting clip. Defaults to the whole timeline. */
  defaultValue?: ClipValue;
  disabled?: boolean;
  duration: number;
  grid: Grid;
  largeStep: number;
  /** The shortest the clip can be trimmed to, in the timeline's units. */
  minLength: number;
  /** Whether the header, or the keys, can move the clip. */
  movable: boolean;
  onDragOffsetChange?: (offset: number) => void;
  /** Fires when Delete or Backspace is pressed on the clip. */
  onRemove?: (event: KeyboardEvent) => void;
  onSelectedChange?: (
    selected: boolean,
    details: ChangeEventDetails<"press", PointerEvent>
  ) => void;
  onValueChange?: (value: ClipValue, details: ClipChangeEventDetails) => void;
  onValueCommitted?: (
    value: ClipValue,
    details: ClipCommitEventDetails
  ) => void;
  /** The controlled selection. */
  selected?: boolean;
  sourceLength?: number;
  step: number;
  /** The controlled clip. */
  value?: ClipValue;
  /** Whether the timeline's zoom is set: px per unit, or null while it fits its lane. */
  zoom: number | null;
}

/** What a view draws a clip from: its value, whether it is selected, and what a drag is moving and by how much. */
export interface ClipSnapshot {
  disabled: boolean;
  /** Whether a pointer is moving, trimming or fading the clip. */
  dragging: boolean;
  /** px the clip has been dragged up or down, while a move is under way. */
  dragOffset: number;
  /** What a pointer is dragging: the clip, an edge or a fade; null between drags. */
  dragTarget: ClipTarget | null;
  selected: boolean;
  /** The clip as displayed: the dragged one while a pointer moves it. */
  value: ClipValue;
}

/** The clip as the timeline holds it: finite, on the timeline, fades within its length. */
export function normalizeClip(clip: ClipValue, duration: number): ClipValue {
  const finite = (value: number, fallback = 0) =>
    Number.isFinite(value) ? value : fallback;
  const start = Math.min(duration, Math.max(0, finite(clip.start)));
  const length = Math.min(duration - start, Math.max(0, finite(clip.length)));
  const fadeIn = Math.min(length, Math.max(0, finite(clip.fadeIn)));
  const fadeOut = Math.min(length - fadeIn, Math.max(0, finite(clip.fadeOut)));
  return {
    fadeIn,
    fadeInShape: clip.fadeInShape,
    fadeOut,
    fadeOutShape: clip.fadeOutShape,
    length,
    offset: Math.max(0, finite(clip.offset)),
    start,
  };
}

/** The clip a timeline without one starts with: the whole of it, from the source's start. */
export function wholeClip(duration: number): ClipValue {
  return { fadeIn: 0, fadeOut: 0, length: duration, offset: 0, start: 0 };
}

/** The keys' targets for an edge or a clip, moved by the keyboard. */
export function keyTargets(
  current: number,
  step: number,
  largeStep: number,
  shiftKey: boolean,
  bounds: readonly [number, number]
): Record<string, number> {
  const arrowStep = shiftKey ? largeStep : step;
  return {
    ArrowDown: current - arrowStep,
    ArrowLeft: current - arrowStep,
    ArrowRight: current + arrowStep,
    ArrowUp: current + arrowStep,
    End: bounds[1],
    Home: bounds[0],
    PageDown: current - largeStep,
    PageUp: current + largeStep,
  };
}

/** The lane the pointer is over, if any: the element that marks itself as one. */
export function laneUnder(event: PointerEvent): Element | null {
  const elements = document.elementsFromPoint?.(event.clientX, event.clientY);
  return (
    elements?.find((element) => element.hasAttribute("data-timeline-lane")) ??
    null
  );
}

/**
 * The lane a moved clip is over: the one under the pointer or, off the lanes
 * (over a track header, the ruler, or past the last lane, where a drag ends up
 * after scrolling to the bottom), the nearest of the timeline's lanes above or
 * below it.
 */
function laneAt(event: PointerEvent, scope: Element | null): Element | null {
  const under = laneUnder(event);
  if (under || !scope) {
    return under;
  }
  let nearest: Element | null = null;
  let best = Number.POSITIVE_INFINITY;
  for (const lane of scope.querySelectorAll("[data-timeline-lane]")) {
    const box = lane.getBoundingClientRect();
    const distance = Math.max(
      box.top - event.clientY,
      event.clientY - box.bottom,
      0
    );
    if (distance < best) {
      best = distance;
      nearest = lane;
    }
  }
  return nearest;
}

/**
 * The views a drag from `handle` scrolls near their edges: the timeline's own
 * across, its edge zone starting after the track headers that stay at its
 * start, and, for a move, the nearest view that scrolls down.
 */
function edgeViews(
  view: HTMLElement | null,
  handle: Element,
  lane: Element | null,
  vertical: boolean
) {
  const across =
    view && view.scrollWidth > view.clientWidth
      ? {
          // Where the lanes begin in what scrolls, in client px: the headers cover what is before.
          covered: lane
            ? Math.max(
                0,
                lane.getBoundingClientRect().left -
                  view.getBoundingClientRect().left +
                  view.scrollLeft * screenScale(view)
              )
            : 0,
          element: view,
        }
      : null;
  const down = vertical ? scrollParent(handle, "y") : null;
  return {
    x: across,
    y: down ? { element: down } : null,
  };
}

/** The new clip a drag of `target` makes, when the pointer has moved by `delta` units. */
function draggedClip(
  target: ClipTarget,
  origin: ClipValue,
  delta: number,
  grid: Grid,
  limits: ClipLimits
): ClipValue {
  if (target === "move") {
    return moveClip(
      origin,
      snapSpanMove(origin.start + delta, origin.start, origin.length, grid),
      limits
    );
  }
  if (target === "trim-start") {
    return trimClipStart(
      origin,
      snapMove(origin.start + delta, origin.start, grid),
      limits
    );
  }
  if (target === "trim-end") {
    const end = clipEnd(origin);
    return trimClipEnd(origin, snapMove(end + delta, end, grid), limits);
  }
  if (target === "fade-in") {
    return setClipFadeIn(origin, origin.fadeIn + delta);
  }
  return setClipFadeOut(origin, origin.fadeOut - delta);
}

/** The value of an edge of the clip, by the target that moves it. */
function edgeOf(clip: ClipValue, target: EdgeTarget): number {
  if (target === "fade-in") {
    return clip.fadeIn;
  }
  if (target === "fade-out") {
    return clip.fadeOut;
  }
  return target === "trim-start" ? clip.start : clipEnd(clip);
}

/** The clip with an edge set to `to`, as the target moves it, within its limits. */
function clipWithEdge(
  clip: ClipValue,
  target: EdgeTarget,
  to: number,
  limits: ClipLimits
): ClipValue {
  if (target === "trim-start") {
    return trimClipStart(clip, to, limits);
  }
  if (target === "trim-end") {
    return trimClipEnd(clip, to, limits);
  }
  if (target === "fade-in") {
    return setClipFadeIn(clip, to);
  }
  return setClipFadeOut(clip, to);
}

/** Where an edge can go: a fade stops where the other fade meets it, a trim where the source or the timeline does. */
function edgeBounds(
  clip: ClipValue,
  target: EdgeTarget,
  limits: ClipLimits
): readonly [number, number] {
  if (target === "fade-in") {
    return [0, Math.max(0, clip.length - clip.fadeOut)];
  }
  if (target === "fade-out") {
    return [0, Math.max(0, clip.length - clip.fadeIn)];
  }
  if (target === "trim-start") {
    return [
      trimClipStart(clip, -FAR, limits).start,
      trimClipStart(clip, FAR, limits).start,
    ];
  }
  const low = trimClipEnd(clip, -FAR, limits);
  return [low.start + low.length, clipEnd(trimClipEnd(clip, FAR, limits))];
}

/** Whether two clips hold the same values. */
export function sameClip(a: ClipValue, b: ClipValue): boolean {
  return (
    a.start === b.start &&
    a.length === b.length &&
    a.offset === b.offset &&
    a.fadeIn === b.fadeIn &&
    a.fadeOut === b.fadeOut &&
    a.fadeInShape === b.fadeInShape &&
    a.fadeOutShape === b.fadeOutShape
  );
}

interface ClipGesture {
  changed: boolean;
  copy: boolean;
  /** The clip when the pointer went down: the drag is measured from it. */
  origin: ClipValue;
  /** The lane the press began in, so a drop onto another one counts as a change. */
  originLane: Element | null;
  startX: number;
  startY: number;
  /** What the gesture drags. */
  target: ClipTarget;
}

/** The edges a fade or a trim moves. */
type EdgeTarget = "fade-in" | "fade-out" | "trim-start" | "trim-end";

/** What `createClipController` returns: the snapshot to draw from, and the presses, keys, typed values and fade shapes that move, trim and fade the clip, and select it. */
export interface ClipController {
  /** Steps a fade to its next shape, from a double click or the keys. */
  cycleFadeShape: (
    edge: "in" | "out",
    reason: "double-click" | "keyboard",
    event: Event
  ) => void;
  /** Keys on a fade or trim handle: arrows and Page keys move the edge, Home and End go to its limits, and Delete takes a fade away. Returns `true` when the handle takes the key. */
  edgeKeyDown: (
    target: "fade-in" | "fade-out" | "trim-start" | "trim-end",
    event: KeyboardEvent
  ) => boolean;
  /** The range an edge can take, found by trimming it as far as it goes. */
  edgeRange: (target: EdgeTarget) => readonly [number, number];
  /** An input moves an edge to a position. */
  edgeTypeAt: (
    target: "fade-in" | "fade-out" | "trim-start" | "trim-end",
    to: number,
    event: Event
  ) => void;
  getSnapshot: () => ClipSnapshot;
  /** Keys on the clip itself: Delete removes, arrows move it. Returns `true` when the clip takes the key. */
  keyDown: (event: KeyboardEvent) => boolean;
  /** An input moves the clip to a start. */
  moveTypeAt: (start: number, event: Event) => void;
  /** Starts a drag of `target` from `handle`; `lane` is the one the clip sits on, which turns px into units. */
  press: (
    target: ClipTarget,
    event: PointerEvent,
    handle: Element,
    lane: Element | null
  ) => void;
  /** Marks the clip selected, from a press on it. */
  select: (event: PointerEvent) => void;
  setOptions: (options: ClipOptions) => void;
  subscribe: (listener: () => void) => () => void;
}

/**
 * A clip's behavior with no view attached: its span, held or controlled,
 * moved, trimmed or faded by the pointer or the keys, and selected.
 */
export function createClipController(initial: ClipOptions): ClipController {
  let options = initial;
  const pointers = createPointerLock();
  const limits = (): ClipLimits => ({
    duration: options.duration,
    minLength: options.minLength,
    sourceLength: options.sourceLength,
  });

  let uncontrolled: ClipValue | undefined;
  // The clip as the gesture under way left it; reset on every render, unless a drag is under way.
  let latest: ClipValue | null = null;
  let dragging = false;
  let dragOffset = 0;
  let gesture: ClipGesture | null = null;
  let uncontrolledSelected = options.defaultSelected ?? false;
  const listeners = new Set<() => void>();
  const notify = () => {
    for (const listener of listeners) {
      listener();
    }
  };

  const held = (): ClipValue =>
    normalizeClip(
      options.value ??
        uncontrolled ??
        options.defaultValue ??
        wholeClip(options.duration),
      options.duration
    );
  const current = (): ClipValue => latest ?? held();
  const isSelected = () => options.selected ?? uncontrolledSelected;

  let snapshot: ClipSnapshot | null = null;
  const getSnapshot = (): ClipSnapshot => {
    const value = dragging && latest !== null ? latest : held();
    const dragTarget = dragging ? (gesture?.target ?? null) : null;
    const disabled = options.disabled ?? false;
    const selected = isSelected();
    if (
      snapshot &&
      sameClip(snapshot.value, value) &&
      snapshot.dragging === dragging &&
      snapshot.disabled === disabled &&
      snapshot.selected === selected &&
      snapshot.dragOffset === dragOffset &&
      snapshot.dragTarget === dragTarget
    ) {
      return snapshot;
    }
    snapshot = { disabled, dragging, dragOffset, dragTarget, selected, value };
    return snapshot;
  };

  /** Reports a change; keeps it unless canceled. */
  const change = (next: ClipValue, details: ClipChangeEventDetails) => {
    if (sameClip(next, current())) {
      return false;
    }
    options.onValueChange?.(next, details);
    if (details.isCanceled) {
      return false;
    }
    latest = next;
    if (options.value === undefined) {
      uncontrolled = next;
    }
    notify();
    return true;
  };

  const commit = (value: ClipValue, details: ClipCommitEventDetails) => {
    options.onValueCommitted?.(value, details);
  };

  const setDragOffset = (pixels: number) => {
    dragOffset = pixels;
    options.onDragOffsetChange?.(pixels);
    notify();
  };

  const setDragging = (next: boolean) => {
    dragging = next;
    if (!next) {
      latest = null;
      setDragOffset(0);
    }
    notify();
  };

  const select = (event: PointerEvent) => {
    // A selected clip is not reported again, unless the press carries Shift,
    // Cmd or Ctrl, or the clip is additive: that is how a selection is built.
    if (
      isSelected() &&
      !(options.additive || event.shiftKey || event.metaKey || event.ctrlKey)
    ) {
      return;
    }
    const details = createChangeEventDetails("press", event);
    options.onSelectedChange?.(true, details);
    if (!details.isCanceled && options.selected === undefined) {
      uncontrolledSelected = true;
      notify();
    }
  };

  const unitsPerPixel = (lane: Element | null) => {
    if (options.zoom !== null) {
      return 1 / options.zoom;
    }
    const width = lane?.getBoundingClientRect().width ?? 0;
    return options.duration / Math.max(width, 1);
  };

  const press: ClipController["press"] = (target, event, handle, lane) => {
    if (options.disabled || event.button !== 0 || !pointers.claim(event)) {
      return;
    }
    if (target === "move" && !options.movable) {
      return;
    }
    handle.setPointerCapture?.(event.pointerId);
    const started: ClipGesture = {
      changed: false,
      copy: target === "move" && event.altKey,
      target,
      origin: current(),
      originLane: target === "move" ? laneUnder(event) : null,
      startX: event.clientX,
      startY: event.clientY,
    };
    gesture = started;
    select(event);
    dragging = true;
    notify();
    // The timeline's own view holds every lane of it: where a clip moved off them finds the nearest.
    const view = handle.closest<HTMLElement>("[data-timeline-viewport]");
    let last = event;
    /** Puts the clip where the pointer is, the views' scroll since the press counted in: it stays under the pointer while they scroll. */
    const place = (move: PointerEvent) => {
      const units = unitsPerPixel(lane);
      const shift = edges.shift();
      const delta = (move.clientX - started.startX + shift.x) * units;
      // The clip's own edges are not places for it to snap to.
      const grid = bypassesGrid(move)
        ? { offset: 0, step: 0 }
        : withSnapRadius(
            withoutSnapPoints(options.grid, [
              started.origin.start,
              clipEnd(started.origin),
            ]),
            units * SNAP_RADIUS_PX
          );
      const next = draggedClip(target, started.origin, delta, grid, limits());
      if (target === "move") {
        setDragOffset(move.clientY - started.startY + shift.y);
      }
      const details = Object.assign(createChangeEventDetails("drag", move), {
        copy: started.copy,
        delta:
          target === "move" ? next.start - started.origin.start : undefined,
        lane: target === "move" ? laneAt(move, view) : undefined,
        target,
      }) as ClipChangeEventDetails;
      if (change(next, details)) {
        started.changed = true;
      }
    };
    // A move or a trim taken near an edge of the view scrolls it, and a move scrolls down to the lanes below too.
    const edges = createEdgeScroll(
      target === "move" || target === "trim-start" || target === "trim-end"
        ? edgeViews(view, handle, lane, target === "move")
        : {},
      () => place(last)
    );
    pointers.follow(
      handle,
      event,
      (move) => {
        last = move;
        edges.follow(move.clientX, move.clientY);
        place(move);
      },
      (end) => {
        edges.stop();
        const finished = gesture;
        gesture = null;
        // Read before settling: the clip falls back to the known value after.
        const committed = current();
        const dropLane = target === "move" ? laneAt(end, view) : undefined;
        setDragging(false);
        const didChange = finished?.changed ?? false;
        if (didChange || (dropLane && dropLane !== started.originLane)) {
          commit(committed, {
            copy: started.copy,
            delta:
              target === "move"
                ? committed.start - started.origin.start
                : undefined,
            event: end,
            lane: dropLane,
            reason: "drag",
            target,
          } as ClipCommitEventDetails);
        }
      }
    );
  };

  /** Moves the whole clip so it starts at `start`, from an input or the keys. */
  const moveTo = (
    start: number,
    reason: "input-change" | "keyboard",
    event: Event
  ) => {
    if (options.disabled || !options.movable) {
      return;
    }
    const next = moveClip(current(), start, limits());
    const details = Object.assign(createChangeEventDetails(reason, event), {
      target: "move" as const,
    }) as ClipChangeEventDetails;
    if (change(next, details)) {
      commit(current(), {
        event,
        reason,
        target: "move",
      } as ClipCommitEventDetails);
    }
  };

  const keyDown: ClipController["keyDown"] = (event) => {
    if (options.disabled) {
      return false;
    }
    if (event.key === "Delete" || event.key === "Backspace") {
      event.preventDefault();
      options.onRemove?.(event);
      return true;
    }
    if (!options.movable) {
      return false;
    }
    const latestClip = current();
    const targets = keyTargets(
      latestClip.start,
      options.step,
      options.largeStep,
      event.shiftKey,
      [0, Math.max(0, options.duration - latestClip.length)]
    );
    const to = targets[event.key];
    if (to === undefined) {
      return false;
    }
    moveTo(to, "keyboard", event);
    return true;
  };

  const edgeRange: ClipController["edgeRange"] = (target) =>
    edgeBounds(current(), target, limits());

  /** Sets a fade or trims an edge to `to`, reporting the change as `reason`. */
  const setEdge = (
    target: EdgeTarget,
    to: number,
    reason: "input-change" | "keyboard",
    event: Event
  ) => {
    const next = clipWithEdge(current(), target, to, limits());
    const details = Object.assign(createChangeEventDetails(reason, event), {
      target,
    }) as ClipChangeEventDetails;
    if (change(next, details)) {
      commit(current(), { event, reason, target } as ClipCommitEventDetails);
    }
  };

  const edgeKeyDown: ClipController["edgeKeyDown"] = (target, event) => {
    if (options.disabled) {
      return false;
    }
    const clip = current();
    // Delete takes a fade away.
    const removes =
      (target === "fade-in" || target === "fade-out") &&
      (event.key === "Delete" || event.key === "Backspace");
    const to = removes
      ? 0
      : keyTargets(
          edgeOf(clip, target),
          options.step,
          options.largeStep,
          event.shiftKey,
          edgeBounds(clip, target, limits())
        )[event.key];
    if (to === undefined) {
      return false;
    }
    event.preventDefault();
    setEdge(target, to, "keyboard", event);
    return true;
  };

  const cycleFadeShape: ClipController["cycleFadeShape"] = (
    edge,
    reason,
    event
  ) => {
    if (options.disabled) {
      return;
    }
    const latestClip = current();
    const shape: FadeShape = nextFadeShape(
      edge === "in" ? latestClip.fadeInShape : latestClip.fadeOutShape
    );
    const next = setClipFadeShape(latestClip, edge, shape);
    const target = edge === "in" ? "fade-in" : "fade-out";
    const details = Object.assign(createChangeEventDetails(reason, event), {
      target,
    }) as ClipChangeEventDetails;
    if (change(next, details)) {
      commit(current(), { event, reason, target } as ClipCommitEventDetails);
    }
  };

  return {
    cycleFadeShape,
    edgeKeyDown,
    edgeRange,
    edgeTypeAt: (target, to, event) => {
      if (!options.disabled) {
        setEdge(target, to, "input-change", event);
      }
    },
    getSnapshot,
    keyDown,
    moveTypeAt: (start, event) => moveTo(start, "input-change", event),
    press,
    select,
    setOptions: (next) => {
      options = next;
      if (!dragging) {
        latest = null;
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

import { clamp } from "@ui-sdk/core/number";
import { clampFinite } from "../grid";

/**
 * A clip: a stretch of a source (a recording, a pattern) placed on the
 * timeline. All lengths are in the timeline's units, the source's included.
 */
export interface ClipValue {
  /** How long the clip's fade-in lasts, from its start. */
  fadeIn: number;
  /** How the fade-in rises. @default "linear" */
  fadeInShape?: FadeShape;
  /** How long the clip's fade-out lasts, up to its end. */
  fadeOut: number;
  /** How the fade-out falls. @default "linear" */
  fadeOutShape?: FadeShape;
  /** How long the clip is on the timeline. */
  length: number;
  /** Where in the source the clip begins: what trimming its start moves. */
  offset: number;
  /** Where the clip begins on the timeline. */
  start: number;
}

/** How a fade rises or falls: evenly, quick then slow, slow then quick, or eased at both ends. */
export type FadeShape = "fast" | "linear" | "slow" | "smooth";

/** The fade shapes in the order a control steps through them. */
export const FADE_SHAPES: readonly FadeShape[] = [
  "linear",
  "fast",
  "slow",
  "smooth",
];

/** The shape after `shape`, going round, for a control that steps through them. */
export function nextFadeShape(shape: FadeShape = "linear"): FadeShape {
  return (
    FADE_SHAPES[(FADE_SHAPES.indexOf(shape) + 1) % FADE_SHAPES.length] ??
    "linear"
  );
}

/**
 * The gain a fade of `shape` has `progress` of the way through it, from 0
 * (silent) to 1 (full): the curve of a fade-in; a fade-out plays it backwards.
 */
export function fadeGain(shape: FadeShape, progress: number): number {
  const t = clamp(progress, 0, 1);
  switch (shape) {
    case "fast":
      return 1 - (1 - t) * (1 - t);
    case "slow":
      return t * t;
    case "smooth":
      return t * t * (3 - 2 * t);
    default:
      return t;
  }
}

/** What a clip edit keeps a clip within: the timeline's length, the shortest it may be, and its source's length. */
export interface ClipLimits {
  /** The length of the timeline the clip sits on. */
  duration: number;
  /** The shortest a clip may be trimmed to. @default 0 */
  minLength?: number;
  /** The length of the source: a clip cannot show more than it holds. @default Infinity */
  sourceLength?: number;
}

/** Where the clip ends on the timeline. */
export function clipEnd(clip: ClipValue): number {
  return clip.start + clip.length;
}

/** The fades, shortened so that together they fit in the clip. */
function fitFades(clip: ClipValue): ClipValue {
  const fadeIn = clamp(clip.fadeIn, 0, clip.length);
  const fadeOut = clamp(clip.fadeOut, 0, clip.length - fadeIn);
  return fadeIn === clip.fadeIn && fadeOut === clip.fadeOut
    ? clip
    : { ...clip, fadeIn, fadeOut };
}

/** Moves the clip to begin at `start`, keeping its length and its place in the source. */
export function moveClip(
  clip: ClipValue,
  start: number,
  limits: ClipLimits
): ClipValue {
  const latest = Math.max(0, limits.duration - clip.length);
  return { ...clip, start: clampFinite(start, 0, latest) };
}

/**
 * Trims the clip's start to `start`: what is cut off stays in the source, so
 * the clip's content does not move on the timeline. Trimming back reveals the
 * source again, as far as its beginning.
 */
export function trimClipStart(
  clip: ClipValue,
  start: number,
  limits: ClipLimits
): ClipValue {
  const minLength = limits.minLength ?? 0;
  const earliest = Math.max(0, clip.start - clip.offset);
  const latest = Math.max(earliest, clipEnd(clip) - minLength);
  const next = clampFinite(start, earliest, latest);
  const delta = next - clip.start;
  return fitFades({
    ...clip,
    length: clip.length - delta,
    offset: clip.offset + delta,
    start: next,
  });
}

/**
 * Trims the clip's end to `end`, as far as the timeline and the source allow.
 */
export function trimClipEnd(
  clip: ClipValue,
  end: number,
  limits: ClipLimits
): ClipValue {
  const minLength = limits.minLength ?? 0;
  const sourceLength = limits.sourceLength ?? Number.POSITIVE_INFINITY;
  const earliest = Math.min(limits.duration, clip.start + minLength);
  const latest = Math.max(
    earliest,
    Math.min(limits.duration, clip.start + (sourceLength - clip.offset))
  );
  const next = clampFinite(end, earliest, latest);
  return fitFades({ ...clip, length: next - clip.start });
}

/** Gives the fade at `edge` the shape `shape`. */
export function setClipFadeShape(
  clip: ClipValue,
  edge: "in" | "out",
  shape: FadeShape
): ClipValue {
  return edge === "in"
    ? { ...clip, fadeInShape: shape }
    : { ...clip, fadeOutShape: shape };
}

/** Sets the fade-in's length, which cannot run into the fade-out. */
export function setClipFadeIn(clip: ClipValue, fadeIn: number): ClipValue {
  return {
    ...clip,
    fadeIn: clampFinite(fadeIn, 0, Math.max(0, clip.length - clip.fadeOut)),
  };
}

/** Sets the fade-out's length, which cannot run into the fade-in. */
export function setClipFadeOut(clip: ClipValue, fadeOut: number): ClipValue {
  return {
    ...clip,
    fadeOut: clampFinite(fadeOut, 0, Math.max(0, clip.length - clip.fadeIn)),
  };
}

/**
 * Cuts the clip in two at `at`, a position on the timeline. The pieces play
 * the same source, in the same place: the right one picks up where the left
 * one stops. Each keeps its own outer fade, and the cut has none. Returns null
 * when `at` leaves either piece shorter than `minLength`.
 */
export function splitClip(
  clip: ClipValue,
  at: number,
  minLength = 0
): [left: ClipValue, right: ClipValue] | null {
  const end = clipEnd(clip);
  const floor = Math.max(minLength, Number.EPSILON);
  if (!(at - clip.start >= floor && end - at >= floor)) {
    return null;
  }
  const { fadeOutShape: _cutOut, ...leftBase } = clip;
  const left = fitFades({
    ...leftBase,
    fadeOut: 0,
    length: at - clip.start,
  });
  const { fadeInShape: _cutIn, ...rightBase } = clip;
  const right = fitFades({
    ...rightBase,
    fadeIn: 0,
    length: end - at,
    offset: clip.offset + (at - clip.start),
    start: at,
  });
  return [left, right];
}

/**
 * A copy of the clip placed right after it, or as late as the timeline
 * allows when there is not room for it.
 */
export function duplicateClip(clip: ClipValue, limits: ClipLimits): ClipValue {
  return moveClip(clip, clipEnd(clip), limits);
}

/**
 * What a clip laid on a lane leaves of the clips already there: they are
 * covered, not stacked. A clip the new one lies wholly over goes; one it
 * overlaps by an edge is trimmed to what is left; one it lies inside is cut
 * in two around it. Items are anything with a `value`, so the rest of what
 * the app keeps about a clip travels with each piece. `split` makes the
 * second piece's item from the first's. Only the timeline's length is read
 * from `limits`: covering only shortens a clip, so no source limits it.
 */
export function coverClips<Item extends { value: ClipValue }>(
  items: readonly Item[],
  placed: ClipValue,
  limits: Pick<ClipLimits, "duration">,
  split: (item: Item, value: ClipValue) => Item
): Item[] {
  const from = placed.start;
  const to = clipEnd(placed);
  const loose = { duration: limits.duration, minLength: 0 };
  const result: Item[] = [];
  for (const item of items) {
    const { value } = item;
    const end = clipEnd(value);
    if (end <= from || value.start >= to) {
      result.push(item);
      continue;
    }
    const keepsLeft = value.start < from;
    const keepsRight = end > to;
    if (keepsLeft) {
      result.push({
        ...item,
        value: trimClipEnd(value, from, loose),
      });
    }
    if (keepsRight) {
      const right = trimClipStart(value, to, loose);
      result.push(keepsLeft ? split(item, right) : { ...item, value: right });
    }
  }
  return result;
}

/** The part of `clip` between `from` and `to`, or null when it has none there. */
function clipPart(
  clip: ClipValue,
  from: number,
  to: number,
  limits: Pick<ClipLimits, "duration">
): ClipValue | null {
  if (clipEnd(clip) <= from || clip.start >= to) {
    return null;
  }
  const loose = { duration: limits.duration, minLength: 0 };
  const started = clip.start < from ? trimClipStart(clip, from, loose) : clip;
  return clipEnd(started) > to ? trimClipEnd(started, to, loose) : started;
}

/**
 * What the stretch from `from` to `to` holds of `items`: the part of each
 * clip inside it, moved so the stretch starts at 0. Each part keeps its
 * place in its source. Lay them back at `at` by adding `at` to their starts.
 */
export function copyRange<Item extends { value: ClipValue }>(
  items: readonly Item[],
  from: number,
  to: number,
  limits: Pick<ClipLimits, "duration">
): Item[] {
  const parts: Item[] = [];
  for (const item of items) {
    const part = clipPart(item.value, from, to, limits);
    if (part) {
      parts.push({ ...item, value: { ...part, start: part.start - from } });
    }
  }
  return parts;
}

/**
 * Takes the stretch from `from` to `to` out of the timeline: what is in it
 * goes, and everything after it moves back to close the gap. A clip across
 * it keeps its two ends, which then meet; `split` makes the second piece's
 * item from the first's, as with `coverClips`.
 */
export function removeTime<Item extends { value: ClipValue }>(
  items: readonly Item[],
  from: number,
  to: number,
  limits: Pick<ClipLimits, "duration">,
  split: (item: Item, value: ClipValue) => Item
): Item[] {
  const gap = to - from;
  if (!(gap > 0)) {
    return [...items];
  }
  const span = { fadeIn: 0, fadeOut: 0, length: gap, offset: 0, start: from };
  return coverClips(items, span, limits, split).map((item) =>
    item.value.start >= to
      ? { ...item, value: { ...item.value, start: item.value.start - gap } }
      : item
  );
}

/**
 * Opens a stretch `length` long at `at`: everything from there moves later,
 * and a clip across `at` is cut in two around the gap. What would then run
 * past the end of the timeline is cut off there, or dropped.
 */
export function insertTime<Item extends { value: ClipValue }>(
  items: readonly Item[],
  at: number,
  length: number,
  limits: Pick<ClipLimits, "duration">,
  split: (item: Item, value: ClipValue) => Item
): Item[] {
  if (!(length > 0)) {
    return [...items];
  }
  const loose = { duration: limits.duration, minLength: 0 };
  const later = (item: Item, value: ClipValue): Item[] => {
    const start = value.start + length;
    if (start >= limits.duration) {
      return [];
    }
    const moved = { ...value, start };
    return [
      {
        ...item,
        value:
          clipEnd(moved) > limits.duration
            ? trimClipEnd(moved, limits.duration, loose)
            : moved,
      },
    ];
  };
  return items.flatMap((item) => {
    const { value } = item;
    if (clipEnd(value) <= at) {
      return [item];
    }
    if (value.start >= at) {
      return later(item, value);
    }
    const cut = splitClip(value, at);
    if (!cut) {
      return [item];
    }
    const [left, right] = cut;
    return [{ ...item, value: left }, ...later(split(item, right), right)];
  });
}

import { createChangeEventDetails } from "../primitive";
import {
  type ClipChangeEventDetails,
  type ClipCommitEventDetails,
  type ClipController,
  type ClipTarget,
  createClipController,
} from "./clip-controller";
import { type ClipValue, clipEnd, type FadeShape, fadeGain } from "./clip";
import {
  css,
  dispatch,
  type PrimitiveContext,
  type SlotDefinition,
} from "@ui-sdk/core";
import { flag, sourceOf, VISUALLY_HIDDEN } from "../primitive";
import { laneOf, placedOver, UNIT_PROPERTY, unitLength } from "./layout";
import type {
  DescribePosition,
  TimelineApi,
  TimelinePublicState,
  TimelineState,
} from "./timeline";

/**
 * The clips of the timeline: a stretch of a source laid on a lane. A clip is
 * named by its `clip` prop and holds a controller of its own; its parts (the
 * header, the trim and fade handles, the fade shades, the inputs) carry the
 * same name, and what they report goes through the Root with the name in the
 * details. Only the clip part itself gives its controller its options.
 */

/** The props every part of a clip takes. */
export interface ClipRef {
  /** The name of the clip it belongs to. */
  clip: string;
  id?: string;
}

/** The props of the clip part: its name, and what it holds. */
export interface ClipProps extends ClipRef {
  /** Whether every press is reported, as one with Shift, Cmd or Ctrl held is. @default false */
  additive?: boolean;
  defaultSelected?: boolean;
  defaultValue?: ClipValue;
  disabled?: boolean;
  /** The shortest the clip can be trimmed to. Defaults to the grid step. */
  minLength?: number;
  /** Whether dragging the header, or the keys, moves the clip. @default true */
  movable?: boolean;
  selected?: boolean;
  /** How long the source is: trimming stops where it runs out. */
  sourceLength?: number;
  value?: ClipValue;
}

export interface ClipPublicState extends TimelinePublicState {
  /** Whether a pointer is moving, trimming or fading the clip. */
  dragging: boolean;
  /** The fade a pointer is dragging, if any. */
  fading: "in" | "out" | undefined;
  selected: boolean;
}

export interface ClipEdgeState extends ClipPublicState {
  /** The edge this part works on. */
  edge: "end" | "in" | "out" | "start";
}

/** What a fade shade draws: the area under the curve and the curve itself, in a 1 by 1 box. */
export interface ClipFadeState extends ClipEdgeState {
  fill: string;
  line: string;
}

/** What the clip's change reports: what moved (`target`), for a move how far and over which lane, whether Alt asks for a copy, the reason, the event, and the clip's name. */
export type ClipChangeDetails = ClipChangeEventDetails & {
  clip: string;
  source?: string;
};

/** What a clip's gesture ending reports. */
export type ClipCommitDetails = ClipCommitEventDetails & { clip: string };

type Slot<Props, Public = ClipPublicState> = SlotDefinition<
  TimelineState,
  TimelineApi,
  Props,
  Public
>;

/** The clip slots, by name. */
export type ClipSlots = {
  clip: Slot<ClipProps>;
  clipFadeIn: Slot<ClipRef, ClipFadeState>;
  clipFadeInHandle: Slot<ClipRef, ClipEdgeState>;
  clipFadeInInput: Slot<
    ClipRef & { getAriaValueText?: DescribePosition },
    object
  >;
  clipFadeOut: Slot<ClipRef, ClipFadeState>;
  clipFadeOutHandle: Slot<ClipRef, ClipEdgeState>;
  clipFadeOutInput: Slot<
    ClipRef & { getAriaValueText?: DescribePosition },
    object
  >;
  clipHeader: Slot<ClipRef>;
  clipInput: Slot<ClipRef & { getAriaValueText?: DescribePosition }, object>;
  clipTrimEnd: Slot<ClipRef, ClipEdgeState>;
  clipTrimEndInput: Slot<
    ClipRef & { getAriaValueText?: DescribePosition },
    object
  >;
  clipTrimStart: Slot<ClipRef, ClipEdgeState>;
  clipTrimStartInput: Slot<
    ClipRef & { getAriaValueText?: DescribePosition },
    object
  >;
};

/** What the timeline's `api` gives the clip parts. */
export interface ClipApi {
  /** The controller of the clip named in `props`; the clip part's own props give it its options. */
  clipFor: (
    state: TimelineState,
    props: ClipProps | ClipRef,
    owner?: boolean
  ) => ClipController;
  /** What each clip was given by its own part. */
  clipProps: Map<string, ClipProps>;
}

const describeNumber = (value: number) => String(Math.round(value * 100) / 100);

const SAMPLES = 16;

/** The points of a fade's curve, in a 1 by 1 box with the gain going up. */
function ramp(shape: FadeShape, edge: "in" | "out") {
  const points: string[] = [];
  for (let index = 0; index <= SAMPLES; index += 1) {
    const x = index / SAMPLES;
    const gain = fadeGain(shape, edge === "in" ? x : 1 - x);
    points.push(`${x} ${1 - gain}`);
  }
  return points;
}

const TARGETS = {
  end: "trim-end",
  in: "fade-in",
  out: "fade-out",
  start: "trim-start",
} as const;

/** The controllers of the clips, and what each was given. */
export function createClipApi(
  context: PrimitiveContext<any, any, any>,
  settings: () => {
    duration: number;
    grid: { offset: number; points?: readonly number[]; step: number };
    largeStep: number;
    step: number;
  },
  bump: () => void
): ClipApi {
  const controllers = new Map<string, ClipController>();
  const clipProps = new Map<string, ClipProps>();
  const provisional = new Set<string>();
  /** The controller of a clip: made once, and again when the clip itself first binds after a part that started it. */
  const controllerFor = (name: string, options: object, owner: boolean) => {
    let controller = controllers.get(name);
    // A part that binds before the clip itself (custom elements make what a clip holds as they connect) starts the controller without what the clip was given: the clip starts it again, with it.
    if (controller && owner && provisional.has(name)) {
      provisional.delete(name);
      controller = undefined;
      // The parts that read the early one read this one now.
      queueMicrotask(bump);
    }
    if (controller) {
      if (owner) {
        controller.setOptions(options as never);
      }
    } else {
      controller = createClipController(options as never);
      controller.subscribe(bump);
      controllers.set(name, controller);
      if (!owner) {
        provisional.add(name);
      }
    }
    return controller;
  };
  return {
    clipFor: (state, props, owner = false) => {
      const name = String(props.clip);
      const own = props as ClipProps;
      const { duration, grid, largeStep, step } = settings();
      if (owner) {
        clipProps.set(name, own);
      }
      const options = {
        additive: own.additive ?? false,
        defaultSelected: own.defaultSelected ?? false,
        defaultValue: own.defaultValue,
        disabled: state.view.disabled || Boolean(own.disabled),
        duration,
        grid,
        largeStep,
        minLength: own.minLength ?? (grid.step > 0 ? grid.step : step),
        movable: own.movable ?? true,
        onDragOffsetChange: (offset: number) => {
          dispatch(context, "onClipDragOffsetChange", offset, {
            clip: name,
            reason: "drag",
          });
        },
        onRemove: (event: KeyboardEvent) => {
          dispatch(context, "onClipRemove", name, {
            clip: name,
            event,
            reason: createChangeEventDetails("keyboard", event).reason,
          });
        },
        onSelectedChange: (
          selected: boolean,
          details: { event: PointerEvent; reason: string }
        ) => {
          dispatch(context, "onClipSelectedChange", selected, {
            clip: name,
            event: details.event,
            reason: details.reason,
          });
        },
        onValueChange: (
          value: ClipValue,
          details: {
            cancel: () => void;
            event?: Event;
            reason: string;
          }
        ) => {
          const { cancel, ...rest } = details;
          const source = sourceOf(details.event);
          if (
            dispatch(context, "onClipChange", value, {
              ...rest,
              clip: name,
              ...(source ? { source } : {}),
            })
          ) {
            cancel();
          }
        },
        onValueCommitted: (
          value: ClipValue,
          details: { event?: Event; reason: string }
        ) => {
          dispatch(context, "onClipCommitted", value, {
            ...details,
            clip: name,
          });
        },
        selected: own.selected,
        sourceLength: own.sourceLength,
        step,
        value: own.value,
        // Read when a gesture needs it: a clip is not drawn again at each step of a zoom.
        get zoom() {
          return context.store.get().frame.zoom as number | null;
        },
      };
      return controllerFor(name, options, owner);
    },
    clipProps,
  };
}

/** Which fade a drag is on, if any. */
function fadingOf(target: string | null | undefined): "in" | "out" | undefined {
  if (target === "fade-in") {
    return "in";
  }
  return target === "fade-out" ? "out" : undefined;
}

/** What a clip part reads of its clip. */
function stateOf(
  state: TimelineState,
  api: TimelineApi,
  props: ClipRef
): ClipPublicState {
  const view = api.clipFor(state, props).getSnapshot();
  const fading = fadingOf(view.dragTarget);
  return {
    disabled: view.disabled,
    dragging: view.dragging,
    fading,
    fitted: state.view.fitted,
    scrubbing: state.view.scrubbing,
    selected: view.selected,
  };
}

const attrsOf = (state: ClipPublicState, clip: string) => ({
  "data-clip": clip,
  "data-disabled": flag(state.disabled),
  "data-dragging": flag(state.dragging),
  "data-fading": state.fading,
  "data-fitted": flag(state.fitted),
  "data-selected": flag(state.selected),
});

/** The slots of the clip and its parts. */
export function clipSlots(slot: any) {
  const focusInput = (el: HTMLElement | undefined) =>
    el
      ?.querySelector<HTMLInputElement>('input[type="range"]')
      ?.focus({ preventScroll: true });

  /** A drag of `target` from a part of the clip: the press stops here, so the lane underneath takes none. */
  const press =
    (target: ClipTarget, focus: "clip" | "own") =>
    (
      event: PointerEvent,
      context: {
        api: TimelineApi;
        el: HTMLElement | undefined;
        props: ClipRef;
        store: { get: () => TimelineState };
      }
    ) => {
      const { api, el, props, store } = context;
      if (event.button !== 0) {
        return;
      }
      event.stopPropagation();
      const controller = api.clipFor(store.get(), props);
      const own = api.clipProps.get(String(props.clip));
      const { disabled } = controller.getSnapshot();
      const enabled =
        !disabled && (target !== "move" || (own?.movable ?? true));
      if (!(el && enabled)) {
        return;
      }
      event.preventDefault();
      if (focus === "own") {
        focusInput(el);
      } else {
        focusInput(
          el.closest<HTMLElement>('[data-slot="timeline-clip"]') ?? el
        );
      }
      controller.press(target, event, el, laneOf(el));
    };

  /** A native input of the clip that works on `edge`. */
  const edgeInput = (edge: "end" | "in" | "out" | "start") => {
    const target = TARGETS[edge];
    return slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: any }
      ) => {
        const controller = api.clipFor(state, props);
        const view = controller.getSnapshot();
        const { value } = view;
        const describe = props.getAriaValueText ?? describeNumber;
        const current = {
          end: clipEnd(value),
          in: value.fadeIn,
          out: value.fadeOut,
          start: value.start,
        }[edge];
        const [min, max] =
          edge === "in" || edge === "out"
            ? [
                0,
                Math.max(
                  0,
                  value.length - (edge === "in" ? value.fadeOut : value.fadeIn)
                ),
              ]
            : controller.edgeRange(target);
        return {
          "aria-valuetext": describe(current, state.duration),
          disabled: flag(view.disabled),
          max: String(max),
          min: String(min),
          step: "any",
          style: css(VISUALLY_HIDDEN),
          type: "range",
          value: String(current),
        };
      },
      on: {
        change: (
          event: Event,
          {
            api,
            el,
            props,
            store,
          }: {
            api: TimelineApi;
            el: HTMLElement | undefined;
            props: ClipRef;
            store: { get: () => TimelineState };
          }
        ) =>
          api
            .clipFor(store.get(), props)
            .edgeTypeAt(target, Number((el as HTMLInputElement).value), event),
        keydown: (
          event: KeyboardEvent,
          {
            api,
            props,
            store,
          }: {
            api: TimelineApi;
            props: ClipRef;
            store: { get: () => TimelineState };
          }
        ) => {
          const controller = api.clipFor(store.get(), props);
          if (controller.getSnapshot().disabled) {
            return;
          }
          if ((edge === "in" || edge === "out") && event.key === "Enter") {
            // Enter steps the shape, as it does on the handle's double click.
            event.preventDefault();
            controller.cycleFadeShape(edge, "keyboard", event);
            return;
          }
          if (controller.edgeKeyDown(target, event)) {
            event.preventDefault();
            // Delete took the fade away: it is not for the clip, or the page, to remove anything too.
            if (
              (edge === "in" || edge === "out") &&
              (event.key === "Delete" || event.key === "Backspace")
            ) {
              event.stopPropagation();
            }
          }
        },
      },
      props: { clip: "key", getAriaValueText: "value" },
    });
  };

  /** A handle that trims or fades an edge by dragging. */
  const edgeHandle = (edge: "end" | "in" | "out" | "start") => {
    const fade = edge === "in" || edge === "out";
    return slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: ClipRef }
      ) => {
        const view = stateOf(state, api, props);
        let place = {};
        if (fade) {
          place =
            edge === "in"
              ? {
                  "inset-inline-start":
                    "calc(var(--clip-unit) * var(--clip-fade-in))",
                }
              : {
                  "inset-inline-end":
                    "calc(var(--clip-unit) * var(--clip-fade-out))",
                };
        }
        return {
          ...attrsOf(view, String(props.clip)),
          "data-edge": edge,
          style: css({
            ...place,
            ...(fade ? { position: "absolute" } : {}),
            "touch-action": "none",
          }),
        };
      },
      on: {
        dblclick: (
          event: MouseEvent,
          {
            api,
            props,
            store,
          }: {
            api: TimelineApi;
            props: ClipRef;
            store: { get: () => TimelineState };
          }
        ) => {
          const controller = api.clipFor(store.get(), props);
          if (fade && !controller.getSnapshot().disabled) {
            controller.cycleFadeShape(edge, "double-click", event);
          }
        },
        pointerdown: press(TARGETS[edge], "own"),
      },
      props: { clip: "key" },
      state: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: ClipRef }
      ) => ({ ...stateOf(state, api, props), edge }),
    });
  };

  /** The shade of a fade: its curve, in a 1 by 1 box. */
  const fadeShade = (edge: "in" | "out") =>
    slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: ClipRef }
      ) => {
        const view = api.clipFor(state, props).getSnapshot();
        const length = edge === "in" ? view.value.fadeIn : view.value.fadeOut;
        const property = edge === "in" ? "--clip-fade-in" : "--clip-fade-out";
        return {
          ...attrsOf(stateOf(state, api, props), String(props.clip)),
          "aria-hidden": "true",
          // What a framework that cannot draw from the state draws the curve from.
          "data-edge-in": edge === "in" ? "" : undefined,
          "data-shape":
            (edge === "in"
              ? view.value.fadeInShape
              : view.value.fadeOutShape) ?? "linear",
          focusable: "false",
          preserveAspectRatio: "none",
          style: css({
            // A positioned svg does not stretch between top and bottom without a height. `--clip-fade-top` leaves room above it, from a class: a style given to the part replaces this one.
            display: length > 0 ? undefined : "none",
            height: "calc(100% - var(--clip-fade-top, 0px))",
            "pointer-events": "none",
            position: "absolute",
            top: "var(--clip-fade-top, 0px)",
            width: `calc(var(--clip-unit) * var(${property}))`,
            ...(edge === "in"
              ? { "inset-inline-start": "0" }
              : { "inset-inline-end": "0" }),
          }),
          viewBox: "0 0 1 1",
        };
      },
      props: { clip: "key" },
      state: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: ClipRef }
      ) => {
        const { value } = api.clipFor(state, props).getSnapshot();
        const shape =
          (edge === "in" ? value.fadeInShape : value.fadeOutShape) ?? "linear";
        const points = ramp(shape, edge);
        return {
          ...stateOf(state, api, props),
          edge,
          fill: `M0 0H1L${[...points].reverse().join("L")}Z`,
          line: `M${points.join("L")}`,
        };
      },
    });

  return {
    clip: slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: ClipProps }
      ) => {
        const view = api.clipFor(state, props, true).getSnapshot();
        const { value } = view;
        const { fadeIn, fadeOut, length, offset, start } = value;
        const fading = fadingOf(view.dragTarget);
        return {
          ...attrsOf(
            {
              disabled: view.disabled,
              dragging: view.dragging,
              fading,
              fitted: state.view.fitted,
              scrubbing: state.view.scrubbing,
              selected: view.selected,
            },
            String(props.clip)
          ),
          style: css({
            ...placedOver(start, length),
            "--clip-drag-y": `${view.dragOffset}px`,
            "--clip-fade-in": String(fadeIn),
            // How long each fade can grow: up to where the other one begins.
            "--clip-fade-in-max": String(length - fadeOut),
            "--clip-fade-out": String(fadeOut),
            "--clip-fade-out-max": String(length - fadeIn),
            "--clip-offset": String(offset),
            // A unit inside the clip: fitted, the timeline's unit is a share of the lane, which inside the clip would be a share of the clip.
            "--clip-unit": state.view.fitted
              ? unitLength(null, length)
              : `var(${UNIT_PROPERTY})`,
            ...(props.sourceLength === undefined
              ? {}
              : { "--clip-source-length": String(props.sourceLength) }),
            "touch-action": "none",
            transform: view.dragging
              ? "translateY(var(--clip-drag-y))"
              : undefined,
          }),
        };
      },
      on: {
        // A press on the body selects the clip and puts the cursor there, and a drag scrubs it: the header moves the clip.
        pointerdown: (
          event: PointerEvent,
          {
            api,
            el,
            props,
            store,
          }: {
            api: TimelineApi;
            el: HTMLElement | undefined;
            props: ClipProps;
            store: { get: () => TimelineState };
          }
        ) => {
          const state = store.get();
          const controller = api.clipFor(state, props, true);
          if (
            !el ||
            controller.getSnapshot().disabled ||
            state.view.disabled ||
            event.button !== 0
          ) {
            return;
          }
          controller.select(event);
          const lane = laneOf(el);
          if (lane) {
            api.controller.pressSeek(event, el, lane);
          }
          focusInput(el);
        },
      },
      props: {
        additive: "boolean",
        clip: "key",
        defaultSelected: "boolean",
        defaultValue: "value",
        disabled: "boolean",
        minLength: "number",
        movable: "boolean",
        selected: "boolean",
        sourceLength: "number",
        value: "value",
      },
      state: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: ClipProps }
      ) => ({ ...stateOf(state, api, props) }),
    }),
    clipFadeIn: fadeShade("in"),
    clipFadeInHandle: edgeHandle("in"),
    clipFadeInInput: edgeInput("in"),
    clipFadeOut: fadeShade("out"),
    clipFadeOutHandle: edgeHandle("out"),
    clipFadeOutInput: edgeInput("out"),
    // The strip of the clip that moves it by dragging.
    clipHeader: slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: ClipRef }
      ) => ({
        ...attrsOf(stateOf(state, api, props), String(props.clip)),
        style: css({ "touch-action": "none" }),
      }),
      on: { pointerdown: press("move", "clip") },
      props: { clip: "key" },
      state: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: ClipRef }
      ) => stateOf(state, api, props),
    }),
    // The clip's own native input: it moves the clip from the keyboard and carries its name.
    clipInput: slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: any }
      ) => {
        const controller = api.clipFor(state, props);
        const view = controller.getSnapshot();
        const { value } = view;
        const describe = props.getAriaValueText ?? describeNumber;
        return {
          "aria-valuetext": `${describe(value.start, state.duration)} to ${describe(value.start + value.length, state.duration)}`,
          disabled: flag(view.disabled),
          max: String(Math.max(0, state.duration - value.length)),
          min: "0",
          step: "any",
          style: css(VISUALLY_HIDDEN),
          type: "range",
          value: String(value.start),
        };
      },
      on: {
        change: (
          event: Event,
          {
            api,
            el,
            props,
            store,
          }: {
            api: TimelineApi;
            el: HTMLElement | undefined;
            props: ClipRef;
            store: { get: () => TimelineState };
          }
        ) =>
          api
            .clipFor(store.get(), props)
            .moveTypeAt(Number((el as HTMLInputElement).value), event),
        keydown: (
          event: KeyboardEvent,
          {
            api,
            props,
            store,
          }: {
            api: TimelineApi;
            props: ClipRef;
            store: { get: () => TimelineState };
          }
        ) => {
          if (api.clipFor(store.get(), props).keyDown(event)) {
            event.preventDefault();
          }
        },
      },
      props: { clip: "key", getAriaValueText: "value" },
    }),
    clipTrimEnd: edgeHandle("end"),
    clipTrimEndInput: edgeInput("end"),
    clipTrimStart: edgeHandle("start"),
    clipTrimStartInput: edgeInput("start"),
  } as ClipSlots;
}

import { createFrameTask } from "../frame";

/** How near an edge of a view the pointer is held, in px, for the view to scroll. */
const EDGE_PX = 48;
/** The most a view scrolls in a frame, in px: with the pointer at its edge or past it. */
const MAX_STEP_PX = 24;

/** What each axis reads: the scroll, the edges of a box, and the size of the window. */
const AXES = {
  x: ["scrollLeft", "left", "right", "innerWidth"],
  y: ["scrollTop", "top", "bottom", "innerHeight"],
} as const;

type Axis = keyof typeof AXES;

/**
 * How far a view scrolls this frame for a pointer at `at`, between its
 * visible `start` and `end`: nothing away from them, then faster the nearer
 * the pointer is held to an edge, or the further past it.
 */
export function edgeScrollStep(at: number, start: number, end: number): number {
  if (at < start + EDGE_PX) {
    return -Math.min(MAX_STEP_PX, Math.ceil((start + EDGE_PX - at) / 3));
  }
  if (at > end - EDGE_PX) {
    return Math.min(MAX_STEP_PX, Math.ceil((at - end + EDGE_PX) / 3));
  }
  return 0;
}

/** The nearest element, from `element` up, that scrolls along `axis`: one that lets it and has more to show. */
export function scrollParent(element: Element, axis: Axis): HTMLElement | null {
  for (let node: Element | null = element; node; node = node.parentElement) {
    const style = getComputedStyle(node);
    const overflow = axis === "x" ? style.overflowX : style.overflowY;
    if (
      node instanceof HTMLElement &&
      (overflow === "auto" || overflow === "scroll") &&
      (axis === "x"
        ? node.scrollWidth > node.clientWidth
        : node.scrollHeight > node.clientHeight)
    ) {
      return node;
    }
  }
  return null;
}

/** px on screen for each px of layout, for a view drawn scaled. */
export function screenScale(element: HTMLElement): number {
  return element.offsetWidth > 0
    ? element.getBoundingClientRect().width / element.offsetWidth
    : 1;
}

/** A view that scrolls along one axis. */
export interface EdgeScrollView {
  /** The px at the start of the view that content held there covers, such as sticky headers: its edge zone starts after them. @default 0 */
  covered?: number;
  element: HTMLElement;
}

export interface EdgeScroll {
  /** Where the pointer has moved to, in client px: call it on each move of the drag, not on the press. */
  follow: (x: number, y: number) => void;
  /** How far each view has scrolled since the drag began, in client px: add it to the pointer's travel. */
  shift: () => { x: number; y: number };
  /** The drag ended: no more scrolling. */
  stop: () => void;
}

/**
 * Scrolls the views around a drag while the pointer is held near one of their
 * edges, once a frame, so something dragged can be taken past what is on
 * screen: across a timeline wider than its window, or to a lane below it. It
 * runs on frames rather than on moves, since a pointer held still at an edge
 * is the point, and sleeps away from the edges until the pointer moves again.
 * `onScroll` runs after each frame that scrolled, for the drag to place what
 * it moves under the pointer again, `shift()` added.
 */
export function createEdgeScroll(
  views: Partial<Record<Axis, EdgeScrollView | null>>,
  onScroll: () => void
): EdgeScroll {
  const axes = (["x", "y"] as const).flatMap((axis) => {
    const view = views[axis];
    return view
      ? [
          {
            axis,
            from: view.element[AXES[axis][0]],
            scale: screenScale(view.element),
            view,
          },
        ]
      : [];
  });
  let pointer: Record<Axis, number> | null = null;

  const task = createFrameTask(() => {
    if (!pointer) {
      return false;
    }
    let scrolled = false;
    for (const { axis, scale, view } of axes) {
      const [scroll, low, high, size] = AXES[axis];
      const { element } = view;
      const box = element.getBoundingClientRect();
      // Only the part of the view on screen counts: a view taller than the window has its edge off screen.
      const start = Math.max(box[low], 0) + (view.covered ?? 0);
      const end = Math.max(start, Math.min(box[high], window[size]));
      const before = element[scroll];
      element[scroll] += edgeScrollStep(pointer[axis], start, end) / scale;
      scrolled ||= element[scroll] !== before;
    }
    if (scrolled) {
      onScroll();
    }
    // Away from the edges, or at the end of what there is to show, it sleeps until the pointer moves.
    return scrolled;
  });

  return {
    follow: (x, y) => {
      pointer = { x, y };
      task.wake();
    },
    shift: () => {
      const travel = { x: 0, y: 0 };
      for (const { axis, from, scale, view } of axes) {
        travel[axis] = (view.element[AXES[axis][0]] - from) * scale;
      }
      return travel;
    },
    stop: () => {
      pointer = null;
      task.stop();
    },
  };
}

/** Set on every lane: the width of one unit of time, so parts place themselves with `calc()`. */
export const UNIT_PROPERTY = "--timeline-unit";
/** Set on every placed part: where it sits, in units. */
export const OFFSET_PROPERTY = "--timeline-offset";
/** Set on every part that spans a stretch of the lane: how long it is, in units. */
export const LENGTH_PROPERTY = "--timeline-length";

/** The width of one unit: px when zoomed, a share of the lane when fitted. */
export const unitLength = (zoom: number | null, duration: number) =>
  zoom === null ? `calc(100% / ${duration > 0 ? duration : 1})` : `${zoom}px`;

/** Sets a lane's unit and width from the zoom, on the element itself. */
export function paintScale(
  el: HTMLElement,
  zoom: number | null,
  duration: number
) {
  el.style.setProperty(UNIT_PROPERTY, unitLength(zoom, duration));
  el.style.minWidth = zoom === null ? "" : `${duration * zoom}px`;
}

/** Places a part at its `--timeline-offset` along the lane. */
export const placedAt = (value: number) => ({
  [OFFSET_PROPERTY]: String(value),
  left: `calc(var(${UNIT_PROPERTY}) * var(${OFFSET_PROPERTY}))`,
  position: "absolute",
});

/** Places a part from `start` along the lane, `length` units long. */
export const placedOver = (start: number, length: number) => ({
  ...placedAt(start),
  [LENGTH_PROPERTY]: String(length),
  width: `calc(var(${UNIT_PROPERTY}) * var(${LENGTH_PROPERTY}))`,
});

/** The lane an element sits in. */
export const laneOf = (el: Element | null) =>
  el?.closest<HTMLElement>("[data-timeline-lane]") ?? null;

/**
 * The nearest of `points` strictly after `from` (`direction` 1) or strictly
 * before it (`direction` -1), or null when there is none that way: what
 * jumping to the next or the previous locator, or cue, needs.
 */
export function adjacentPoint(
  points: readonly number[],
  from: number,
  direction: 1 | -1
): number | null {
  let found: number | null = null;
  for (const point of points) {
    if (
      (direction === 1 ? point > from : point < from) &&
      (found === null || (direction === 1 ? point < found : point > found))
    ) {
      found = point;
    }
  }
  return found;
}

import { createChangeEventDetails, createPointerLock } from "../primitive";
import type { TimelineZoomChangeEventDetails } from "./position";
import type { ZoomAnchor } from "./scale";

/** How the viewport is scrolled and zoomed, as last laid out. */
export interface NavigatorMetrics {
  /** Where value 0 sits in the scrolled content, in px: past a column of headers, for instance. */
  origin: number;
  scrollStart: number;
  /** Visible width, in px. */
  width: number;
  /** px per unit as drawn: the zoom, or what fitting the width gives. */
  zoom: number;
}

/** The part of the navigator a gesture moves: one of its edges, or the window between them. */
export type NavigatorPart = "end" | "start" | "window";

/** The stretch of the timeline the viewport shows, in units. */
export function visibleRange(
  metrics: NavigatorMetrics,
  duration: number
): readonly [start: number, end: number] {
  if (!(metrics.zoom > 0 && metrics.width > 0)) {
    return [0, duration];
  }
  const start = Math.min(
    duration,
    Math.max(0, metrics.scrollStart / metrics.zoom)
  );
  const span = Math.max(0, metrics.width - metrics.origin) / metrics.zoom;
  return [start, Math.min(duration, start + span)];
}

/** Where `part` lands when moved by `delta` units from `from`, within the timeline. */
export function movedRange(
  part: NavigatorPart,
  from: readonly [number, number],
  delta: number,
  duration: number
): [number, number] {
  const [start, end] = from;
  const minSpan = duration / 1000;
  if (part === "window") {
    const span = end - start;
    const next = Math.min(Math.max(0, start + delta), duration - span);
    return [next, next + span];
  }
  if (part === "start") {
    return [Math.min(Math.max(0, start + delta), end - minSpan), end];
  }
  return [start, Math.min(Math.max(start + minSpan, end + delta), duration)];
}

/**
 * How wide the window is drawn, in px, for a stretch `width` px of a bar `bar`
 * px wide. It meets the bar's whole width at the top and `least` at the bottom,
 * and every width has its own, so a window dragged to a width shows just one
 * stretch: a tiny stretch keeps the window big enough to hold, with no step.
 */
function drawnWidth(width: number, bar: number, least: number): number {
  if (least <= 0) {
    return width;
  }
  const floor = Math.min(least, bar / 2);
  return Math.sqrt(width ** 2 + floor ** 2 * (1 - (width / bar) ** 2));
}

/**
 * The window as it is drawn on a bar `bar` px wide, its two edges in px, for
 * the stretch `range`: never narrower than `least`, and inside the bar, at the
 * end of the timeline too. With no `least`, it is the stretch itself.
 */
export function thumbOf(
  range: readonly [number, number],
  duration: number,
  bar: number,
  least: number
): [number, number] {
  const perUnit = bar / duration;
  const width = (range[1] - range[0]) * perUnit;
  const drawn = drawnWidth(width, bar, least);
  const room = bar - width;
  const from = room > 0 ? (range[0] * perUnit * (bar - drawn)) / room : 0;
  return [from, from + drawn];
}

/** The stretch a window drawn from `thumb[0]` to `thumb[1]` px shows: `thumbOf` read back. */
export function rangeOfThumb(
  thumb: readonly [number, number],
  duration: number,
  bar: number,
  least: number
): [number, number] {
  const drawn = thumb[1] - thumb[0];
  const floor = Math.min(least, bar / 2);
  const width =
    least > 0
      ? Math.sqrt(
          Math.max(0, (drawn ** 2 - floor ** 2) / (1 - (floor / bar) ** 2))
        )
      : drawn;
  const room = bar - drawn;
  const from = room > 0 ? (thumb[0] * (bar - width)) / room : 0;
  const perUnit = bar / duration;
  return [from / perUnit, (from + width) / perUnit];
}

/** Where a drag of `part` by `delta` px leaves the window: an edge stops at `least` wide, the other held still. */
function movedThumb(
  part: NavigatorPart,
  [from, to]: readonly [number, number],
  delta: number,
  bar: number,
  least: number
): [number, number] {
  if (part === "window") {
    const next = Math.min(Math.max(0, from + delta), bar - (to - from));
    return [next, next + (to - from)];
  }
  if (part === "start") {
    return [Math.max(0, Math.min(from + delta, to - least)), to];
  }
  return [from, Math.min(Math.max(from + least, to + delta), bar)];
}

/** A keypress moves the window or an edge by this share of the timeline. */
const NUDGE_SHARE = 0.02;

/** The options of `createNavigatorController`: the timeline's length, how the viewport is laid out, the functions that scroll and zoom it, and the narrowest the window may be. */
export interface NavigatorOptions {
  disabled?: boolean;
  duration: number;
  /** The closest the viewport zooms, in px per unit: a drag of an edge stops there, the window with it, rather than sliding on. */
  maxZoom?: number;
  /** The viewport's metrics as last laid out. */
  metrics: () => NavigatorMetrics;
  /** The least width the window is drawn at, in px: a drag follows the window as drawn. @default 0 */
  minWindowWidth?: number;
  /** Scrolls the viewport to `left` px. */
  scrollTo: (left: number) => void;
  /** Clamps and proposes a zoom held still around `anchor`; returns whether it was applied. */
  zoomTo: (
    next: number,
    details: TimelineZoomChangeEventDetails,
    anchor: ZoomAnchor
  ) => boolean;
}

/** What `createNavigatorController` returns: the stretch the window shows, and the presses, keys, typed values and double click that move it. */
export interface NavigatorController {
  /** Double click shows everything. */
  doubleClick: (event: MouseEvent) => void;
  /** Moves a part of the window, its edge or the window itself, by a share of the keyboard step: a key or the wheel. */
  keyDown: (part: NavigatorPart, event: KeyboardEvent) => boolean;
  /** Starts a drag of `part` from `handle`; `track` is the navigator's bar, which turns px into units. */
  press: (
    part: NavigatorPart,
    event: PointerEvent,
    handle: Element,
    track: Element | null
  ) => void;
  /** The stretch shown now. */
  range: () => readonly [number, number];
  setOptions: (options: NavigatorOptions) => void;
  /** Moves a part to a value from an input: the start or end, or the window's start. */
  typeAt: (part: NavigatorPart, value: number, event: Event) => void;
}

/**
 * The navigator's behavior: a bar with the stretch the viewport shows inside
 * it, which a drag or a key moves. A move of the window scrolls, a move of an
 * edge zooms and holds the other edge still.
 */
export function createNavigatorController(
  initial: NavigatorOptions
): NavigatorController {
  let options = initial;
  const pointers = createPointerLock();

  /** Scrolls or zooms the viewport so it shows `next`. */
  const showRange = (
    part: NavigatorPart,
    next: readonly [number, number],
    details: TimelineZoomChangeEventDetails
  ) => {
    const metrics = options.metrics();
    const laneWidth = Math.max(1, metrics.width - metrics.origin);
    const [start, end] = next;
    if (part === "window" || !(end > start)) {
      if (metrics.zoom > 0) {
        options.scrollTo(start * metrics.zoom);
      }
      return;
    }
    // Resizing the window is zooming: its start is held at the lane's start.
    const zoomed = options.zoomTo(laneWidth / (end - start), details, {
      offset: metrics.origin,
      value: start,
    });
    if (!zoomed && metrics.zoom > 0) {
      options.scrollTo(start * metrics.zoom);
    }
  };

  const range = () => visibleRange(options.metrics(), options.duration);

  const press: NavigatorController["press"] = (part, event, handle, track) => {
    if (options.disabled || event.button !== 0 || !pointers.claim(event)) {
      return;
    }
    handle.setPointerCapture?.(event.pointerId);
    const from = range();
    const startX = event.clientX;
    pointers.follow(
      handle,
      event,
      (move) => {
        // The window follows the pointer on the bar, and what the view shows follows the window.
        const { duration, maxZoom, minWindowWidth = 0 } = options;
        const bar = Math.max(track?.getBoundingClientRect().width ?? 0, 1);
        const metrics = options.metrics();
        const lane = Math.max(1, metrics.width - metrics.origin);
        const leastSpan = Math.max(
          duration / 1000,
          maxZoom ? lane / maxZoom : 0
        );
        const next = movedThumb(
          part,
          thumbOf(from, duration, bar, minWindowWidth),
          move.clientX - startX,
          bar,
          drawnWidth((leastSpan / duration) * bar, bar, minWindowWidth)
        );
        showRange(
          part,
          rangeOfThumb(next, duration, bar, minWindowWidth),
          createChangeEventDetails("drag", move)
        );
      },
      () => undefined
    );
  };

  const keyDown: NavigatorController["keyDown"] = (part, event) => {
    if (options.disabled) {
      return false;
    }
    const nudge = options.duration * NUDGE_SHARE;
    const deltas: Record<string, number> = {
      ArrowDown: -nudge,
      ArrowLeft: -nudge,
      ArrowRight: nudge,
      ArrowUp: nudge,
      End: options.duration,
      Home: -options.duration,
      PageDown: -nudge * 5,
      PageUp: nudge * 5,
    };
    const delta = deltas[event.key];
    if (delta === undefined) {
      return false;
    }
    showRange(
      part,
      movedRange(part, range(), delta, options.duration),
      createChangeEventDetails(
        "keyboard",
        event
      ) as TimelineZoomChangeEventDetails
    );
    return true;
  };

  const typeAt: NavigatorController["typeAt"] = (part, value, event) => {
    if (options.disabled) {
      return;
    }
    const current = range();
    const from = part === "end" ? current[1] : current[0];
    showRange(
      part,
      movedRange(part, current, value - from, options.duration),
      createChangeEventDetails(
        "input-change",
        event
      ) as TimelineZoomChangeEventDetails
    );
  };

  return {
    doubleClick: (event) => {
      if (options.disabled) {
        return;
      }
      showRange(
        "end",
        [0, options.duration],
        createChangeEventDetails(
          "double-click",
          event
        ) as TimelineZoomChangeEventDetails
      );
    },
    keyDown,
    press,
    range,
    setOptions: (next) => {
      options = next;
    },
    typeAt,
  };
}

import {
  createNavigatorController,
  type NavigatorController,
  type NavigatorPart,
  thumbOf,
  visibleRange,
} from "./navigator-controller";
import { css, type SlotDefinition } from "@ui-sdk/core";
import { flag, VISUALLY_HIDDEN } from "../primitive";
import type {
  DescribePosition,
  TimelineApi,
  TimelinePublicState,
  TimelineState,
} from "./timeline";

/**
 * The navigator: a bar with the stretch the viewport shows inside it, which a
 * drag or a key moves. A move of the window scrolls, a move of an edge zooms
 * and holds the other edge still. Its parts follow the viewport straight in
 * the DOM, so a scroll never renders.
 */

/** The props of the navigator part. */
export interface NavigatorProps {
  id?: string;
  /** The least width the window is drawn at, in px. @default 0 */
  minWindowWidth?: number;
}

interface PartProps {
  id?: string;
}

export interface NavigatorEdgeState extends TimelinePublicState {
  edge: "end" | "start";
}

type Slot<Props, Public = TimelinePublicState> = SlotDefinition<
  TimelineState,
  TimelineApi,
  Props,
  Public
>;

type InputSlot = Slot<
  PartProps & { getAriaValueText?: DescribePosition },
  object
>;

/** The navigator slots, by name. */
export type NavigatorSlots = {
  navigator: Slot<NavigatorProps>;
  navigatorEnd: Slot<PartProps, NavigatorEdgeState>;
  navigatorEndInput: InputSlot;
  navigatorStart: Slot<PartProps, NavigatorEdgeState>;
  navigatorStartInput: InputSlot;
  navigatorWindow: Slot<PartProps>;
  navigatorWindowInput: InputSlot;
};

/** What the navigator's `api` gives its parts. */
export interface NavigatorApi {
  /** The bar, and what it was given, once the navigator part binds. */
  navigator: {
    el: HTMLElement | null;
    minWindowWidth: number;
    /** The bar's width, measured when it binds and when it is resized: reading it from the DOM at each paint would lay the page out each time. */
    width: number;
  };
  /** A controller over the viewport as it is now. */
  navigatorFor: (state: TimelineState) => NavigatorController;
}

const describeNumber = (value: number) => String(Math.round(value * 100) / 100);

export function createNavigatorApi(
  api: () => TimelineApi,
  /** How close the timeline zooms, in px per unit: where the window stops narrowing. */
  maxZoom: () => number
): NavigatorApi {
  const navigator = {
    el: null as HTMLElement | null,
    minWindowWidth: 0,
    width: 0,
  };
  return {
    navigator,
    navigatorFor: (state) =>
      createNavigatorController({
        disabled: state.view.disabled,
        duration: state.duration,
        maxZoom: maxZoom(),
        metrics: () => api().viewport.get(),
        minWindowWidth: navigator.minWindowWidth,
        scrollTo: (left) => api().scrollerTo.current?.(left),
        zoomTo: (next, details, anchor) => api().zoomTo(next, details, anchor),
      }),
  };
}

/** Where the window sits in the bar, as shares of it, and the stretch it shows. */
function layoutOf(api: TimelineApi, state: TimelineState) {
  const { duration } = state;
  const range = visibleRange(api.viewport.get(), duration);
  const bar = api.navigator.width;
  const { minWindowWidth } = api.navigator;
  const drawn =
    minWindowWidth > 0 && bar > 0 && duration > 0
      ? thumbOf(range, duration, bar, minWindowWidth)
      : null;
  const span = drawn ? bar : Math.max(duration, Number.MIN_VALUE);
  const [from, to] = drawn ?? range;
  return {
    duration,
    range,
    thumb: { end: to / span, start: from / span, width: (to - from) / span },
  };
}

const percent = (share: number) => `${share * 100}%`;

const publicOf = (state: TimelineState): TimelinePublicState => ({
  disabled: state.view.disabled,
  fitted: state.view.fitted,
  scrubbing: state.view.scrubbing,
});

const attrsOf = (state: TimelineState) => ({
  "data-disabled": flag(state.view.disabled),
  "data-fitted": flag(state.view.fitted),
  "data-scrubbing": flag(state.view.scrubbing),
});

/** Runs `write` now and on each change of the viewport, outside any render. */
function follow(
  part: { api: TimelineApi; store: { get: () => TimelineState } },
  write: (layout: ReturnType<typeof layoutOf>) => void
) {
  const run = () => write(layoutOf(part.api, part.store.get()));
  run();
  return part.api.viewport.subscribe(run);
}

export function navigatorSlots(slot: any) {
  const press =
    (kind: NavigatorPart) =>
    (
      event: PointerEvent,
      {
        api,
        el,
        store,
      }: {
        api: TimelineApi;
        el: HTMLElement | undefined;
        store: { get: () => TimelineState };
      }
    ) => {
      if (event.button !== 0) {
        return;
      }
      event.stopPropagation();
      const state = store.get();
      if (!el || state.view.disabled) {
        return;
      }
      event.preventDefault();
      api.navigatorFor(state).press(kind, event, el, api.navigator.el);
    };

  const edge = (kind: "end" | "start") =>
    slot({
      attrs: (state: TimelineState, { api }: { api: TimelineApi }) => {
        const { thumb } = layoutOf(api, state);
        return {
          ...attrsOf(state),
          "data-edge": kind,
          style: css({
            left: percent(kind === "start" ? thumb.start : thumb.end),
            position: "absolute",
            "touch-action": "none",
          }),
        };
      },
      bind: (el: HTMLElement, part: any) =>
        follow(part, ({ thumb }) => {
          el.style.left = percent(kind === "start" ? thumb.start : thumb.end);
        }),
      on: { pointerdown: press(kind) },
      state: (state: TimelineState) => ({ ...publicOf(state), edge: kind }),
    });

  const edgeInput = (kind: "end" | "start") =>
    slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: any }
      ) => {
        const { duration, range } = layoutOf(api, state);
        const current = kind === "start" ? range[0] : range[1];
        return {
          "aria-valuetext": (props.getAriaValueText ?? describeNumber)(
            current,
            duration
          ),
          disabled: flag(state.view.disabled),
          max: String(kind === "start" ? range[1] : duration),
          min: String(kind === "start" ? 0 : range[0]),
          step: "any",
          style: css(VISUALLY_HIDDEN),
          type: "range",
          value: String(current),
        };
      },
      bind: (el: HTMLElement, part: any) =>
        follow(part, ({ duration, range }) => {
          const input = el as HTMLInputElement;
          const current = kind === "start" ? range[0] : range[1];
          input.max = String(kind === "start" ? range[1] : duration);
          input.min = String(kind === "start" ? 0 : range[0]);
          input.value = String(current);
          input.setAttribute(
            "aria-valuetext",
            (part.props.getAriaValueText ?? describeNumber)(current, duration)
          );
        }),
      on: {
        change: (
          event: Event,
          {
            api,
            el,
            store,
          }: {
            api: TimelineApi;
            el: HTMLElement | undefined;
            store: { get: () => TimelineState };
          }
        ) =>
          api
            .navigatorFor(store.get())
            .typeAt(kind, Number((el as HTMLInputElement).value), event),
        keydown: (
          event: KeyboardEvent,
          {
            api,
            store,
          }: { api: TimelineApi; store: { get: () => TimelineState } }
        ) => {
          if (api.navigatorFor(store.get()).keyDown(kind, event)) {
            event.preventDefault();
          }
        },
      },
      props: { getAriaValueText: "value" },
    });

  return {
    navigator: slot({
      attrs: (state: TimelineState) => ({
        ...attrsOf(state),
        style: css({ position: "relative", "touch-action": "none" }),
      }),
      bind: (el: HTMLElement, part: any) => {
        const { navigator } = part.api;
        navigator.el = el;
        navigator.minWindowWidth = part.props.minWindowWidth ?? 0;
        navigator.width = el.getBoundingClientRect().width;
        // The parts read the width again when the bar is resized.
        const observer = new ResizeObserver(() => {
          const { width } = el.getBoundingClientRect();
          if (width !== navigator.width) {
            navigator.width = width;
            part.store.set({ parts: part.store.get().parts + 1 });
          }
        });
        observer.observe(el);
        return () => {
          observer.disconnect();
          navigator.el = null;
        };
      },
      on: {
        dblclick: (
          event: MouseEvent,
          {
            api,
            store,
          }: { api: TimelineApi; store: { get: () => TimelineState } }
        ) => api.navigatorFor(store.get()).doubleClick(event),
      },
      props: { minWindowWidth: "number" },
      state: (state: TimelineState) => publicOf(state),
    }),
    navigatorEnd: edge("end"),
    navigatorEndInput: edgeInput("end"),
    navigatorStart: edge("start"),
    navigatorStartInput: edgeInput("start"),
    navigatorWindow: slot({
      attrs: (state: TimelineState, { api }: { api: TimelineApi }) => {
        const { thumb } = layoutOf(api, state);
        return {
          ...attrsOf(state),
          style: css({
            left: percent(thumb.start),
            position: "absolute",
            width: percent(thumb.width),
          }),
        };
      },
      bind: (el: HTMLElement, part: any) =>
        follow(part, ({ thumb }) => {
          el.style.left = percent(thumb.start);
          el.style.width = percent(thumb.width);
        }),
      on: { pointerdown: press("window") },
      state: (state: TimelineState) => publicOf(state),
    }),
    navigatorWindowInput: slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: any }
      ) => {
        const { duration, range } = layoutOf(api, state);
        const describe = props.getAriaValueText ?? describeNumber;
        return {
          "aria-valuetext": `${describe(range[0], duration)} to ${describe(range[1], duration)}`,
          disabled: flag(state.view.disabled),
          max: String(Math.max(0, duration - (range[1] - range[0]))),
          min: "0",
          step: "any",
          style: css(VISUALLY_HIDDEN),
          type: "range",
          value: String(range[0]),
        };
      },
      bind: (el: HTMLElement, part: any) =>
        follow(part, ({ duration, range }) => {
          const input = el as HTMLInputElement;
          const describe = part.props.getAriaValueText ?? describeNumber;
          input.max = String(Math.max(0, duration - (range[1] - range[0])));
          input.value = String(range[0]);
          input.setAttribute(
            "aria-valuetext",
            `${describe(range[0], duration)} to ${describe(range[1], duration)}`
          );
        }),
      on: {
        change: (
          event: Event,
          {
            api,
            el,
            store,
          }: {
            api: TimelineApi;
            el: HTMLElement | undefined;
            store: { get: () => TimelineState };
          }
        ) =>
          api
            .navigatorFor(store.get())
            .typeAt("window", Number((el as HTMLInputElement).value), event),
        keydown: (
          event: KeyboardEvent,
          {
            api,
            store,
          }: { api: TimelineApi; store: { get: () => TimelineState } }
        ) => {
          if (api.navigatorFor(store.get()).keyDown("window", event)) {
            event.preventDefault();
          }
        },
      },
      props: { getAriaValueText: "value" },
    }),
  } as NavigatorSlots;
}

import { clampFinite } from "../grid";
import {
  type ChangeEventDetails,
  type CommitEventDetails,
  createChangeEventDetails,
  createPointerLock,
} from "../primitive";
import type { Source } from "../primitive";
import { clampZoom } from "./scale";
import {
  bypassesGrid,
  type Grid,
  SNAP_RADIUS_PX,
  snapToGrid,
  withSnapRadius,
} from "../grid";

/** What `onPositionChange` receives with each move of the playhead: the reason (`"press"`, `"drag"`, `"keyboard"` or `"input-change"`), the event, and `cancel()` to refuse the move. */
export type TimelinePositionChangeEventDetails =
  | ChangeEventDetails<"press" | "drag", PointerEvent>
  | ChangeEventDetails<"keyboard", KeyboardEvent>
  | ChangeEventDetails<"input-change", Event>;
/** What `onPositionCommitted` receives once a move of the playhead ends: the reason and the event behind it. */
export type TimelinePositionCommitEventDetails =
  | CommitEventDetails<"press" | "drag", PointerEvent>
  | CommitEventDetails<"keyboard", KeyboardEvent>
  | CommitEventDetails<"input-change", Event>;

/** What `onZoomChange` receives with each zoom: the reason (`"wheel"`, `"drag"`, `"keyboard"`, `"input-change"` or `"double-click"`), the event, and `cancel()` to refuse it. */
export type TimelineZoomChangeEventDetails =
  | ChangeEventDetails<"wheel", WheelEvent>
  | ChangeEventDetails<"drag", PointerEvent>
  | ChangeEventDetails<"keyboard", KeyboardEvent>
  | ChangeEventDetails<"input-change", Event>
  | ChangeEventDetails<"double-click", MouseEvent>;

/** The options of `createTimelineController`: the position and the zoom, each held, controlled or (the position) live, the timeline's length, grid and steps, the zoom's bounds, and the callbacks. */
export interface TimelineOptions {
  /** Uncontrolled starting position. @default 0 */
  defaultPosition?: number;
  /** Uncontrolled starting zoom, in px per unit. `null` fits the width. */
  defaultZoom?: number | null;
  disabled?: boolean;
  duration: number;
  grid: Grid;
  largeStep: number;
  maxZoom: number;
  minZoom: number;
  onPositionChange?: (
    value: number,
    details: TimelinePositionChangeEventDetails
  ) => void;
  onPositionCommitted?: (
    value: number,
    details: TimelinePositionCommitEventDetails
  ) => void;
  onZoomChange?: (
    zoom: number,
    details: TimelineZoomChangeEventDetails
  ) => void;
  /** The controlled position. */
  position?: number;
  /** A live position, followed without a render: it takes precedence over `position`. */
  source?: Source<number>;
  step: number;
  /** The controlled zoom, in px per unit; `null` fits the width. */
  zoom?: number | null;
}

/** What a view draws the timeline from. */
export interface TimelineSnapshot {
  disabled: boolean;
  duration: number;
  /** Whether no zoom is set, so the timeline fits the width it is given. */
  fitted: boolean;
  /** The position as displayed: the scrubbed one while a pointer moves it. */
  position: number;
  /** Whether a pointer is moving the position. */
  scrubbing: boolean;
  /** px per unit, or null while fitted. */
  zoom: number | null;
}

/** A stretch selected by dragging on the ruler with Shift held. */
export type TimelineSelectionChangeEventDetails = ChangeEventDetails<
  "drag",
  PointerEvent
>;
export type TimelineSelectionCommitEventDetails = CommitEventDetails<
  "drag",
  PointerEvent
>;

/** Listens to the stretch a Shift + drag on the ruler selects: set by the ruler. */
export interface TimelineSelectionHandlers {
  onSelectionChange?: (
    range: readonly [number, number],
    details: TimelineSelectionChangeEventDetails
  ) => void;
  onSelectionCommitted?: (
    range: readonly [number, number],
    details: TimelineSelectionCommitEventDetails
  ) => void;
}

/** What `createTimelineController` returns: the snapshot to draw from, and the presses, keys, typed values and zooms that move the playhead or the view. */
export interface TimelineController {
  /** Reports the end of a gesture that moved the position. */
  commitSeek: (
    value: number,
    details: TimelinePositionCommitEventDetails
  ) => void;
  getSnapshot: () => TimelineSnapshot;
  /** Handles a key on the ruler: arrows, Page keys, Home and End. Returns `true` when the timeline takes the key. */
  keyDown: (event: KeyboardEvent) => boolean;
  /**
   * Starts a press on the ruler: a press seeks, a drag scrubs, Shift scrubs
   * four times finer; with a selection listener, a drag with Shift held selects
   * a stretch instead. `handle` takes the pointer, `lane` is what it is measured along.
   */
  pressRuler: (event: PointerEvent, handle: Element, lane: Element) => void;
  /**
   * Starts a press that seeks: `lane` is what the position is measured along,
   * `handle` takes the pointer. A drag scrubs, on the grid unless Cmd/Ctrl is
   * held. With `selecting` listeners, a drag selects the stretch from the press
   * to the pointer instead, and the position stays where the press put it.
   */
  pressSeek: (
    event: PointerEvent,
    handle: Element,
    lane: Element,
    selecting?: TimelineSelectionHandlers
  ) => void;
  /** Clamps and proposes a position; returns whether it was applied. */
  seek: (next: number, details: TimelinePositionChangeEventDetails) => boolean;
  setOptions: (options: TimelineOptions) => void;
  setScrubbing: (scrubbing: boolean) => void;
  /** Takes the selection listeners of the ruler; call it whenever they may have changed. */
  setSelection: (handlers: TimelineSelectionHandlers) => void;
  subscribe: (listener: () => void) => () => void;
  /** Sets the position from an input, reporting an `"input-change"` change and commit. */
  typeAt: (value: number, event: Event) => void;
  /** The position of a point at `clientX` on `lane`, in units, clamped to the timeline. */
  valueAt: (lane: Element, clientX: number) => number;
  /** Clamps and proposes a zoom; returns whether it was applied. */
  zoomTo: (next: number, details: TimelineZoomChangeEventDetails) => boolean;
}

/** Holding Shift scrubs this much slower than the pointer moves. */
const FINE_SCRUB = 0.25;

/** The timeline's units under a point of `lane`, clamped to the timeline. */
export function valueAtLane(
  lane: Element,
  clientX: number,
  zoom: number | null,
  duration: number
): number {
  const rect = lane.getBoundingClientRect();
  const unit = zoom ?? rect.width / Math.max(duration, Number.MIN_VALUE);
  const value = (clientX - rect.left) / Math.max(unit, Number.MIN_VALUE);
  return Math.min(duration, Math.max(0, value));
}

/**
 * The timeline's playback position and zoom, with no view attached: held,
 * controlled or live, moved by a press, a drag, a key or an input, and zoomed.
 */
export function createTimelineController(
  initial: TimelineOptions
): TimelineController {
  let options = initial;
  const pointers = createPointerLock();

  // Held by the timeline, unless `position` or a live `source` is given.
  let uncontrolledPosition = options.defaultPosition ?? 0;
  // The position as the gesture under way left it: a controlled position that
  // lags behind must not pull the timeline back mid-scrub.
  let latest: number | null = null;
  let scrubbing = false;
  let uncontrolledZoom: number | null = options.defaultZoom ?? null;
  const listeners = new Set<() => void>();
  const notify = () => {
    for (const listener of listeners) {
      listener();
    }
  };

  const clampToDuration = (value: number) =>
    clampFinite(value, 0, options.duration);
  const held = (): number =>
    clampToDuration(
      options.source
        ? options.source.getSnapshot()
        : (options.position ?? uncontrolledPosition)
    );
  const current = (): number => latest ?? held();
  const heldZoom = (): number | null =>
    options.zoom === undefined ? uncontrolledZoom : options.zoom;

  let snapshot: TimelineSnapshot | null = null;
  const getSnapshot = (): TimelineSnapshot => {
    const position = scrubbing && latest !== null ? latest : held();
    const zoom = heldZoom();
    const disabled = options.disabled ?? false;
    const { duration } = options;
    if (
      snapshot &&
      snapshot.position === position &&
      snapshot.zoom === zoom &&
      snapshot.scrubbing === scrubbing &&
      snapshot.disabled === disabled &&
      snapshot.duration === duration
    ) {
      return snapshot;
    }
    snapshot = {
      disabled,
      duration,
      fitted: zoom === null,
      position,
      scrubbing,
      zoom,
    };
    return snapshot;
  };

  const seek: TimelineController["seek"] = (raw, details) => {
    const next = clampToDuration(raw);
    if (next === current()) {
      return false;
    }
    options.onPositionChange?.(next, details);
    if (details.isCanceled) {
      return false;
    }
    latest = next;
    if (options.position === undefined && !options.source) {
      uncontrolledPosition = next;
    }
    notify();
    return true;
  };

  const commitSeek: TimelineController["commitSeek"] = (value, details) => {
    options.onPositionCommitted?.(value, details);
  };

  const zoomTo: TimelineController["zoomTo"] = (next, details) => {
    const clamped = clampZoom(next, options.minZoom, options.maxZoom);
    if (clamped === null || clamped === heldZoom()) {
      return false;
    }
    options.onZoomChange?.(clamped, details);
    if (details.isCanceled) {
      return false;
    }
    if (options.zoom === undefined) {
      uncontrolledZoom = clamped;
    }
    notify();
    return true;
  };

  const setScrubbing: TimelineController["setScrubbing"] = (next) => {
    scrubbing = next;
    if (!next) {
      // The drag is over: the known position rules again.
      latest = null;
    }
    notify();
  };

  /** The grid a press lands on: its points pull from a few px away at the zoom held now. */
  const pressGrid = () => {
    const zoom = heldZoom();
    return zoom !== null && zoom > 0
      ? withSnapRadius(options.grid, SNAP_RADIUS_PX / zoom)
      : options.grid;
  };

  const pressSeek: TimelineController["pressSeek"] = (
    event,
    handle,
    lane,
    selecting
  ) => {
    if (options.disabled || event.button !== 0 || !pointers.claim(event)) {
      return;
    }
    handle.setPointerCapture?.(event.pointerId);
    // The grid applies unless Cmd/Ctrl is held: read from the pointer's own keys.
    const landingAt = (pointer: PointerEvent) => {
      const raw = valueAtLane(
        lane,
        pointer.clientX,
        heldZoom(),
        options.duration
      );
      return bypassesGrid(pointer) ? raw : snapToGrid(raw, pressGrid());
    };
    const anchor = landingAt(event);
    const gesture: {
      changed: boolean;
      moved: boolean;
      range: readonly [number, number] | null;
    } = {
      changed: false,
      moved: false,
      range: null,
    };
    setScrubbing(true);
    gesture.changed = seek(anchor, createChangeEventDetails("press", event));
    /** A drag that selects: the stretch from the press to the pointer, once it has length. */
    const select = (move: PointerEvent) => {
      const at = landingAt(move);
      if (at === anchor && gesture.range === null) {
        return;
      }
      const range = [Math.min(anchor, at), Math.max(anchor, at)] as const;
      const details = createChangeEventDetails("drag", move);
      selecting?.onSelectionChange?.(range, details);
      if (!details.isCanceled) {
        gesture.range = range;
      }
    };
    pointers.follow(
      handle,
      event,
      (move) => {
        if (selecting?.onSelectionChange) {
          select(move);
          return;
        }
        gesture.moved = true;
        if (seek(landingAt(move), createChangeEventDetails("drag", move))) {
          gesture.changed = true;
        }
      },
      (end) => {
        // Read before settling: the position falls back to the known value after.
        const committed = current();
        setScrubbing(false);
        if (gesture.changed) {
          commitSeek(committed, {
            event: end,
            reason: gesture.moved ? "drag" : "press",
          } as TimelinePositionCommitEventDetails);
        }
        if (gesture.range) {
          selecting?.onSelectionCommitted?.(gesture.range, {
            event: end,
            reason: "drag",
          });
        }
      }
    );
  };

  const keyDown: TimelineController["keyDown"] = (event) => {
    if (options.disabled) {
      return false;
    }
    const now = current();
    const arrowStep = event.shiftKey ? options.largeStep : options.step;
    const targets: Record<string, number> = {
      ArrowDown: now - arrowStep,
      ArrowLeft: now - arrowStep,
      ArrowRight: now + arrowStep,
      ArrowUp: now + arrowStep,
      End: options.duration,
      Home: 0,
      PageDown: now - options.largeStep,
      PageUp: now + options.largeStep,
    };
    const target = targets[event.key];
    if (target === undefined) {
      return false;
    }
    if (seek(target, createChangeEventDetails("keyboard", event))) {
      commitSeek(current(), {
        event,
        reason: "keyboard",
      } as TimelinePositionCommitEventDetails);
    }
    return true;
  };

  let selection: TimelineSelectionHandlers = {};

  const pressRuler: TimelineController["pressRuler"] = (
    event,
    handle,
    lane
  ) => {
    if (options.disabled || event.button !== 0 || !pointers.claim(event)) {
      return;
    }
    handle.setPointerCapture?.(event.pointerId);
    const landing = (pointer: PointerEvent) => {
      const raw = valueAtLane(
        lane,
        pointer.clientX,
        heldZoom(),
        options.duration
      );
      return bypassesGrid(pointer) ? raw : snapToGrid(raw, pressGrid());
    };
    if (event.shiftKey && selection.onSelectionChange) {
      // Shift selects a stretch, as on a DAW's ruler; a plain press seeks.
      const anchor = landing(event);
      const selecting: { range: readonly [number, number] | null } = {
        range: null,
      };
      setScrubbing(true);
      pointers.follow(
        handle,
        event,
        (move) => {
          const at = landing(move);
          const range = [Math.min(anchor, at), Math.max(anchor, at)] as const;
          const details = createChangeEventDetails("drag", move);
          selection.onSelectionChange?.(range, details);
          if (!details.isCanceled) {
            selecting.range = range;
          }
        },
        (end) => {
          setScrubbing(false);
          if (selecting.range) {
            selection.onSelectionCommitted?.(selecting.range, {
              event: end,
              reason: "drag",
            });
          }
        }
      );
      return;
    }
    // Shift scrubs four times finer, measured from where the pointer last moved at full speed.
    const unitOf = () => {
      const rect = handle.getBoundingClientRect();
      return (
        heldZoom() ?? rect.width / Math.max(options.duration, Number.MIN_VALUE)
      );
    };
    let anchor = { clientX: event.clientX, value: landing(event) };
    const gesture: { changed: boolean; moved: boolean } = {
      changed: false,
      moved: false,
    };
    setScrubbing(true);
    gesture.changed = seek(
      anchor.value,
      createChangeEventDetails("press", event)
    );
    pointers.follow(
      handle,
      event,
      (move) => {
        gesture.moved = true;
        let value: number;
        if (move.shiftKey) {
          value =
            anchor.value +
            ((move.clientX - anchor.clientX) / unitOf()) * FINE_SCRUB;
        } else {
          value = landing(move);
          anchor = { clientX: move.clientX, value };
        }
        if (seek(value, createChangeEventDetails("drag", move))) {
          gesture.changed = true;
        }
      },
      (end) => {
        const committed = current();
        setScrubbing(false);
        if (gesture.changed) {
          commitSeek(committed, {
            event: end,
            reason: gesture.moved ? "drag" : "press",
          } as TimelinePositionCommitEventDetails);
        }
      }
    );
  };

  return {
    commitSeek,
    getSnapshot,
    keyDown,
    pressSeek,
    seek,
    pressRuler,
    setSelection: (handlers) => {
      selection = handlers;
    },
    typeAt: (value, event) => {
      if (options.disabled) {
        return;
      }
      if (seek(value, createChangeEventDetails("input-change", event))) {
        commitSeek(current(), {
          event,
          reason: "input-change",
        } as TimelinePositionCommitEventDetails);
      }
    },
    setOptions: (next) => {
      options = next;
      // The props take over again on every render, unless a scrub is under way.
      if (!scrubbing) {
        latest = null;
      }
    },
    setScrubbing,
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    valueAt: (lane, clientX) =>
      valueAtLane(lane, clientX, heldZoom(), options.duration),
    zoomTo,
  };
}

import {
  type ChangeEventDetails,
  type CommitEventDetails,
  createChangeEventDetails,
  createPointerLock,
} from "../primitive";
import { normalizeRange, type RangeEdge, type RangeValue } from "../grid";
import { keyTargets } from "./clip-controller";
import { valueAtLane } from "./position";
import {
  bypassesGrid,
  type Grid,
  SNAP_RADIUS_PX,
  snapRangeMove,
  snapToGrid,
  withoutSnapPoints,
  withSnapRadius,
} from "../grid";

type Edged<Details> = Details & {
  /** What moved: one edge, or the whole range with `"both"`. */
  edge: RangeEdge;
};

/** What `onValueChange` receives with each change to a range: which `edge` moved, or `"both"`, the reason (`"drag"`, `"draw"`, `"keyboard"` or `"input-change"`), the event, and `cancel()` to refuse the change. */
export type RangeChangeEventDetails = Edged<
  | ChangeEventDetails<"drag" | "draw", PointerEvent>
  | ChangeEventDetails<"keyboard", KeyboardEvent>
  | ChangeEventDetails<"input-change", Event>
>;
/** What `onValueCommitted` receives once a gesture on a range ends: which edge moved, the reason and the event behind it. */
export type RangeCommitEventDetails = Edged<
  | CommitEventDetails<"drag" | "draw", PointerEvent>
  | CommitEventDetails<"keyboard", KeyboardEvent>
  | CommitEventDetails<"input-change", Event>
>;

/** The options of `createRangeController`: the range, held or controlled, the timeline's length, grid, steps and zoom, the shortest length, whether it can be moved or drawn, and the callbacks. */
export interface RangeOptions {
  defaultValue?: RangeValue;
  disabled?: boolean;
  /** Whether dragging across empty lane draws a new range. */
  drawable?: boolean;
  duration: number;
  grid: Grid;
  largeStep: number;
  /** The least room it is drawn with, in px, as `drawnRangeWidth` draws it: a drag of its end follows what is drawn. @default 0 */
  minDrawnWidth?: number;
  /** The shortest the range can be, in the timeline's units. */
  minLength: number;
  /** Whether dragging the body, or its keys, moves the range. */
  movable: boolean;
  onValueChange?: (value: RangeValue, details: RangeChangeEventDetails) => void;
  onValueCommitted?: (
    value: RangeValue,
    details: RangeCommitEventDetails
  ) => void;
  step: number;
  /** The controlled range. */
  value?: RangeValue;
  /** The timeline's px per unit, or null while it fits its lane. */
  zoom: number | null;
}

/** What a view draws a range from. */
export interface RangeSnapshot {
  disabled: boolean;
  /** Whether a pointer is moving, resizing or drawing the range. */
  dragging: boolean;
  /** The range as displayed: the dragged one while a pointer moves it. */
  value: RangeValue;
}

/** What `createRangeController` returns: the snapshot to draw from, and the presses, draws, keys and typed values that move and resize the range. */
export interface RangeController {
  /** Keys on a handle's input: arrows and Page keys move the edge, Home and End go to its limits. Returns `true` when the handle takes the key. */
  edgeKeyDown: (edge: "end" | "start", event: KeyboardEvent) => boolean;
  /** How far an edge can go, before it meets the other one. */
  edgeRange: (edge: "end" | "start") => readonly [number, number];
  /** An input moves an edge to a position. */
  edgeTypeAt: (edge: "end" | "start", position: number, event: Event) => void;
  getSnapshot: () => RangeSnapshot;
  /**
   * Keys on the range's own input. Left and Right move it by a step, Up and
   * Down by its own length, Page keys by a large step, Home and End to the
   * ends of the timeline. With Cmd/Ctrl, Left and Right shorten or lengthen
   * it by a step and Up and Down double or halve it, its start in place.
   * Returns `true` when the range takes the key.
   */
  keyDown: (event: KeyboardEvent) => boolean;
  /** An input moves the range to a start, keeping its length. */
  moveTypeAt: (start: number, event: Event) => void;
  /**
   * Starts a drag of `edge` (or the whole range, `"both"`) from `handle`. The
   * drag is measured on the lane the range sits on, `lane`, in px.
   */
  press: (
    edge: RangeEdge,
    event: PointerEvent,
    handle: Element,
    lane: Element | null
  ) => void;
  /**
   * Starts drawing a new range from a press on `lane` itself, where no range is:
   * the drag runs from where the press began to where the pointer is.
   */
  pressDraw: (event: PointerEvent, lane: Element) => void;
  setOptions: (options: RangeOptions) => void;
  subscribe: (listener: () => void) => () => void;
}

/**
 * How wide a range `width` px long is drawn, so that it keeps `least` px of
 * room for its handles: from `2 * least` px up, as long as it is, and under
 * that it still grows with its length, at half the rate.
 */
export function drawnRangeWidth(width: number, least: number): number {
  return Math.max(width, least + width / 2);
}

/** How long a range is, in px, when it is drawn `drawn` px wide. */
export function rangeWidthOfDrawn(drawn: number, least: number): number {
  return drawn >= 2 * least ? drawn : Math.max(0, 2 * (drawn - least));
}

/** One drag, from press to release. */
interface RangeGesture {
  changed: boolean;
  /** The range when the pointer went down: the drag is measured from it. */
  origin: RangeValue;
  startX: number;
}

/**
 * A range's behavior with no view attached: its span on the timeline, held or
 * controlled, moved or resized by its body or its edges, drawn across empty
 * lane, and moved by the keys and inputs.
 */
export function createRangeController(initial: RangeOptions): RangeController {
  let options = initial;
  const pointers = createPointerLock();
  const limits = () => ({
    duration: options.duration,
    minLength: options.minLength,
  });

  let uncontrolled: RangeValue | undefined;
  // The range as the gesture under way left it: a controlled range that lags
  // behind must not pull it back mid-drag.
  let latest: RangeValue | null = null;
  let dragging = false;
  const listeners = new Set<() => void>();
  const notify = () => {
    for (const listener of listeners) {
      listener();
    }
  };

  const held = (): RangeValue =>
    normalizeRange(
      options.value ??
        uncontrolled ??
        options.defaultValue ?? [0, options.duration],
      options.duration
    );
  const current = (): RangeValue => latest ?? held();

  let snapshot: RangeSnapshot | null = null;
  const getSnapshot = (): RangeSnapshot => {
    const value = dragging && latest !== null ? latest : held();
    const disabled = options.disabled ?? false;
    if (
      snapshot &&
      snapshot.value[0] === value[0] &&
      snapshot.value[1] === value[1] &&
      snapshot.dragging === dragging &&
      snapshot.disabled === disabled
    ) {
      return snapshot;
    }
    snapshot = { disabled, dragging, value };
    return snapshot;
  };

  /** Proposes a range; keeps it unless canceled. */
  const change = (next: RangeValue, details: RangeChangeEventDetails) => {
    const [start, end] = current();
    if (next[0] === start && next[1] === end) {
      return false;
    }
    options.onValueChange?.(next, details);
    if (details.isCanceled) {
      return false;
    }
    latest = next;
    if (options.value === undefined) {
      uncontrolled = next;
    }
    notify();
    return true;
  };

  const commit = (value: RangeValue, details: RangeCommitEventDetails) => {
    options.onValueCommitted?.(value, details);
  };

  /** The limits of an edge: how far it can go before it meets the other one. */
  const edgeRange = (edge: "end" | "start"): readonly [number, number] => {
    const [start, end] = current();
    if (edge === "start") {
      return [0, Math.max(0, end - options.minLength)];
    }
    return [
      Math.min(options.duration, start + options.minLength),
      options.duration,
    ];
  };

  /** Moves the whole range so it starts at `target`, keeping its length. */
  const moveTo = (
    target: number,
    reason: "input-change" | "keyboard",
    event: Event
  ) => {
    if (options.disabled) {
      return;
    }
    const [start, end] = current();
    const span = end - start;
    const from = Math.min(Math.max(0, target), options.duration - span);
    const details = Object.assign(createChangeEventDetails(reason, event), {
      edge: "both" as const,
    }) as RangeChangeEventDetails;
    const next: RangeValue = [from, from + span];
    if (change(next, details)) {
      // The range just proposed: telling a view of it can redraw it from its own props before this reads `current()`.
      commit(next, {
        edge: "both",
        event,
        reason,
      } as RangeCommitEventDetails);
    }
  };

  /** Cmd/Ctrl + arrows: the end moves, the start stays, so the range grows or shrinks. */
  const resizeKey = (event: KeyboardEvent) => {
    const [start, end] = current();
    const length = end - start;
    const lengths: Record<string, number> = {
      ArrowDown: length / 2,
      ArrowLeft: length - options.step,
      ArrowRight: length + options.step,
      ArrowUp: length * 2,
    };
    const next = lengths[event.key];
    if (next === undefined) {
      return false;
    }
    setEdge("end", start + next, "keyboard", event);
    return true;
  };

  const keyDown: RangeController["keyDown"] = (event) => {
    if (options.disabled) {
      return false;
    }
    if (event.metaKey || event.ctrlKey) {
      return resizeKey(event);
    }
    const [start, end] = current();
    if (event.key === "ArrowUp" || event.key === "ArrowDown") {
      moveTo(
        start + (event.key === "ArrowUp" ? 1 : -1) * (end - start),
        "keyboard",
        event
      );
      return true;
    }
    const target = keyTargets(
      start,
      options.step,
      options.largeStep,
      event.shiftKey,
      [0, options.duration - (end - start)]
    )[event.key];
    if (target === undefined) {
      return false;
    }
    moveTo(target, "keyboard", event);
    return true;
  };

  const setEdge = (
    edge: "end" | "start",
    position: number,
    reason: "input-change" | "keyboard",
    event: Event
  ) => {
    const [min, max] = edgeRange(edge);
    const clamped = Math.min(max, Math.max(min, position));
    const [start, end] = current();
    const next: RangeValue =
      edge === "start" ? [clamped, end] : [start, clamped];
    const details = Object.assign(createChangeEventDetails(reason, event), {
      edge,
    }) as RangeChangeEventDetails;
    if (change(next, details)) {
      commit(next, { edge, event, reason } as RangeCommitEventDetails);
    }
  };

  const edgeKeyDown: RangeController["edgeKeyDown"] = (edge, event) => {
    if (options.disabled) {
      return false;
    }
    const [start, end] = current();
    const at = edge === "start" ? start : end;
    const target = keyTargets(
      at,
      options.step,
      options.largeStep,
      event.shiftKey,
      edgeRange(edge)
    )[event.key];
    if (target === undefined) {
      return false;
    }
    setEdge(edge, target, "keyboard", event);
    return true;
  };

  const edgeTypeAt: RangeController["edgeTypeAt"] = (edge, position, event) => {
    if (!options.disabled) {
      setEdge(edge, position, "input-change", event);
    }
  };

  /** How many units a pixel is along `lane`. */
  const perPixel = (lane: Element | null) => {
    if (options.zoom !== null) {
      return 1 / options.zoom;
    }
    const width = lane?.getBoundingClientRect().width ?? 0;
    return options.duration / Math.max(width, 1);
  };

  /** The grid applies unless Cmd/Ctrl is held: read from the pointer's own keys. */
  const valueAt = (lane: Element, event: PointerEvent) => {
    const raw = valueAtLane(
      lane,
      event.clientX,
      options.zoom,
      options.duration
    );
    return bypassesGrid(event)
      ? raw
      : snapToGrid(
          raw,
          withSnapRadius(options.grid, perPixel(lane) * SNAP_RADIUS_PX)
        );
  };

  const press: RangeController["press"] = (edge, event, handle, lane) => {
    if (options.disabled || event.button !== 0 || !pointers.claim(event)) {
      return;
    }
    if (edge === "both" && !options.movable) {
      return;
    }
    handle.setPointerCapture?.(event.pointerId);
    const gesture: RangeGesture = {
      changed: false,
      origin: current(),
      startX: event.clientX,
    };
    dragging = true;
    notify();
    pointers.follow(
      handle,
      event,
      (move) => {
        // Pixels become units along the lane, the same way a drag reads them.
        const units = perPixel(lane);
        const moved = move.clientX - gesture.startX;
        // Its end follows the pointer as drawn: a range drawn wider than it is changes faster than its handle moves.
        const least = options.minDrawnWidth ?? 0;
        const length = (gesture.origin[1] - gesture.origin[0]) / units;
        const delta =
          edge === "end" && least > 0 && units > 0
            ? (rangeWidthOfDrawn(
                drawnRangeWidth(length, least) + moved,
                least
              ) -
                length) *
              units
            : moved * units;
        // Its own edges are not places for the range to snap to.
        const grid: Grid = bypassesGrid(move)
          ? { offset: 0, step: 0 }
          : withSnapRadius(
              withoutSnapPoints(options.grid, gesture.origin),
              units * SNAP_RADIUS_PX
            );
        const next = snapRangeMove(gesture.origin, edge, delta, limits(), grid);
        const details = Object.assign(createChangeEventDetails("drag", move), {
          edge,
        }) as RangeChangeEventDetails;
        if (change(next, details)) {
          gesture.changed = true;
        }
      },
      (end) => {
        // Read before settling: the range falls back to the known value after.
        const committed = current();
        dragging = false;
        latest = null;
        notify();
        if (gesture.changed) {
          commit(committed, {
            edge,
            event: end,
            reason: "drag",
          } as RangeCommitEventDetails);
        }
      }
    );
  };

  const pressDraw: RangeController["pressDraw"] = (event, lane) => {
    if (
      options.disabled ||
      !options.drawable ||
      event.button !== 0 ||
      !pointers.claim(event) ||
      event.target !== lane
    ) {
      return;
    }
    lane.setPointerCapture?.(event.pointerId);
    const anchor = valueAt(lane, event);
    const drawTo = (pointer: PointerEvent, at: number) => {
      const from = Math.min(anchor, at);
      const to = Math.max(from + options.minLength, Math.max(anchor, at));
      const next = normalizeRange(
        [Math.min(from, options.duration - options.minLength), to],
        options.duration
      );
      return change(
        next,
        Object.assign(createChangeEventDetails("draw", pointer), {
          edge: "both" as const,
        }) as RangeChangeEventDetails
      );
    };
    dragging = true;
    notify();
    const gesture = { changed: drawTo(event, anchor) };
    pointers.follow(
      lane,
      event,
      (move) => {
        if (drawTo(move, valueAt(lane, move))) {
          gesture.changed = true;
        }
      },
      (end) => {
        const committed = current();
        dragging = false;
        latest = null;
        notify();
        if (gesture.changed) {
          commit(committed, {
            edge: "both",
            event: end,
            reason: "draw",
          } as RangeCommitEventDetails);
        }
      }
    );
  };

  return {
    edgeKeyDown,
    edgeRange,
    edgeTypeAt,
    getSnapshot,
    keyDown,
    moveTypeAt: (start, event) => moveTo(start, "input-change", event),
    press,
    pressDraw,
    setOptions: (next) => {
      options = next;
      // The props take over again on every render, unless a gesture is under way.
      if (!dragging) {
        latest = null;
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

import {
  createRangeController,
  type RangeController,
} from "./range-controller";
import {
  css,
  dispatch,
  type PrimitiveContext,
  type SlotDefinition,
} from "@ui-sdk/core";
import { flag, sourceOf, VISUALLY_HIDDEN } from "../primitive";
import { laneOf, placedOver } from "./layout";
import type {
  DescribePosition,
  TimelineApi,
  TimelinePublicState,
  TimelineState,
} from "./timeline";

/**
 * The ranges of the timeline: a stretch laid over a lane, such as a loop or a
 * selection. A range is named by its `range` prop and holds a controller of
 * its own; its edges and its input carry the same name, and what they report
 * goes through the Root, `onRangeChange` and `onRangeCommitted`, with the
 * name and the edge in the details.
 */

export type RangeValue = readonly [number, number];

/** The props every part of a range takes. */
export interface RangeRef {
  id?: string;
  /** The name of the range it belongs to. */
  range: string;
}

/** The props of the range part: its name, and what it holds. */
export interface RangeProps extends RangeRef {
  defaultValue?: RangeValue;
  disabled?: boolean;
  /** Whether dragging across empty lane draws a new range. @default false */
  drawable?: boolean;
  /** The least room the range is drawn with, in px. @default 0 */
  minDrawnWidth?: number;
  /** The shortest the range can be. Defaults to the grid step. */
  minLength?: number;
  /** Whether dragging the body, or the keys, moves the range. @default true */
  movable?: boolean;
  value?: RangeValue;
}

export interface RangePublicState extends TimelinePublicState {
  /** Whether a pointer is moving, resizing or drawing the range. */
  dragging: boolean;
}

export interface RangeEdgeState extends RangePublicState {
  edge: "end" | "start";
}

/** What a range's change reports. */
export interface RangeChangeDetails {
  cancel: () => void;
  edge: "both" | "end" | "start";
  event?: Event;
  /** The name of the range that moved. */
  range: string;
  reason: string;
  source?: string;
}

export interface RangeCommitDetails {
  edge: "both" | "end" | "start";
  event?: Event;
  range: string;
  reason: string;
}

type Slot<Props, Public = RangePublicState> = SlotDefinition<
  TimelineState,
  TimelineApi,
  Props,
  Public
>;

type InputSlot = Slot<
  RangeRef & { getAriaValueText?: DescribePosition },
  object
>;

/** The range slots, by name. */
export type RangeSlots = {
  range: Slot<RangeProps>;
  rangeEnd: Slot<RangeRef, RangeEdgeState>;
  rangeEndInput: InputSlot;
  rangeInput: InputSlot;
  rangeStart: Slot<RangeRef, RangeEdgeState>;
  rangeStartInput: InputSlot;
};

/** What the timeline's `api` gives the range parts. */
export interface RangeApi {
  /** The controller of the range named in `props`; the range part's own props give it its options. */
  rangeFor: (
    state: TimelineState,
    props: RangeProps | RangeRef,
    owner?: boolean
  ) => RangeController;
  /** What each range was given by its own part. */
  rangeProps: Map<string, RangeProps>;
}

const describeNumber = (value: number) => String(Math.round(value * 100) / 100);

export function createRangeApi(
  context: PrimitiveContext<any, any, any>,
  settings: () => {
    duration: number;
    grid: { offset: number; points?: readonly number[]; step: number };
    largeStep: number;
    step: number;
  },
  bump: () => void
): RangeApi {
  const controllers = new Map<string, RangeController>();
  const rangeProps = new Map<string, RangeProps>();
  const provisional = new Set<string>();
  /** The controller of a range: made once, and again when the range itself first binds after a part that started it. */
  const controllerFor = (name: string, options: object, owner: boolean) => {
    let controller = controllers.get(name);
    // A part that binds before the range itself starts the controller without what the range was given: the range starts it again, with it.
    if (controller && owner && provisional.has(name)) {
      provisional.delete(name);
      controller = undefined;
      queueMicrotask(bump);
    }
    if (controller) {
      if (owner) {
        controller.setOptions(options as never);
      }
    } else {
      controller = createRangeController(options as never);
      controller.subscribe(bump);
      controllers.set(name, controller);
      if (!owner) {
        provisional.add(name);
      }
    }
    return controller;
  };
  return {
    rangeFor: (state, props, owner = false) => {
      const name = String(props.range);
      const own = props as RangeProps;
      const { duration, grid, largeStep, step } = settings();
      if (owner) {
        rangeProps.set(name, own);
      }
      const options = {
        defaultValue: own.defaultValue,
        disabled: state.view.disabled || Boolean(own.disabled),
        drawable: own.drawable ?? false,
        duration,
        grid,
        largeStep,
        minDrawnWidth: own.minDrawnWidth ?? 0,
        minLength: own.minLength ?? (grid.step > 0 ? grid.step : step),
        movable: own.movable ?? true,
        onValueChange: (
          value: RangeValue,
          details: { cancel: () => void; event?: Event; reason: string }
        ) => {
          const { cancel, ...rest } = details;
          const source = sourceOf(details.event);
          if (
            dispatch(context, "onRangeChange", value, {
              ...rest,
              range: name,
              ...(source ? { source } : {}),
            })
          ) {
            cancel();
          }
        },
        onValueCommitted: (
          value: RangeValue,
          details: { event?: Event; reason: string }
        ) => {
          dispatch(context, "onRangeCommitted", value, {
            ...details,
            range: name,
          });
        },
        step,
        value: own.value,
        get zoom() {
          return context.store.get().frame.zoom as number | null;
        },
      };
      return controllerFor(name, options, owner);
    },
    rangeProps,
  };
}

const publicOf = (
  state: TimelineState,
  api: TimelineApi,
  props: RangeRef
): RangePublicState => ({
  disabled: api.rangeFor(state, props).getSnapshot().disabled,
  dragging: api.rangeFor(state, props).getSnapshot().dragging,
  fitted: state.view.fitted,
  scrubbing: state.view.scrubbing,
});

const attrsOf = (state: RangePublicState, range: string) => ({
  "data-disabled": flag(state.disabled),
  "data-dragging": flag(state.dragging),
  "data-fitted": flag(state.fitted),
  "data-range": range,
  "data-scrubbing": flag(state.scrubbing),
});

export function rangeSlots(slot: any) {
  /** A drag of `edge` from a part of the range: the press stops here, so the lane underneath takes none. */
  const press =
    (side: "both" | "end" | "start") =>
    (
      event: PointerEvent,
      {
        api,
        el,
        props,
        store,
      }: {
        api: TimelineApi;
        el: HTMLElement | undefined;
        props: RangeRef;
        store: { get: () => TimelineState };
      }
    ) => {
      if (event.button !== 0) {
        return;
      }
      event.stopPropagation();
      const controller = api.rangeFor(store.get(), props);
      const own = api.rangeProps.get(String(props.range));
      const enabled =
        !controller.getSnapshot().disabled &&
        (side !== "both" || (own?.movable ?? true));
      if (!(el && enabled)) {
        return;
      }
      event.preventDefault();
      if (side !== "both") {
        el.querySelector<HTMLInputElement>('input[type="range"]')?.focus({
          preventScroll: true,
        });
      }
      controller.press(side, event, el, laneOf(el));
    };

  const edge = (kind: "end" | "start") =>
    slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: RangeRef }
      ) => ({
        ...attrsOf(publicOf(state, api, props), String(props.range)),
        "data-edge": kind,
        style: css({ "touch-action": "none" }),
      }),
      on: { pointerdown: press(kind) },
      props: { range: "key" },
      state: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: RangeRef }
      ) => ({ ...publicOf(state, api, props), edge: kind }),
    });

  const edgeInput = (kind: "end" | "start") =>
    slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: any }
      ) => {
        const controller = api.rangeFor(state, props);
        const view = controller.getSnapshot();
        const current = kind === "start" ? view.value[0] : view.value[1];
        const [min, max] = controller.edgeRange(kind);
        return {
          "aria-valuetext": (props.getAriaValueText ?? describeNumber)(
            current,
            state.duration
          ),
          disabled: flag(view.disabled),
          max: String(max),
          min: String(min),
          step: "any",
          style: css(VISUALLY_HIDDEN),
          type: "range",
          value: String(current),
        };
      },
      on: {
        change: (
          event: Event,
          {
            api,
            el,
            props,
            store,
          }: {
            api: TimelineApi;
            el: HTMLElement | undefined;
            props: RangeRef;
            store: { get: () => TimelineState };
          }
        ) =>
          api
            .rangeFor(store.get(), props)
            .edgeTypeAt(kind, Number((el as HTMLInputElement).value), event),
        keydown: (
          event: KeyboardEvent,
          {
            api,
            props,
            store,
          }: {
            api: TimelineApi;
            props: RangeRef;
            store: { get: () => TimelineState };
          }
        ) => {
          if (api.rangeFor(store.get(), props).edgeKeyDown(kind, event)) {
            event.preventDefault();
          }
        },
      },
      props: { getAriaValueText: "value", range: "key" },
    });

  return {
    range: slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: RangeProps }
      ) => {
        const view = api.rangeFor(state, props, true).getSnapshot();
        const [start, end] = view.value;
        const placed = placedOver(start, end - start);
        const minDrawn = props.minDrawnWidth ?? 0;
        return {
          ...attrsOf(
            {
              disabled: view.disabled,
              dragging: view.dragging,
              fitted: state.view.fitted,
              scrubbing: state.view.scrubbing,
            },
            String(props.range)
          ),
          style: css({
            ...placed,
            ...(minDrawn > 0
              ? {
                  width: `max(${placed.width}, calc(${minDrawn}px + ${placed.width} / 2))`,
                }
              : {}),
            "touch-action": "none",
          }),
        };
      },
      // Drawing a new range across empty lane: the press is listened for on the lane itself, which the range does not render.
      bind: (el: HTMLElement, part: any) => {
        const handleDown = (event: PointerEvent) => {
          const given = part.props as RangeProps;
          const controller = part.api.rangeFor(part.store.get(), given, true);
          const lane = event.currentTarget as HTMLElement;
          if (given.drawable && !controller.getSnapshot().disabled) {
            controller.pressDraw(event, lane);
          }
        };
        let lane: HTMLElement | null = null;
        let disposed = false;
        // The lane is looked for once the range is in the document: a framework may bind it before.
        queueMicrotask(() => {
          lane = laneOf(el);
          if (!disposed) {
            lane?.addEventListener("pointerdown", handleDown);
          }
        });
        return () => {
          disposed = true;
          lane?.removeEventListener("pointerdown", handleDown);
        };
      },
      on: { pointerdown: press("both") },
      props: {
        defaultValue: "value",
        disabled: "boolean",
        drawable: "boolean",
        minDrawnWidth: "number",
        minLength: "number",
        movable: "boolean",
        range: "key",
        value: "value",
      },
      state: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: RangeProps }
      ) => ({
        disabled: api.rangeFor(state, props, true).getSnapshot().disabled,
        dragging: api.rangeFor(state, props, true).getSnapshot().dragging,
        fitted: state.view.fitted,
        scrubbing: state.view.scrubbing,
      }),
    }),
    rangeEnd: edge("end"),
    rangeEndInput: edgeInput("end"),
    // The range's own native input: it moves the range from the keyboard and carries its name.
    rangeInput: slot({
      attrs: (
        state: TimelineState,
        { api, props }: { api: TimelineApi; props: any }
      ) => {
        const view = api.rangeFor(state, props).getSnapshot();
        const [start, end] = view.value;
        const describe = props.getAriaValueText ?? describeNumber;
        return {
          "aria-valuetext": `${describe(start, state.duration)} to ${describe(end, state.duration)}`,
          disabled: flag(view.disabled),
          max: String(Math.max(0, state.duration - (end - start))),
          min: "0",
          step: "any",
          style: css(VISUALLY_HIDDEN),
          type: "range",
          value: String(start),
        };
      },
      on: {
        change: (
          event: Event,
          {
            api,
            el,
            props,
            store,
          }: {
            api: TimelineApi;
            el: HTMLElement | undefined;
            props: RangeRef;
            store: { get: () => TimelineState };
          }
        ) =>
          api
            .rangeFor(store.get(), props)
            .moveTypeAt(Number((el as HTMLInputElement).value), event),
        keydown: (
          event: KeyboardEvent,
          {
            api,
            props,
            store,
          }: {
            api: TimelineApi;
            props: RangeRef;
            store: { get: () => TimelineState };
          }
        ) => {
          if (api.rangeFor(store.get(), props).keyDown(event)) {
            event.preventDefault();
          }
        },
      },
      props: { getAriaValueText: "value", range: "key" },
    }),
    rangeStart: edge("start"),
    rangeStartInput: edgeInput("start"),
  } as RangeSlots;
}

/** A point held still through a zoom: a value, and how far from the viewport's start it sits, in px. */
export interface ZoomAnchor {
  offset: number;
  value: number;
}

/** Keeps `zoom` within its bounds; anything that is not a positive number is refused. */
export function clampZoom(
  zoom: number,
  minZoom: number,
  maxZoom: number
): number | null {
  if (!(Number.isFinite(zoom) && zoom > 0)) {
    return null;
  }
  return Math.min(maxZoom, Math.max(minZoom, zoom));
}

/**
 * Where the viewport must scroll so `anchor.value` stays `anchor.offset` px
 * from its start at the new zoom. `origin` is where value 0 sits in the
 * scrolled content, in px: past a column of headers, for instance.
 */
export function anchoredScroll(
  anchor: ZoomAnchor,
  zoom: number,
  origin: number
): number {
  return Math.max(0, origin + anchor.value * zoom - anchor.offset);
}

/** The value under a point `offset` px from the viewport's start. */
export function valueAtOffset(
  offset: number,
  scrollStart: number,
  zoom: number,
  origin: number
): number {
  return (scrollStart + offset - origin) / zoom;
}

import { clamp } from "@ui-sdk/core/number";
import {
  type ChangeEventDetails,
  type CommitEventDetails,
  createChangeEventDetails,
  createPointerLock,
} from "../primitive";

/** What `onHeightChange` receives with each resize of a track: the reason (`"drag"`, `"keyboard"`, `"input-change"` or `"double-click"`), the event, and `cancel()` to refuse it. */
export type TrackHeightChangeEventDetails =
  | ChangeEventDetails<"drag", PointerEvent>
  | ChangeEventDetails<"keyboard", KeyboardEvent>
  | ChangeEventDetails<"input-change", Event>
  | ChangeEventDetails<"double-click", MouseEvent>;
/** What `onHeightCommitted` receives once a resize ends: the reason and the event behind it. */
export type TrackHeightCommitEventDetails =
  | CommitEventDetails<"drag", PointerEvent>
  | CommitEventDetails<"keyboard", KeyboardEvent>
  | CommitEventDetails<"input-change", Event>
  | CommitEventDetails<"double-click", MouseEvent>;

/** The options of `createTrackController`: the height its parent holds, its bounds and steps, how to measure it, and the callbacks. */
export interface TrackOptions {
  /** The height in px, or `undefined` for the row to share what room there is. */
  height?: number;
  largeStep: number;
  max: number;
  /** Measures the row as drawn: what a track without a height is, while it is resized. */
  measure: () => number;
  min: number;
  onHeightChange?: (
    height: number | undefined,
    details: TrackHeightChangeEventDetails
  ) => void;
  onHeightCommitted?: (
    height: number | undefined,
    details: TrackHeightCommitEventDetails
  ) => void;
  step: number;
}

/** What a view draws a track's resize handle from: whether a resize is under way. */
export interface TrackSnapshot {
  /** Whether a pointer is resizing the track. */
  resizing: boolean;
}

/** What `createTrackController` returns: the snapshot to draw from, and the presses, keys, typed values and reset that ask for a height. */
export interface TrackController {
  getSnapshot: () => TrackSnapshot;
  /** Handles a key on the handle's input: the arrows move by a step (Down is taller), Page keys by a large one, Home and End go to the limits. Returns `true` when the handle takes the key. */
  keyDown: (event: KeyboardEvent) => boolean;
  /** Starts a drag from `handle`: the height moves with the pointer, measured from where it was taken. */
  press: (event: PointerEvent, handle: Element) => void;
  /** Gives the height up, so the row shares the room again. */
  reset: (event: MouseEvent) => void;
  /** Asks for a new height: a drag, a key or an input. Returns `true` when the height is applied. */
  resize: (height: number, details: TrackHeightChangeEventDetails) => boolean;
  setOptions: (options: TrackOptions) => void;
  subscribe: (listener: () => void) => () => void;
  /** Sets the height from an input, committing it when it applies. */
  typeAt: (value: number, event: Event) => void;
}

/**
 * A track's height, with no view attached: what a drag, a key, an input or a
 * double click asks of it. The track holds no height of its own: the parent
 * sets it, and the controller reports each request.
 */
export function createTrackController(initial: TrackOptions): TrackController {
  let options = initial;
  const pointers = createPointerLock();
  let resizing = false;
  const listeners = new Set<() => void>();
  const notify = () => {
    for (const listener of listeners) {
      listener();
    }
  };

  /** What the track is now: the height it was given, or what it measures. */
  const current = () => options.height ?? options.measure();

  let snapshot: TrackSnapshot | null = null;
  const getSnapshot = (): TrackSnapshot => {
    if (snapshot?.resizing === resizing) {
      return snapshot;
    }
    snapshot = { resizing };
    return snapshot;
  };

  const resize: TrackController["resize"] = (height, details) => {
    const clamped = clamp(height, options.min, options.max);
    if (clamped === options.height) {
      return false;
    }
    options.onHeightChange?.(clamped, details);
    return !details.isCanceled;
  };

  const commit = (
    height: number | undefined,
    details: TrackHeightCommitEventDetails
  ) => {
    options.onHeightCommitted?.(height, details);
  };

  const reset: TrackController["reset"] = (event) => {
    if (options.height === undefined) {
      return;
    }
    const details = createChangeEventDetails(
      "double-click",
      event
    ) as TrackHeightChangeEventDetails;
    options.onHeightChange?.(undefined, details);
    if (!details.isCanceled) {
      commit(undefined, {
        event,
        reason: "double-click",
      } as TrackHeightCommitEventDetails);
    }
  };

  /** Asks for `to` from a key or an input, committing it when it applies. */
  const setHeight = (
    to: number,
    reason: "input-change" | "keyboard",
    event: Event
  ) => {
    const details = createChangeEventDetails(
      reason,
      event
    ) as TrackHeightChangeEventDetails;
    if (resize(to, details)) {
      commit(clamp(to, options.min, options.max), {
        event,
        reason,
      } as TrackHeightCommitEventDetails);
    }
  };

  const press: TrackController["press"] = (event, handle) => {
    if (event.button !== 0 || !pointers.claim(event)) {
      return;
    }
    handle.setPointerCapture?.(event.pointerId);
    const from = current();
    const started: {
      changed: boolean;
      from: number;
      latest: number;
      startY: number;
    } = {
      changed: false,
      from,
      latest: from,
      startY: event.clientY,
    };
    resizing = true;
    notify();
    pointers.follow(
      handle,
      event,
      (move) => {
        const next = started.from + move.clientY - started.startY;
        const details = createChangeEventDetails(
          "drag",
          move
        ) as TrackHeightChangeEventDetails;
        if (resize(next, details)) {
          started.changed = true;
          started.latest = clamp(next, options.min, options.max);
        }
      },
      (end) => {
        resizing = false;
        notify();
        if (started.changed) {
          commit(started.latest, {
            event: end,
            reason: "drag",
          } as TrackHeightCommitEventDetails);
        }
      }
    );
  };

  const keyDown: TrackController["keyDown"] = (event) => {
    const now = current();
    const targets: Record<string, number> = {
      ArrowDown: now + options.step,
      ArrowLeft: now - options.step,
      ArrowRight: now + options.step,
      ArrowUp: now - options.step,
      End: options.max,
      Home: options.min,
      PageDown: now + options.largeStep,
      PageUp: now - options.largeStep,
    };
    const to = targets[event.key];
    if (to === undefined) {
      return false;
    }
    setHeight(to, "keyboard", event);
    return true;
  };

  return {
    getSnapshot,
    keyDown,
    press,
    reset,
    resize,
    setOptions: (next) => {
      options = next;
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    typeAt: (value, event) => setHeight(value, "input-change", event),
  };
}

import { createChangeEventDetails } from "../primitive";
import type { TimelineZoomChangeEventDetails } from "./position";
import { valueAtOffset } from "./scale";

/**
 * How far one pixel of wheel delta zooms, as an exponent. A trackpad's pinch
 * comes as the wheel with Ctrl, about -100 ln s of delta for a spread of s:
 * the zoom goes by s², so a few pinches go from a whole timeline to its finest.
 */
export const WHEEL_ZOOM_SENSITIVITY = 0.02;

/** The most one frame zooms by, as an exponent: twice in or half out, so a mouse's notch never jumps further. */
const MOST_PER_FRAME = Math.LN2;

/** Pixels in a line and a page of wheel delta, for a wheel that counts in those. */
const DELTA_PX = [1, 16, 400] as const;

/** The options of `createWheelZoom`: the timeline's length, the zoom as drawn, where its start sits, and the function that applies a zoom. */
export interface WheelZoomOptions {
  disabled?: boolean;
  /** px per unit as drawn: the zoom, or what fitting the width gives. */
  drawnZoom: () => number;
  duration: number;
  /** Where value 0 sits in the scrolled content, in px. */
  origin: () => number;
  /** Clamps and proposes a zoom held still around the anchor; returns whether it was applied. */
  zoomTo: (
    next: number,
    details: TimelineZoomChangeEventDetails,
    anchor: { offset: number; value: number }
  ) => boolean;
}

/** What `createWheelZoom` returns: the wheel handler, `setOptions`, and `dispose`. */
export interface WheelZoomController {
  /** Drops the zoom that waits for the next frame. */
  dispose: () => void;
  setOptions: (options: WheelZoomOptions) => void;
  /** Takes a wheel event over the viewport: Cmd/Ctrl zooms, a bare wheel is left to scroll. Returns `true` when it zooms. */
  wheel: (event: WheelEvent, element: HTMLElement) => boolean;
}

/**
 * A wheel zoom around the pointer. A trackpad sends wheel events faster than
 * frames, and each zoom lays the whole timeline out again: the deltas, in
 * pixels whatever the wheel counts in, are added up and applied once per
 * frame, anchored on where the pointer was.
 */
export function createWheelZoom(
  initial: WheelZoomOptions
): WheelZoomController {
  let options = initial;
  let pending: {
    delta: number;
    event: WheelEvent;
    element: HTMLElement;
  } | null = null;
  let frame = 0;

  const flush = () => {
    frame = 0;
    const batch = pending;
    pending = null;
    if (!batch) {
      return;
    }
    const current = options.drawnZoom();
    if (!(current > 0)) {
      return;
    }
    const { element, event } = batch;
    const offset = event.clientX - element.getBoundingClientRect().left;
    const value = valueAtOffset(
      offset,
      element.scrollLeft,
      current,
      options.origin()
    );
    const exponent = Math.min(
      MOST_PER_FRAME,
      Math.max(-MOST_PER_FRAME, -batch.delta * WHEEL_ZOOM_SENSITIVITY)
    );
    options.zoomTo(
      current * Math.exp(exponent),
      createChangeEventDetails(
        "wheel",
        event
      ) as TimelineZoomChangeEventDetails,
      { offset, value: Math.min(options.duration, Math.max(0, value)) }
    );
  };

  return {
    dispose: () => {
      cancelAnimationFrame(frame);
      frame = 0;
      pending = null;
    },
    setOptions: (next) => {
      options = next;
    },
    wheel: (event, element) => {
      if (!(event.ctrlKey || event.metaKey) || options.disabled) {
        return false;
      }
      event.preventDefault();
      pending = {
        delta:
          (pending?.delta ?? 0) +
          event.deltaY * (DELTA_PX[event.deltaMode] ?? 1),
        element,
        event,
      };
      if (!frame) {
        frame = requestAnimationFrame(flush);
      }
      return true;
    },
  };
}

import { createParts } from "@ui-sdk/vue/primitive";
import { defineComponent, h } from "vue";
import { timeline } from "./timeline";

/** Which element each part is. */
const parts = createParts(timeline, {
  clip: "div",
  clipFadeIn: "svg",
  clipFadeInHandle: "div",
  clipFadeInInput: "input",
  clipFadeOut: "svg",
  clipFadeOutHandle: "div",
  clipFadeOutInput: "input",
  clipHeader: "div",
  clipInput: "input",
  clipTrimEnd: "div",
  clipTrimEndInput: "input",
  clipTrimStart: "div",
  clipTrimStartInput: "input",
  lane: "div",
  mark: "div",
  navigator: "div",
  navigatorEnd: "div",
  navigatorEndInput: "input",
  navigatorStart: "div",
  navigatorStartInput: "input",
  navigatorWindow: "div",
  navigatorWindowInput: "input",
  range: "div",
  rangeEnd: "div",
  rangeEndInput: "input",
  rangeInput: "input",
  rangeStart: "div",
  rangeStartInput: "input",
  playhead: "div",
  root: "div",
  ruler: "div",
  rulerInput: "input",
  track: "div",
  trackHeader: "div",
  trackResizeHandle: "div",
  trackResizeInput: "input",
  viewport: "div",
});

const NAMING = ["aria-describedby", "aria-label", "aria-labelledby"] as const;

/** The accessible name given to a part goes to the input it holds. */
const nameOf = (attrs: Record<string, unknown>) => {
  const naming: Record<string, unknown> = {};
  const rest: Record<string, unknown> = { ...attrs };
  for (const key of NAMING) {
    naming[key] = rest[key];
    delete rest[key];
  }
  return { naming, rest };
};

/**
 * The lane that moves the position: a press jumps to the pointer and a drag
 * scrubs, on the grid unless Cmd/Ctrl is held. It holds the native
 * `<input type="range">` that takes focus and the keys and carries the name.
 */
const Ruler = defineComponent(
  (
    props: { getAriaValueText?: (value: number, duration: number) => string },
    { attrs, slots }
  ) =>
    () => {
      const { naming, rest } = nameOf(attrs);
      return h(parts.Ruler, rest as never, {
        default: (scope: object) => [
          slots.default?.(scope),
          h(parts.RulerInput, {
            ...naming,
            getAriaValueText: props.getAriaValueText,
          } as never),
        ],
      });
    },
  { inheritAttrs: false, name: "TimelineRuler", props: ["getAriaValueText"] }
);

/** Sets the track's height: by dragging, or from the keyboard through its native input. A double-click gives the height up. */
const TrackResizeHandle = defineComponent(
  (props: { track: string }, { attrs, slots }) =>
    () => {
      const { naming, rest } = nameOf(attrs);
      return h(
        parts.TrackResizeHandle,
        { ...rest, track: props.track } as never,
        {
          default: (scope: object) => [
            slots.default?.(scope),
            h(parts.TrackResizeInput, {
              ...naming,
              track: props.track,
            } as never),
          ],
        }
      );
    },
  {
    inheritAttrs: false,
    name: "TimelineTrackResizeHandle",
    props: ["track"],
  }
);

/** A point of interest at a `value`. With `movable`, a drag or the arrows move it. The `mark` name defaults to the value. */
const Mark = defineComponent(
  (props: { mark?: string; value: number }, { attrs, slots }) =>
    () =>
      h(
        parts.Mark,
        {
          ...attrs,
          mark: props.mark ?? String(props.value),
          value: props.value,
        } as never,
        slots
      ),
  { inheritAttrs: false, name: "TimelineMark", props: ["mark", "value"] }
);

/**
 * A stretch of a source laid on a lane: a recording, a pattern. Its parts
 * (the header, the handles, the fades) take the same `clip` name. Its own
 * native `<input type="range">` moves it from the keyboard and carries its
 * name, unless it is not `movable`.
 */
const Clip = defineComponent(
  (
    props: {
      clip: string;
      getAriaValueText?: (value: number, duration: number) => string;
      movable?: boolean;
    },
    { attrs, slots }
  ) =>
    () => {
      const { naming, rest } = nameOf(attrs);
      const movable = props.movable ?? true;
      return h(parts.Clip, { ...rest, clip: props.clip, movable } as never, {
        default: (scope: object) => [
          slots.default?.(scope),
          movable
            ? h(parts.ClipInput, {
                ...naming,
                clip: props.clip,
                getAriaValueText: props.getAriaValueText,
              } as never)
            : null,
        ],
      });
    },
  {
    inheritAttrs: false,
    name: "TimelineClip",
    props: ["clip", "getAriaValueText", "movable"],
  }
);

/** An edge of a clip with the input it holds: a trim handle or a fade handle. */
const edged = (
  name: string,
  pick: (edge: string) => { handle: object; input: object }
) =>
  defineComponent(
    (
      props: {
        clip: string;
        edge: string;
        getAriaValueText?: (value: number, duration: number) => string;
      },
      { attrs, slots }
    ) =>
      () => {
        const { naming, rest } = nameOf(attrs);
        const { handle, input } = pick(props.edge);
        return h(handle as never, { ...rest, clip: props.clip } as never, {
          default: (scope: object) => [
            slots.default?.(scope),
            h(
              input as never,
              {
                ...naming,
                clip: props.clip,
                getAriaValueText: props.getAriaValueText,
              } as never
            ),
          ],
        });
      },
    {
      inheritAttrs: false,
      name,
      props: ["clip", "edge", "getAriaValueText"],
    }
  );

/** Trims one edge of the clip, by dragging or from the keyboard through its native input: it moves where in the source the clip begins instead of stretching it. */
const ClipHandle = edged("TimelineClipHandle", (edge) =>
  edge === "start"
    ? { handle: parts.ClipTrimStart, input: parts.ClipTrimStartInput }
    : { handle: parts.ClipTrimEnd, input: parts.ClipTrimEndInput }
);

/** Sets one fade of the clip, by dragging or from the keyboard through its native input. A double click, or Enter, steps its shape. */
const ClipFadeHandle = edged("TimelineClipFadeHandle", (edge) =>
  edge === "in"
    ? { handle: parts.ClipFadeInHandle, input: parts.ClipFadeInInput }
    : { handle: parts.ClipFadeOutHandle, input: parts.ClipFadeOutInput }
);

/** Shades a fade of the clip: its curve, in a 1 by 1 box. Style its `color` for the line, and `--clip-fade-shade` for the fill. */
const ClipFade = defineComponent(
  (props: { clip: string; edge: "in" | "out" }, { attrs }) =>
    () =>
      h(
        props.edge === "in" ? parts.ClipFadeIn : parts.ClipFadeOut,
        { ...attrs, clip: props.clip } as never,
        {
          default: ({ state }: { state: { fill: string; line: string } }) => [
            h("path", {
              d: state.fill,
              style: { fill: "var(--clip-fade-shade, currentColor)" },
            }),
            h("path", {
              d: state.line,
              fill: "none",
              stroke: "currentColor",
              "stroke-width": 1.5,
              style: { vectorEffect: "non-scaling-stroke" },
            }),
          ],
        }
      ),
  { inheritAttrs: false, name: "TimelineClipFade", props: ["clip", "edge"] }
);

/** The stretch the viewport shows, inside the navigator: dragging it scrolls. Its native input moves it from the keyboard. */
const NavigatorWindow = defineComponent(
  (
    props: { getAriaValueText?: (value: number, duration: number) => string },
    { attrs, slots }
  ) =>
    () => {
      const { naming, rest } = nameOf(attrs);
      return h(parts.NavigatorWindow, rest as never, {
        default: (scope: object) => [
          slots.default?.(scope),
          h(parts.NavigatorWindowInput, {
            ...naming,
            getAriaValueText: props.getAriaValueText,
          } as never),
        ],
      });
    },
  {
    inheritAttrs: false,
    name: "TimelineNavigatorWindow",
    props: ["getAriaValueText"],
  }
);

/** An edge with the input it holds, for the navigator and for a range. */
const bordered = (
  name: string,
  pick: (edge: string) => { handle: object; input: object },
  keyed?: string
) =>
  defineComponent(
    (
      props: {
        edge: string;
        getAriaValueText?: (value: number, duration: number) => string;
        range?: string;
      },
      { attrs, slots }
    ) =>
      () => {
        const { naming, rest } = nameOf(attrs);
        const { handle, input } = pick(props.edge);
        const own = keyed ? { [keyed]: props.range } : {};
        return h(handle as never, { ...rest, ...own } as never, {
          default: (scope: object) => [
            slots.default?.(scope),
            h(
              input as never,
              {
                ...naming,
                ...own,
                getAriaValueText: props.getAriaValueText,
              } as never
            ),
          ],
        });
      },
    {
      inheritAttrs: false,
      name,
      props: ["edge", "getAriaValueText", "range"],
    }
  );

/** An edge of the navigator's window: dragging it zooms, holding the other edge still. */
const NavigatorHandle = bordered("TimelineNavigatorHandle", (edge) =>
  edge === "start"
    ? { handle: parts.NavigatorStart, input: parts.NavigatorStartInput }
    : { handle: parts.NavigatorEnd, input: parts.NavigatorEndInput }
);

/** Resizes one edge of a range, by dragging or from the keyboard through its native input. */
const RangeHandle = bordered(
  "TimelineRangeHandle",
  (edge) =>
    edge === "start"
      ? { handle: parts.RangeStart, input: parts.RangeStartInput }
      : { handle: parts.RangeEnd, input: parts.RangeEndInput },
  "range"
);

/**
 * A stretch laid over a lane, such as a loop or a selection. Its edges take
 * the same `range` name. Its own native `<input type="range">` moves it from
 * the keyboard and carries its name, unless it is not `movable`.
 */
const Range = defineComponent(
  (
    props: {
      getAriaValueText?: (value: number, duration: number) => string;
      movable?: boolean;
      range: string;
    },
    { attrs, slots }
  ) =>
    () => {
      const { naming, rest } = nameOf(attrs);
      const movable = props.movable ?? true;
      return h(parts.Range, { ...rest, movable, range: props.range } as never, {
        default: (scope: object) => [
          slots.default?.(scope),
          movable
            ? h(parts.RangeInput, {
                ...naming,
                getAriaValueText: props.getAriaValueText,
                range: props.range,
              } as never)
            : null,
        ],
      });
    },
  {
    inheritAttrs: false,
    name: "TimelineRange",
    props: ["getAriaValueText", "movable", "range"],
  }
);

export const Timeline = {
  Clip,
  ClipFade,
  ClipFadeHandle,
  ClipHandle,
  ClipHeader: parts.ClipHeader,
  Lane: parts.Lane,
  Mark,
  Navigator: parts.Navigator,
  NavigatorHandle,
  NavigatorWindow,
  Playhead: parts.Playhead,
  Range,
  RangeHandle,
  Root: parts.Root,
  Ruler,
  Track: parts.Track,
  TrackHeader: parts.TrackHeader,
  TrackResizeHandle,
  Viewport: parts.Viewport,
};
